(() => {
 const root=document.getElementById("haView"); if(!root || root.dataset.ready==="1") return; root.dataset.ready="1";
 const topics=[
  ["Anatomy & Physiology","10%","Body systems: integumentary, skeletal, muscular, nervous, endocrine, blood, cardiovascular, lymphatic/immunity, digestive, respiratory, urinary, reproductive systems and growth.","शरीरका प्रणाली, तिनको बनावट, काम, रक्तसञ्चार, श्वासप्रश्वास, पाचन, उत्सर्जन, प्रजनन र वृद्धि-विकास।"],
  ["Community Health","25%","Health education and promotion; environmental health; PHC and family health; epidemiology and disease control; nutrition; community diagnosis; health management.","स्वास्थ्य शिक्षा, वातावरणीय स्वास्थ्य, प्राथमिक स्वास्थ्य सेवा, परिवार स्वास्थ्य, महामारी विज्ञान, रोग नियन्त्रण, पोषण, समुदाय निदान र स्वास्थ्य व्यवस्थापन।"],
  ["General Medicine","25%","Clinical methods; systemic diseases; pediatrics and neonatology; skin diseases; sexually transmitted infections; psychiatry.","इतिहास लिने र शारीरिक परीक्षण, विभिन्न प्रणालीका रोग, बाल तथा नवजात स्वास्थ्य, छालाका रोग, यौनसञ्चारित संक्रमण र मानसिक स्वास्थ्य।"],
  ["Pharmacology & Pharmacy","10%","Clinical pharmacology, common drug groups, rational drug use, pharmacokinetics/dynamics, dispensing, labeling, inventory and preparations.","औषधिको प्रभाव र शरीरमा हुने प्रक्रिया, सामान्य औषधि समूह, विवेकपूर्ण औषधि प्रयोग, भण्डारण, लेबल, वितरण र औषधि तयारी।"],
  ["General Surgery","25%","Basic surgery; first aid and emergency care; obstetrics and gynecology; eye, ENT and oral health.","सामान्य शल्यचिकित्सा, प्राथमिक उपचार, आकस्मिक सेवा, प्रसूति तथा स्त्रीरोग, आँखा, कान-नाक-घाँटी र मुख स्वास्थ्य।"],
  ["Clinical Pathology","5%","Biochemistry, microbiology, parasitology, hematology, blood collection and common laboratory principles.","जैवरसायन, सूक्ष्मजीव विज्ञान, परजीवी विज्ञान, रक्तविज्ञान, रगत संकलन र प्रयोगशाला परीक्षणका आधार।"]
 ];
 const notes=[
 ["1. Clinical history taking","A structured history includes presenting complaint, history of present illness, past medical/surgical history, medication and allergy history, family and social history, and review of systems. Use open questions first, then clarify onset, duration, severity, associated symptoms and red flags.","व्यवस्थित इतिहासमा मुख्य समस्या, हालको रोगको विवरण, पुराना रोग/शल्यक्रिया, औषधि तथा एलर्जी, पारिवारिक/सामाजिक इतिहास र प्रणालीगत समीक्षा पर्छ। पहिले खुला प्रश्न सोध्नुहोस्; त्यसपछि सुरु भएको समय, अवधि, गम्भीरता र चेतावनी संकेत बुझ्नुहोस्।"],
 ["2. General physical examination","Assess general appearance, consciousness, hydration, pallor, jaundice, cyanosis, clubbing, edema, lymph nodes and vital signs. Interpret findings in context; repeat unexpected measurements and document units.","सामान्य परीक्षणमा देखावट, चेतना, पानीको अवस्था, रक्तअल्पताको फिक्कापन, जन्डिस, नीलोपन, औँलाको clubbing, सुन्निनु, lymph node र vital signs जाँचिन्छ। असामान्य नतिजा पुनः जाँचेर एकाइ सहित लेख्नुहोस्।"],
 ["3. Vital signs","Core vital signs include temperature, pulse, respiratory rate, blood pressure and oxygen saturation when indicated. Correct cuff size, patient position, rest period and technique improve accuracy.","मुख्य vital signs तापक्रम, नाडी, श्वासदर, रक्तचाप र आवश्यकताअनुसार oxygen saturation हुन्। सही cuff, बिरामीको अवस्था, आराम अवधि र विधिले मापन शुद्ध बनाउँछ।"],
 ["4. Cardiovascular overview","The heart pumps blood through pulmonary and systemic circulation. Assess chest pain, dyspnea, palpitations, syncope, edema and relevant risk factors. Acute chest pain with instability requires urgent emergency assessment.","मुटुले pulmonary र systemic circulation मार्फत रगत पम्प गर्छ। छाती दुखाइ, सास फेर्न गाह्रो, धड्कन, बेहोसी, सुन्निनु र जोखिम जाँच्नुहोस्। अस्थिर अवस्थासहितको तीव्र छाती दुखाइमा तुरुन्त आकस्मिक मूल्याङ्कन आवश्यक हुन्छ।"],
 ["5. Respiratory overview","Assess cough, sputum, breathlessness, wheeze, chest pain and respiratory effort. Respiratory rate and oxygen saturation help assess severity. Severe distress, cyanosis or altered consciousness are emergency signs.","खोकी, खकार, सास फेर्न गाह्रो, wheeze, छाती दुखाइ र श्वास प्रयास जाँच्नुहोस्। श्वासदर र oxygen saturation ले गम्भीरता बुझ्न मद्दत गर्छ। अत्यधिक सास कष्ट, नीलोपन वा चेतना परिवर्तन आकस्मिक संकेत हुन्।"],
 ["6. Gastrointestinal and hepatic symptoms","Ask about appetite, nausea, vomiting, abdominal pain, bowel habit, blood in stool, jaundice and weight change. Severe abdominal pain, persistent vomiting, GI bleeding or peritonism need urgent evaluation.","भोक, वाकवाकी, बान्ता, पेट दुखाइ, दिसाको बानी, दिसामा रगत, जन्डिस र तौल परिवर्तन सोध्नुहोस्। तीव्र पेट दुखाइ, लगातार बान्ता, पाचननलीबाट रक्तस्राव वा peritonism मा तत्काल जाँच चाहिन्छ।"],
 ["7. Diabetes mellitus","Diabetes is a metabolic disorder characterized by persistent hyperglycemia due to impaired insulin secretion, insulin action, or both. Diagnosis uses validated plasma glucose or HbA1c criteria; symptoms alone are insufficient.","मधुमेह insulin उत्पादन वा काममा समस्या हुँदा रगतमा glucose लगातार बढ्ने अवस्था हो। निदानका लागि मान्य plasma glucose वा HbA1c मापदण्ड प्रयोग हुन्छ; लक्षण मात्र पर्याप्त हुँदैन।"],
 ["8. Hypertension","Hypertension is persistently elevated blood pressure. Confirm with properly performed repeated measurements and follow current national guidance. Assess cardiovascular risk, adherence, lifestyle and evidence of target-organ damage.","उच्च रक्तचाप भनेको रक्तचाप लगातार बढिरहने अवस्था हो। सही विधिले पटक-पटक मापन गरी हालको राष्ट्रिय निर्देशिका अनुसार पुष्टि गर्नुपर्छ। मुटु-रक्तनली जोखिम, औषधि नियमितता, जीवनशैली र अंगमा क्षति जाँच्नुहोस्।"],
 ["9. Pediatric assessment","Assess age-specific growth, feeding, immunization, development, hydration, danger signs and caregiver concerns. Use the current national IMNCI/IMCI chart and refer urgently for general danger signs.","बालबालिकामा उमेरअनुसार वृद्धि, खाना, खोप, विकास, पानीको अवस्था, खतरा संकेत र अभिभावकको चिन्ता जाँच्नुहोस्। हालको राष्ट्रिय IMNCI/IMCI चार्ट प्रयोग गरी सामान्य खतरा संकेत भए तुरुन्त referral गर्नुहोस्।"],
 ["10. Neonatal danger signs","Poor feeding, convulsions, fast or difficult breathing, fever or hypothermia, reduced movement and severe jaundice may indicate serious neonatal illness. Stabilize within scope and arrange urgent referral.","दूध नखानु, दौरा, छिटो वा गाह्रो श्वास, ज्वरो वा शरीर चिसो हुनु, कम चल्नु र गम्भीर जन्डिस नवजात शिशुको गम्भीर रोगका संकेत हुन सक्छन्। आफ्नो कार्यक्षेत्रभित्र प्रारम्भिक स्थिरीकरण गरी तुरुन्त referral गर्नुहोस्।"],
 ["11. Infection prevention","Apply standard precautions to every patient: hand hygiene, risk-based PPE, respiratory hygiene, safe injection practice, sharps safety, environmental cleaning and correct reprocessing of reusable equipment.","हरेक बिरामीमा standard precautions अपनाउनुहोस्: हात सफा, जोखिमअनुसार PPE, श्वास स्वच्छता, सुरक्षित injection, धारिलो वस्तु सुरक्षा, वातावरण सफाइ र पुनःप्रयोग हुने उपकरणको सही प्रशोधन।"],
 ["12. Rational medicine use","Choose medicines according to a valid indication, patient factors, evidence, dose, route, duration, contraindications and interactions. Check allergies, explain use, document and monitor adverse effects. Avoid unnecessary antibiotics.","औषधि स्पष्ट कारण, बिरामीको अवस्था, प्रमाण, मात्रा, दिने बाटो, अवधि, निषेध र interaction हेरेर छान्नुहोस्। एलर्जी जाँच्नुहोस्, प्रयोग बुझाउनुहोस्, अभिलेख राख्नुहोस् र adverse effect निगरानी गर्नुहोस्। अनावश्यक antibiotic नदिनुहोस्।"],
 ["13. First aid and ABCDE","For an acutely ill patient, assess Airway, Breathing, Circulation, Disability and Exposure while calling for help. Treat life-threatening problems first, monitor continuously and arrange transfer according to protocol.","गम्भीर बिरामीमा सहयोग बोलाउँदै Airway, Breathing, Circulation, Disability र Exposure क्रमशः मूल्याङ्कन गर्नुहोस्। ज्यान जोखिमका समस्या पहिले सम्हाल्नुहोस्, निरन्तर निगरानी गरी protocol अनुसार referral/transfer गर्नुहोस्।"],
 ["14. Shock","Shock is life-threatening circulatory failure causing inadequate tissue perfusion. Warning signs can include altered mental status, cool clammy skin, weak rapid pulse and hypotension (often late). Call emergency support and manage per protocol.","Shock भनेको तन्तुमा पर्याप्त रक्तप्रवाह नपुग्ने ज्यान जोखिमको अवस्था हो। चेतना बदलिनु, चिसो पसिनायुक्त छाला, कमजोर छिटो नाडी र रक्तचाप घट्नु (ढिलो संकेत हुन सक्छ) देखिन सक्छ। आकस्मिक सहयोग बोलाई protocol अनुसार व्यवस्थापन गर्नुहोस्।"],
 ["15. Burns","Initial burn care prioritizes stopping the burning process, cooling a thermal burn with cool running water, removing constricting items if safe, covering with a clean non-adherent dressing and assessing airway, circulation and burn severity. Do not apply ice or household substances.","जलनमा पहिले जल्ने प्रक्रिया रोक्नुहोस्, thermal burn लाई चिसो बग्ने पानीले चिस्याउनुहोस्, सुरक्षित भए कसिलो वस्तु हटाउनुहोस् र सफा नटाँसिने dressing लगाउनुहोस्। airway, circulation र गम्भीरता जाँच्नुहोस्। बरफ वा घरेलु पदार्थ नलगाउनुहोस्।"],
 ["16. Obstetric danger signs","Urgent referral is needed for heavy vaginal bleeding, severe headache/visual symptoms, convulsions, severe abdominal pain, fever, difficulty breathing, reduced fetal movement or signs of obstructed labour.","धेरै योनी रक्तस्राव, कडा टाउको दुखाइ/दृष्टि समस्या, दौरा, कडा पेट दुखाइ, ज्वरो, सास कष्ट, बच्चा कम चल्नु वा प्रसव अवरोधका संकेतमा तुरुन्त referral चाहिन्छ।"],
 ["17. STI and respectful care","Provide confidential, non-judgmental assessment. Follow current national STI guidelines for testing, treatment, partner services, counselling and follow-up. Avoid diagnosing solely from symptoms when testing is indicated.","गोपनीयता र भेदभावरहित व्यवहारसहित जाँच गर्नुहोस्। परीक्षण, उपचार, partner service, परामर्श र follow-up का लागि हालको राष्ट्रिय STI निर्देशिका पालना गर्नुहोस्। परीक्षण आवश्यक हुँदा लक्षणका आधारमा मात्र निदान नगर्नुहोस्।"],
 ["18. Community diagnosis","Community diagnosis systematically identifies health problems, determinants, resources and priorities using reliable data, community participation and analysis. Findings should guide a feasible action plan and monitoring indicators.","समुदाय निदानले भरपर्दो तथ्याङ्क, समुदायको सहभागिता र विश्लेषणबाट स्वास्थ्य समस्या, निर्धारक, स्रोत र प्राथमिकता पहिचान गर्छ। नतिजाका आधारमा व्यवहारिक कार्ययोजना र अनुगमन सूचक बनाउनुहोस्।"],
 ["19. Epidemiology basics","Incidence measures new cases in a population at risk over a specified period; prevalence measures all existing cases at a point or over a period. Define numerator, denominator, population and time clearly.","Incidence ले निश्चित अवधिमा जोखिममा रहेको जनसंख्यामा नयाँ केस मापन गर्छ; prevalence ले कुनै समय वा अवधिमा रहेका सबै केस मापन गर्छ। numerator, denominator, जनसंख्या र समय स्पष्ट राख्नुहोस्।"],
 ["20. Safe specimen collection","Use the correct container, patient identification, labeling at the bedside, appropriate collection technique, infection prevention, timely transport and documentation. Reject or clarify unlabeled or mismatched specimens according to policy.","सही container, बिरामी पहिचान, बिरामीकै छेउमा label, उचित संकलन विधि, संक्रमण रोकथाम, समयमै ढुवानी र अभिलेख अपनाउनुहोस्। label नभएको वा विवरण नमिलेको नमुना नीतिअनुसार अस्वीकार वा स्पष्ट गर्नुहोस्।"],
 ["21. Respiratory diseases and assessment","Assess respiratory rate, work of breathing, oxygen saturation and chest findings. Common conditions include upper respiratory infection, pneumonia, asthma and COPD. Red flags include severe breathlessness, cyanosis, exhaustion, altered consciousness and low oxygen saturation; stabilize using ABCDE, provide care within scope and arrange urgent referral.","श्वासदर, सास फेर्न लाग्ने मेहनत, oxygen saturation र छातीको जाँच गर्नुहोस्। सामान्य रोगमा माथिल्लो श्वासप्रश्वास संक्रमण, निमोनिया, दम र COPD पर्छन्। अत्यधिक सास कष्ट, नीलोपन, थकान, चेतना परिवर्तन र oxygen कम हुनु खतरा संकेत हुन्; ABCDE अनुसार प्राथमिक मूल्याङ्कन गरी शीघ्र referral गर्नुहोस्।"],
 ["22. Cardiovascular diseases and red flags","Assess pulse, blood pressure, perfusion, edema and chest pain. Hypertension may be asymptomatic; confirm elevated readings using correct technique and repeat measurements. Suspected acute coronary syndrome, stroke, syncope with instability or shock requires emergency assessment and referral; do not delay for routine tests.","नाडी, रक्तचाप, रक्तप्रवाह, सुन्निने अवस्था र छाती दुखाइ मूल्याङ्कन गर्नुहोस्। उच्च रक्तचाप लक्षणविहीन पनि हुन सक्छ; सही तरिकाले नापेर पुनः पुष्टि गर्नुहोस्। हृदयाघातको शंका, stroke, अस्थिर अवस्थासहित बेहोस हुनु वा shock भए आकस्मिक मूल्याङ्कन र referral गर्नुहोस्।"],
 ["23. Gastrointestinal and liver disorders","Common presentations include diarrhea, vomiting, abdominal pain, dyspepsia, jaundice and gastrointestinal bleeding. Assess hydration, abdominal danger signs, stool history and medication use. Severe dehydration, persistent vomiting, blood in stool, rigid abdomen or jaundice with systemic illness needs urgent review.","पखाला, बान्ता, पेट दुखाइ, अपच, जन्डिस र पाचननलीबाट रक्तस्राव सामान्य समस्या हुन्। शरीरमा पानीको कमी, पेटका खतरा संकेत, दिसाको विवरण र औषधि प्रयोग जाँच्नुहोस्। गम्भीर dehydration, निरन्तर बान्ता, दिसामा रगत, कडा पेट वा बिरामी अवस्थासहित जन्डिस भए शीघ्र referral गर्नुहोस्।"],
 ["24. Renal and urinary disorders","Ask about urine volume, frequency, dysuria, hematuria, flank pain and edema. Urinary tract infection may cause dysuria and frequency; fever with flank pain may suggest upper urinary infection. Oliguria, anuria, severe dehydration, visible blood or suspected acute kidney injury requires prompt assessment.","पिसाबको मात्रा, पटक, पोल्ने, रगत, कम्मरको छेउ दुख्ने र सुन्निनेबारे सोध्नुहोस्। UTI मा पिसाब पोल्ने र पटक-पटक लाग्ने हुन सक्छ; ज्वरोसँग flank pain भए माथिल्लो urinary infection को शंका हुन्छ। पिसाब अत्यन्त कम/बन्द, देखिने रगत वा acute kidney injury को शंका भए शीघ्र जाँच आवश्यक हुन्छ।"],
 ["25. Neurological assessment and emergencies","Assess level of consciousness, pupils, speech, limb power, sensation, gait and seizures. Sudden facial droop, arm weakness or speech difficulty suggests stroke and is time-critical. A first seizure, prolonged seizure, repeated seizures without recovery, meningism or reduced consciousness needs emergency care.","चेतनाको स्तर, आँखाको pupil, बोली, हातखुट्टाको शक्ति, संवेदना, हिँडाइ र दौरा जाँच्नुहोस्। अचानक अनुहार बाङ्गिनु, हात कमजोर हुनु वा बोली बिग्रनु stroke का संकेत हुन सक्छन् र समय अत्यन्त महत्त्वपूर्ण हुन्छ। पहिलोपटक दौरा, लामो दौरा, होस नफर्की दोहोरिने दौरा वा चेतना घटे आकस्मिक सेवा चाहिन्छ।"],
 ["26. Common infectious diseases and infection control","Consider local epidemiology and exposure when assessing fever. Use standard precautions for every patient, hand hygiene, appropriate PPE, safe injection practices, respiratory hygiene and correct waste segregation. Suspected tuberculosis, measles, meningitis or other notifiable/high-risk infection requires appropriate precautions, notification and referral according to national guidance.","ज्वरो मूल्याङ्कन गर्दा स्थानीय रोगको अवस्था र exposure विचार गर्नुहोस्। सबै बिरामीमा हात सफाइ, उपयुक्त PPE, सुरक्षित injection, श्वासप्रश्वास शिष्टाचार र फोहोर छुट्याउने standard precaution अपनाउनुहोस्। क्षयरोग, दादुरा, meningitis वा उच्च जोखिम संक्रमणको शंका भए राष्ट्रिय निर्देशिकाअनुसार सावधानी, सूचना र referral गर्नुहोस्।"],
 ["27. Pediatric assessment and IMNCI danger signs","Assess feeding, activity, respiratory rate, chest indrawing, temperature, hydration and growth. General danger signs include inability to drink or breastfeed, vomiting everything, convulsions and lethargy or unconsciousness. Young infants need particular attention to poor feeding, fast or difficult breathing, fever or low temperature and reduced movement; refer urgently when danger signs are present.","खुवाइ, सक्रियता, श्वासदर, छाती भित्र तानिने, तापक्रम, hydration र वृद्धि जाँच्नुहोस्। सामान्य खतरा संकेतमा दूध/पानी पिउन नसक्नु, सबै कुरा बान्ता गर्नु, दौरा र सुस्त वा बेहोस हुनु पर्छन्। साना शिशुमा दूध नखानु, छिटो/गाह्रो सास, ज्वरो वा शरीर चिसो हुनु र कम चल्नु विशेष खतरा हुन्; संकेत देखिए शीघ्र referral गर्नुहोस्।"],
 ["28. Skin diseases and basic dermatology","Common conditions include scabies, fungal infections, eczema, impetigo and acne. Examine distribution, morphology, itch, pain, fever and contacts. Treat only within competence and local protocols; widespread infection, rapidly spreading redness, severe pain, mucosal involvement, systemic illness or suspected severe drug reaction requires urgent assessment.","खुजली, फंगल संक्रमण, eczema, impetigo र acne सामान्य छालाका समस्या हुन्। शरीरमा फैलावट, दागको प्रकार, चिलाउने/दुख्ने, ज्वरो र सम्पर्कमा आएका व्यक्तिबारे जाँच्नुहोस्। आफ्नो दक्षता र स्थानीय protocol भित्र मात्र उपचार गर्नुहोस्; फैलँदो रातोपन, धेरै दुखाइ, mucosa संलग्न वा गम्भीर औषधि प्रतिक्रिया भए शीघ्र जाँच आवश्यक हुन्छ।"],
 ["29. Mental health and psychosocial care","Use respectful, non-stigmatizing communication and assess mood, sleep, function, substance use and safety. Ask directly and calmly about self-harm thoughts when clinically indicated. Immediate risk of suicide, severe agitation, psychosis with danger, delirium or inability to care for basic needs requires urgent safety measures and referral.","सम्मानजनक र भेदभावरहित संवाद गर्नुहोस्; मनोदशा, निद्रा, दैनिक काम, पदार्थ प्रयोग र सुरक्षाबारे बुझ्नुहोस्। आवश्यक अवस्थामा आत्महानिको सोचबारे शान्त र स्पष्ट रूपमा सोध्नुहोस्। आत्महत्याको तत्काल जोखिम, खतरासहितको अत्यधिक उत्तेजना, psychosis, delirium वा आधारभूत हेरचाह गर्न नसक्ने अवस्था भए तत्काल सुरक्षा र referral आवश्यक हुन्छ।"],
 ["30. Obstetric and gynecological care","Antenatal assessment includes blood pressure, anemia symptoms, nutrition, danger signs and birth preparedness. Danger signs include vaginal bleeding, severe headache or visual symptoms, convulsions, severe abdominal pain, fever, leaking fluid or reduced fetal movement. Postpartum heavy bleeding, fever, severe headache or convulsions is an emergency.","गर्भावस्थाको जाँचमा रक्तचाप, रक्तअल्पताका लक्षण, पोषण, खतरा संकेत र प्रसूति तयारी समावेश गर्नुहोस्। योनीबाट रगत, कडा टाउको दुखाइ/दृष्टि समस्या, दौरा, कडा पेट दुखाइ, ज्वरो, पानी बग्नु वा बच्चा कम चल्नु खतरा संकेत हुन्। सुत्केरीपछि धेरै रक्तस्राव, ज्वरो, कडा टाउको दुखाइ वा दौरा आकस्मिक अवस्था हो।"],
 ["31. Wound care, fractures and surgical conditions","Assess wound location, contamination, depth, bleeding, distal circulation, sensation and movement. Control bleeding, cover wounds with clean dressings and assess tetanus immunization. Suspected open fracture, neurovascular compromise, compartment syndrome, major burns, abdominal rigidity or acute abdomen requires urgent referral; do not attempt procedures beyond scope.","घाउको स्थान, फोहोर, गहिराइ, रक्तस्राव, टाढाको रक्तसञ्चार, संवेदना र चाल जाँच्नुहोस्। रक्तस्राव नियन्त्रण गरी सफा dressing लगाउनुहोस् र tetanus खोप अवस्था जाँच्नुहोस्। खुला fracture, रक्तसञ्चार/नसामा समस्या, compartment syndrome, ठूलो burn वा acute abdomen भए शीघ्र referral गर्नुहोस्; आफ्नो कार्यक्षेत्रभन्दा बाहिरको प्रक्रिया नगर्नुहोस्।"],
 ["32. Eye, ENT and oral health essentials","Red flags include sudden visual loss, painful red eye, chemical eye exposure, ear discharge with mastoid swelling, airway compromise, severe sore throat with drooling and facial/oral swelling with fever. For chemical eye exposure, begin immediate copious irrigation and arrange urgent care. Refer suspected emergencies promptly.","अचानक दृष्टि हराउनु, दुख्ने रातो आँखा, आँखामा रसायन पर्नु, कानबाट पानीसँग mastoid सुन्निनु, श्वासमार्ग अवरुद्ध हुनु, र्‍याल चुहिने गरी घाँटी दुख्नु र ज्वरोसहित मुख/अनुहार सुन्निनु खतरा संकेत हुन्। आँखामा रसायन परे तुरुन्त प्रशस्त पानीले धुन सुरु गरी आकस्मिक उपचारमा पठाउनुहोस्।"]

 ["33. Health education and health promotion","Health education is a planned learning process that helps people make informed health decisions. Assess the audience, identify learning needs, set measurable objectives, select suitable methods and media, deliver the session, and evaluate knowledge or behaviour change. Methods include individual counselling, group discussion, demonstration and community campaigns. Health promotion also addresses supportive environments, community action and healthy public policy.","स्वास्थ्य शिक्षा भनेको मानिसलाई स्वास्थ्यसम्बन्धी सही निर्णय गर्न सहयोग गर्ने योजनाबद्ध सिकाइ प्रक्रिया हो। लक्षित समूह र आवश्यकता पहिचान गरी मापनयोग्य उद्देश्य बनाउने, उपयुक्त विधि/माध्यम छान्ने, कार्यक्रम सञ्चालन गर्ने र ज्ञान वा व्यवहारमा आएको परिवर्तन मूल्याङ्कन गर्ने। व्यक्तिगत परामर्श, समूह छलफल, प्रदर्शन र समुदाय अभियान यसका विधि हुन्।"],
 ["34. Safe water, sanitation and waste management","Safe water management includes source protection, appropriate treatment such as filtration and disinfection, safe storage and regular quality monitoring. Sanitation includes hygienic latrines, handwashing facilities, food hygiene and safe disposal of human and healthcare waste. Segregate healthcare waste at the point of generation using current national guidance; never mix sharps with general waste.","सुरक्षित पानीका लागि स्रोत संरक्षण, आवश्यक filtration/disinfection, सुरक्षित भण्डारण र नियमित गुणस्तर जाँच आवश्यक हुन्छ। सरसफाइमा चर्पी, हात धुने सुविधा, खाद्य स्वच्छता र मानव तथा स्वास्थ्य संस्थाको फोहोर सुरक्षित व्यवस्थापन पर्छ। स्वास्थ्यजन्य फोहोर उत्पादन भएको ठाउँमै छुट्याई हालको राष्ट्रिय निर्देशिका पालना गर्नुपर्छ; धारिलो फोहोर सामान्य फोहोरमा मिसाउनु हुँदैन।"],
 ["35. Vector and rodent control","Integrated vector management combines environmental control, elimination of breeding sites, safe water storage, personal protection, community participation and targeted insecticide use when indicated. Mosquito control includes removing stagnant water and covering containers. Rodent control requires safe food storage, waste control, proofing buildings and approved control measures; avoid unsafe handling of poison.","Vector नियन्त्रणमा वातावरण व्यवस्थापन, प्रजननस्थल हटाउने, पानीका भाँडा छोप्ने, व्यक्तिगत सुरक्षा, समुदाय सहभागिता र आवश्यकताअनुसार मात्र कीटनाशक प्रयोग समावेश हुन्छ। लामखुट्टे नियन्त्रणका लागि जमेको पानी हटाउनुहोस्। मुसा नियन्त्रणमा खाद्य पदार्थ सुरक्षित राख्ने, फोहोर व्यवस्थापन, भवनका प्वाल बन्द गर्ने र स्वीकृत उपाय अपनाउने; विषादी असुरक्षित रूपमा चलाउनु हुँदैन।"],
 ["36. Primary health care and family health","Primary health care is accessible, equitable and community-oriented care across prevention, promotion, treatment, rehabilitation and palliation. Core principles include equitable distribution, community participation, intersectoral coordination and appropriate technology. Family health services include antenatal and postnatal care, safe delivery referral, newborn care, child growth monitoring, immunization, adolescent health and voluntary family planning counselling.","प्राथमिक स्वास्थ्य सेवा सबैका लागि पहुँचयोग्य, समानतामूलक र समुदाय केन्द्रित सेवा हो; यसमा रोकथाम, प्रवर्द्धन, उपचार, पुनर्स्थापना र palliation पर्छ। समान वितरण, समुदाय सहभागिता, विभिन्न क्षेत्रबीच समन्वय र उपयुक्त प्रविधि यसको आधार हुन्। परिवार स्वास्थ्य सेवामा गर्भवती तथा सुत्केरी जाँच, सुरक्षित प्रसूति referral, नवजात हेरचाह, बाल वृद्धि अनुगमन, खोप, किशोर स्वास्थ्य र स्वेच्छिक परिवार नियोजन परामर्श पर्छ।"],
 ["37. Immunization and cold chain","Vaccines are sensitive biological products and must be stored and transported within the temperature range specified by the national immunization programme and product guidance. Maintain the cold chain, monitor and document temperatures, use conditioned ice packs where required, check vaccine vial monitors and expiry dates, and follow policy after a temperature excursion. Do not use a vaccine if its safety or potency is uncertain; seek programme guidance.","खोप तापक्रमप्रति संवेदनशील जैविक पदार्थ हो र राष्ट्रिय खोप कार्यक्रम तथा उत्पादकले तोकेको तापक्रममा भण्डारण/ढुवानी गर्नुपर्छ। cold chain कायम राख्ने, तापक्रम नियमित अभिलेख गर्ने, आवश्यकताअनुसार conditioned ice pack प्रयोग गर्ने, vaccine vial monitor र म्याद जाँच्ने तथा तापक्रम बिग्रिएमा निर्देशिका पालना गर्ने। गुणस्तरमा शंका भए कार्यक्रमको निर्देशन नलिई खोप प्रयोग गर्नु हुँदैन।"],
 ["38. Nutrition and nutritional assessment","A balanced diet provides adequate energy, protein, essential fats, vitamins, minerals, fibre and safe water. Assess nutritional status using dietary history, clinical signs and appropriate anthropometry such as weight, height/length, BMI or mid-upper arm circumference according to age and programme guidance. Undernutrition may result from inadequate intake, disease or social determinants; manage and refer according to national protocols.","सन्तुलित आहारले पर्याप्त ऊर्जा, protein, आवश्यक बोसो, vitamin, mineral, fibre र सुरक्षित पानी दिन्छ। खानपान इतिहास, शारीरिक संकेत र उमेरअनुसार तौल, उचाइ/लम्बाइ, BMI वा MUAC जस्ता मापनबाट पोषण अवस्था मूल्याङ्कन गरिन्छ। कुपोषण अपर्याप्त खाना, रोग वा सामाजिक कारणले हुन सक्छ; राष्ट्रिय protocol अनुसार व्यवस्थापन र referral गर्नुपर्छ।"],
 ["39. Health management, HMIS and community programmes","Health management includes planning, organizing, staffing, supervision, monitoring, evaluation and responsible use of resources. Health Management Information Systems (HMIS) support routine reporting and decision-making; records should be complete, timely, accurate and confidential. Community diagnosis and micro-planning use local data and participation to prioritize problems, set activities, assign responsibilities and monitor indicators.","स्वास्थ्य व्यवस्थापनमा योजना, संगठन, जनशक्ति व्यवस्थापन, supervision, monitoring, evaluation र स्रोतको जिम्मेवार उपयोग पर्छ। HMIS ले नियमित प्रतिवेदन र निर्णयमा सहयोग गर्छ; अभिलेख पूर्ण, समयमै, सही र गोप्य हुनुपर्छ। समुदाय निदान र micro-planning ले स्थानीय तथ्याङ्क तथा सहभागिताबाट समस्या प्राथमिकता, गतिविधि, जिम्मेवारी र अनुगमन सूचक तय गर्छ।"],
 ["40. Blood, lymphatic system and immunity","Blood consists of plasma, red blood cells, white blood cells and platelets. Red cells transport oxygen, white cells contribute to defence and platelets support haemostasis. The lymphatic system returns tissue fluid to circulation and supports immune surveillance. Innate immunity provides rapid non-specific defence; adaptive immunity involves antigen-specific B and T lymphocytes and immunological memory.","रगतमा plasma, red blood cell, white blood cell र platelet हुन्छन्। रातो रक्तकोषले oxygen बोक्छ, सेतो रक्तकोषले संक्रमणविरुद्ध रक्षा गर्छ र platelet ले रक्तस्राव रोक्न सहयोग गर्छ। lymphatic system ले तन्तुको तरल पदार्थ रक्तसञ्चारमा फर्काउँछ र प्रतिरक्षा निगरानीमा मद्दत गर्छ। innate immunity छिटो र सामान्य रक्षा हो; adaptive immunity मा antigen-विशिष्ट B/T lymphocyte र immune memory हुन्छ।"],
 ["41. Reproductive health and family planning","Reproductive health includes informed, voluntary and respectful care throughout the life course. Family planning counselling should explain available methods, effectiveness, benefits, possible adverse effects, contraindications and the option to discontinue or switch. Respect informed choice and confidentiality; assess pregnancy-related danger signs and arrange timely referral. Do not pressure clients toward a particular method.","प्रजनन स्वास्थ्यमा जीवनका विभिन्न चरणमा जानकारीसहित, स्वेच्छिक र सम्मानजनक सेवा पर्छ। परिवार नियोजन परामर्शमा उपलब्ध विधि, प्रभावकारिता, फाइदा, सम्भावित adverse effect, निषेध र विधि परिवर्तन/छोड्ने विकल्प बुझाउनुपर्छ। सूचित छनोट र गोपनीयताको सम्मान गर्नुहोस्; गर्भावस्थाका खतरा संकेत पहिचान गरी समयमै referral गर्नुहोस्। कुनै एक विधि रोज्न दबाब दिनु हुँदैन।"]

 ];
 const Q=[
 ["The functional unit of the kidney is:","मिर्गौलाको कार्यात्मक एकाइ कुन हो?",["Nephron","Neuron","Alveolus","Hepatocyte"],0,"The nephron filters blood and contributes to urine formation.","Nephron ले रगत छानेर पिसाब बन्ने प्रक्रियामा काम गर्छ।","Anatomy & Physiology"],
 ["Which chamber pumps oxygenated blood into the systemic circulation?","शरीरभरि oxygenated blood पठाउने मुटुको कोठा कुन हो?",["Right atrium","Right ventricle","Left atrium","Left ventricle"],3,"The left ventricle pumps oxygenated blood into the aorta and systemic circulation.","Left ventricle ले aorta हुँदै शरीरभरि oxygenated blood पठाउँछ।","Anatomy & Physiology"],
 ["Insulin is secreted by which pancreatic cells?","Insulin pancreas का कुन कोषिकाले उत्पादन गर्छन्?",["Alpha cells","Beta cells","Acinar cells","Delta cells"],1,"Pancreatic beta cells secrete insulin; alpha cells secrete glucagon.","Pancreas का beta cells ले insulin र alpha cells ले glucagon उत्पादन गर्छन्।","Anatomy & Physiology"],
 ["Which sequence best describes a structured clinical history?","व्यवस्थित clinical history को राम्रो क्रम कुन हो?",["Presenting complaint, HPI, past history, medication/allergy, family/social history","Only diagnosis and prescription","Only vital signs","Only family history"],0,"A complete history explores the current problem and relevant medical, medication, allergy, family and social context.","पूर्ण इतिहासमा हालको समस्या र सम्बन्धित स्वास्थ्य, औषधि, एलर्जी, पारिवारिक तथा सामाजिक विवरण समेटिन्छ।","General Medicine"],
 ["Which is a core vital sign?","मुख्य vital sign कुन हो?",["Hair colour","Respiratory rate","Height only","Visual acuity"],1,"Temperature, pulse, respiratory rate and blood pressure are core vital signs.","तापक्रम, नाडी, श्वासदर र रक्तचाप मुख्य vital signs हुन्।","General Medicine"],
 ["A patient has severe breathlessness and cyanosis. What is the priority?","बिरामीलाई अत्यधिक सास कष्ट र नीलोपन छ। पहिलो प्राथमिकता के हो?",["Routine appointment next week","Urgent ABC assessment and emergency help","Give oral food","Ask them to walk"],1,"Severe respiratory distress and cyanosis are emergency signs requiring immediate assessment and help.","गम्भीर श्वास कष्ट र नीलोपन आकस्मिक संकेत हुन्; तुरुन्त मूल्याङ्कन र सहयोग चाहिन्छ।","General Medicine"],
 ["Persistent hyperglycemia is characteristic of:","लगातार hyperglycemia कुन रोगको विशेषता हो?",["Diabetes mellitus","Asthma","Scabies","Otitis externa"],0,"Diabetes mellitus involves persistent hyperglycemia due to impaired insulin secretion, action or both.","मधुमेहमा insulin उत्पादन वा कार्यमा समस्या भएर glucose बढ्छ।","General Medicine"],
 ["Which finding may suggest fluid overload?","कुन संकेतले शरीरमा तरल बढी भएको देखाउन सक्छ?",["Peripheral edema","Dry hair only","Improved appetite","Normal urine colour"],0,"Peripheral edema can occur with fluid retention and requires clinical context and assessment.","Peripheral edema तरल जम्मा हुँदा देखिन सक्छ; अन्य अवस्था पनि मूल्याङ्कन गर्नुपर्छ।","General Medicine"],
 ["Which is a neonatal danger sign?","नवजात शिशुको खतरा संकेत कुन हो?",["Feeding well","Convulsions","Normal activity","Regular feeding"],1,"Convulsions in a neonate are a danger sign requiring urgent assessment and referral.","नवजातमा दौरा गम्भीर खतरा संकेत हो र तत्काल referral चाहिन्छ।","General Medicine"],
 ["What is the first step in a systematic assessment of an acutely ill patient?","गम्भीर बिरामीको व्यवस्थित जाँचमा पहिलो चरण के हो?",["ABCDE approach","Routine discharge","Wait for laboratory report","Give an unverified medicine"],0,"ABCDE prioritizes life-threatening airway, breathing and circulation problems.","ABCDE ले airway, breathing र circulation का ज्यान जोखिमका समस्या प्राथमिकतामा राख्छ।","General Surgery"],
 ["Which symptom with pregnancy requires urgent referral?","गर्भावस्थामा कुन लक्षण भए तुरुन्त referral चाहिन्छ?",["Mild appetite change","Heavy vaginal bleeding","Occasional fetal movement","Mild fatigue after activity"],1,"Heavy vaginal bleeding is an obstetric danger sign.","धेरै योनी रक्तस्राव प्रसूति आकस्मिक संकेत हो।","General Surgery"],
 ["A thermal burn should initially be cooled with:","Thermal burn लाई सुरुमा के ले चिस्याउनु उपयुक्त हुन्छ?",["Cool running water","Ice directly","Toothpaste","Cooking oil"],0,"Cool running water is recommended; avoid ice and household substances.","चिसो बग्ने पानी प्रयोग गर्नुहोस्; बरफ वा घरेलु पदार्थ नलगाउनुहोस्।","General Surgery"],
 ["Which is an appropriate sharps safety practice?","धारिलो उपकरणको सुरक्षित अभ्यास कुन हो?",["Recap used needles with both hands","Dispose immediately into puncture-resistant sharps container","Leave on a tray","Bend used needles"],1,"Used sharps should be discarded immediately into an approved puncture-resistant container.","प्रयोग भएको धारिलो वस्तु तुरुन्त puncture-resistant sharps container मा फाल्नुपर्छ।","General Surgery"],
 ["Incidence refers to:","Incidence को अर्थ के हो?",["All existing cases","New cases occurring in a population at risk over time","Total hospital beds","Number of health workers"],1,"Incidence measures new cases over a specified period in a population at risk.","Incidence ले निश्चित अवधिमा जोखिममा रहेको जनसंख्याका नयाँ केस मापन गर्छ।","Community Health"],
 ["Prevalence includes:","Prevalence मा के समावेश हुन्छ?",["Only new cases","All existing cases at a specified time or period","Only deaths","Only exposed persons"],1,"Prevalence counts existing cases at a point or during a period.","Prevalence ले निश्चित समयमा वा अवधिमा रहेका सबै केस गन्छ।","Community Health"],
 ["A key principle of primary health care is:","प्राथमिक स्वास्थ्य सेवाको मुख्य सिद्धान्त कुन हो?",["Community participation","Only hospital-based care","No prevention","Care only for urban residents"],0,"Community participation is a core PHC principle.","समुदायको सहभागिता प्राथमिक स्वास्थ्य सेवाको मुख्य सिद्धान्त हो।","Community Health"],
 ["Which method makes drinking water safer at household level?","घरायसी तहमा पिउने पानी सुरक्षित बनाउने विधि कुन हो?",["Boiling appropriately","Adding soil","Storing uncovered","Mixing with wastewater"],0,"Appropriate boiling is an effective household water treatment method when done correctly.","सही तरिकाले उमाल्नु घरायसी पानी शुद्धीकरणको प्रभावकारी उपाय हो।","Community Health"],
 ["A balanced diet should provide:","सन्तुलित आहारले के उपलब्ध गराउनुपर्छ?",["Only carbohydrates","Adequate energy and essential nutrients in suitable proportions","Only vitamins","Only fats"],1,"A balanced diet provides adequate energy and essential nutrients in appropriate proportions.","सन्तुलित आहारले आवश्यक ऊर्जा र पोषक तत्व उचित अनुपातमा दिन्छ।","Community Health"],
 ["Which is an example of health promotion?","स्वास्थ्य प्रवर्द्धनको उदाहरण कुन हो?",["Community-led physical activity and nutrition programme","Ignoring local priorities","Providing information without engagement only","Discouraging participation"],0,"Health promotion supports people and communities to increase control over health.","स्वास्थ्य प्रवर्द्धनले व्यक्ति र समुदायलाई आफ्नो स्वास्थ्यमा नियन्त्रण बढाउन सहयोग गर्छ।","Community Health"],
 ["Cold chain is maintained to:","Cold chain किन कायम राखिन्छ?",["Preserve vaccine potency","Change vaccine colour","Freeze every medicine","Avoid recording temperature"],0,"Cold chain maintains recommended temperatures to preserve vaccine quality and potency.","खोपको गुणस्तर र प्रभावकारिता जोगाउन तोकिएको तापक्रम कायम गरिन्छ।","Community Health"],
 ["Which is the best approach to community diagnosis?","समुदाय निदानको राम्रो विधि कुन हो?",["Collect and analyze reliable data with community participation","Assume all communities are identical","Use rumours only","Exclude local leaders"],0,"Reliable data and community participation help identify priorities and feasible interventions.","भरपर्दो तथ्याङ्क र समुदाय सहभागिताले प्राथमिकता र व्यवहारिक उपाय पहिचान गर्छ।","Community Health"],
 ["A drug's pharmacokinetics describes:","Pharmacokinetics ले के वर्णन गर्छ?",["What the body does to the drug","Only drug price","Only tablet colour","What the drug does to the body"],0,"Pharmacokinetics includes absorption, distribution, metabolism and excretion.","Pharmacokinetics मा absorption, distribution, metabolism र excretion पर्छ।","Pharmacology"],
 ["Before giving a medicine, which should be checked?","औषधि दिनुअघि के जाँच्नुपर्छ?",["Allergy and current medicines","Only shoe size","Only occupation","Only preferred colour"],0,"Allergy, interactions, contraindications and patient factors are essential safety checks.","एलर्जी, interaction, contraindication र बिरामीको अवस्था जाँच्नु आवश्यक छ।","Pharmacology"],
 ["Antibiotics should be used:","Antibiotic कहिले प्रयोग गर्नुपर्छ?",["For every fever","When clinically indicated for susceptible bacterial infection","For all viral colds","To treat hypertension"],1,"Antibiotics are for indicated bacterial infections, not routine viral illnesses.","Antibiotic आवश्यक bacterial infection मा प्रयोग हुन्छ; सामान्य viral रोगमा होइन।","Pharmacology"],
 ["Which route places medicine directly into a vein?","औषधि सिधै नसामा दिने route कुन हो?",["Intravenous","Oral","Topical","Inhalational"],0,"Intravenous administration delivers medicine into a vein.","Intravenous route बाट औषधि नसामा दिइन्छ।","Pharmacology"],
 ["A prescription label should clearly include:","औषधिको label मा स्पष्ट रूपमा के हुनुपर्छ?",["Patient/drug directions and relevant dispensing details","Only decoration","Unverified abbreviations","No expiry information where required"],0,"Clear labeling supports correct use and patient safety; follow local legal requirements.","स्पष्ट label ले सही प्रयोग र बिरामी सुरक्षा बढाउँछ; स्थानीय कानुनी मापदण्ड पालना गर्नुपर्छ।","Pharmacology"],
 ["Shock is primarily a problem of:","Shock मुख्यतया कुन समस्यासँग सम्बन्धित छ?",["Inadequate tissue perfusion","Excessive hair growth","Improved circulation","Tooth discoloration"],0,"Shock is circulatory failure causing inadequate tissue perfusion.","Shock मा रक्तसञ्चार असफल भएर तन्तुमा पर्याप्त रक्तप्रवाह पुग्दैन।","General Surgery"],
 ["Which action is appropriate for external severe bleeding?","बाहिरी गम्भीर रक्तस्रावमा उपयुक्त कदम कुन हो?",["Apply firm direct pressure and call for urgent help","Wash and leave uncovered","Encourage walking","Apply soil"],0,"Firm direct pressure is a key first-aid measure while arranging emergency care.","आकस्मिक सहयोग मिलाउँदै घाउमा कडा प्रत्यक्ष दबाब दिनु प्राथमिक उपचारको मुख्य उपाय हो।","General Surgery"],
 ["Which is a warning sign of stroke?","Stroke को चेतावनी संकेत कुन हो?",["Sudden facial droop or one-sided weakness","Gradual nail growth","Mild thirst after exercise","Itchy scalp only"],0,"Sudden facial weakness, arm weakness or speech difficulty requires emergency response.","अचानक अनुहार बाङ्गिनु, हात कमजोर हुनु वा बोली बिग्रनु आकस्मिक संकेत हुन्।","General Surgery"],
 ["Which is a common sign of anemia?","रक्तअल्पताको सामान्य संकेत कुन हो?",["Pallor and fatigue","Blue sclera in all cases","Increased hair length","Excessive sweating only"],0,"Anemia may cause pallor, fatigue, breathlessness and reduced exercise tolerance.","रक्तअल्पतामा फिक्कापन, थकान, सास कष्ट र काम गर्ने क्षमता घट्न सक्छ।","Clinical Pathology"],
 ["Which sample is commonly used for a complete blood count?","Complete blood count का लागि सामान्यतया कुन नमुना प्रयोग हुन्छ?",["EDTA anticoagulated blood","Urine only","Saliva only","Unpreserved stool"],0,"CBC is commonly performed on EDTA-anticoagulated whole blood.","CBC का लागि EDTA भएको anticoagulated whole blood सामान्यतया प्रयोग हुन्छ।","Clinical Pathology"],
 ["Sterilization means:","Sterilization को अर्थ के हो?",["Destruction/removal of all forms of microbial life including spores","Removal of visible dirt only","Reduction of odour","Rinsing with water"],0,"Sterilization destroys or removes all forms of microbial life, including bacterial spores.","Sterilization ले bacterial spores सहित सबै प्रकारका सूक्ष्मजीव नष्ट वा हटाउँछ।","Clinical Pathology"],
 ["Which organism causes malaria?","मलेरिया कुन जीवका कारण हुन्छ?",["Plasmodium species","Candida species","Staphylococcus aureus","Entamoeba coli"],0,"Malaria is caused by Plasmodium parasites transmitted by infected female Anopheles mosquitoes.","मलेरिया Plasmodium परजीवीबाट हुन्छ, जुन संक्रमित पोथी Anopheles लामखुट्टेले सार्छ।","Clinical Pathology"],

  ["Which bone protects the brain?","मस्तिष्कलाई कुन हड्डीले सुरक्षा गर्छ?",["Skull","Femur","Patella","Tibia"],0,"The skull encloses and protects the brain.","Skull ले मस्तिष्कलाई घेरेर सुरक्षा गर्छ।","Anatomy & Physiology"],
  ["Which blood cells mainly carry oxygen?","अक्सिजन बोक्ने मुख्य रक्तकोष कुन हो?",["White blood cells","Red blood cells","Platelets","Plasma cells"],1,"Red blood cells contain hemoglobin, which carries oxygen.","रातो रक्तकोषमा hemoglobin हुन्छ, जसले अक्सिजन बोक्छ।","Anatomy & Physiology"],
  ["Which part of the brain helps coordinate balance and movement?","सन्तुलन र चाल समन्वय गर्न मस्तिष्कको कुन भागले मद्दत गर्छ?",["Cerebellum","Medulla","Hypothalamus","Cerebrum"],0,"The cerebellum coordinates movement, posture and balance.","Cerebellum ले चाल, शरीरको अवस्था र सन्तुलन समन्वय गर्छ।","Anatomy & Physiology"],
  ["The main site of gas exchange in the lungs is:","फोक्सोमा ग्यास आदानप्रदान हुने मुख्य स्थान कुन हो?",["Trachea","Bronchi","Alveoli","Pleura"],2,"Alveoli provide a large thin surface for oxygen and carbon dioxide exchange.","Alveoli को पातलो सतहमा अक्सिजन र कार्बन डाइअक्साइड साटासाट हुन्छ।","Anatomy & Physiology"],
  ["Which hormone lowers blood glucose?","रगतको glucose घटाउने hormone कुन हो?",["Glucagon","Insulin","Adrenaline","Cortisol"],1,"Insulin promotes glucose uptake and storage, lowering blood glucose.","Insulin ले glucose को उपयोग र भण्डारण बढाएर रगतको glucose घटाउँछ।","Anatomy & Physiology"],
  ["The best first step when planning a community health programme is to:","समुदाय स्वास्थ्य कार्यक्रम योजना बनाउँदा पहिलो उपयुक्त कदम के हो?",["Assess community needs and resources","Purchase equipment immediately","Start without baseline data","Select activities without consultation"],0,"A needs assessment identifies priority problems, resources and community expectations.","आवश्यकता मूल्याङ्कनले प्राथमिक समस्या, स्रोत र समुदायको अपेक्षा पहिचान गर्छ।","Community Health"],
  ["Which indicator commonly measures infant deaths among live births?","जीवित जन्ममध्ये शिशु मृत्यु मापन गर्ने सूचक कुन हो?",["Maternal mortality ratio","Infant mortality rate","Crude birth rate","General fertility rate"],1,"Infant mortality rate measures deaths under one year per 1,000 live births in a specified period.","शिशु मृत्यु दरले निश्चित अवधिमा प्रति १,००० जीवित जन्ममा एक वर्षमुनिका मृत्यु मापन गर्छ।","Community Health"],
  ["Which is a primary prevention activity?","प्राथमिक रोकथामको उदाहरण कुन हो?",["Rehabilitation after stroke","Immunization","Screening for cervical cancer","Physiotherapy after fracture"],1,"Immunization prevents disease before it occurs.","खोपले रोग हुनुअघि नै रोकथाम गर्छ।","Community Health"],
  ["A disease constantly present in a particular area is described as:","कुनै क्षेत्रमा निरन्तर देखिने रोगलाई के भनिन्छ?",["Epidemic","Pandemic","Endemic","Sporadic outbreak"],2,"Endemic disease maintains a usual presence in a defined population or area.","Endemic रोग निश्चित समुदाय वा क्षेत्रमा सामान्य रूपमा निरन्तर रहन्छ।","Community Health"],
  ["Which measure is most useful for preventing fecal-oral disease transmission?","दिसा–मुख मार्गबाट सर्ने रोग रोक्न कुन उपाय उपयोगी हुन्छ?",["Handwashing with soap after toilet use","Sharing drinking cups","Open defecation","Storing food uncovered"],0,"Handwashing with soap interrupts transmission of fecal pathogens.","साबुनपानीले हात धुँदा दिसाबाट सर्ने जीवाणुको प्रसार रोकिन्छ।","Community Health"],
  ["Which vitamin deficiency causes night blindness?","कुन vitamin को कमीले राति कम देख्ने समस्या हुन्छ?",["Vitamin C","Vitamin D","Vitamin A","Vitamin K"],2,"Vitamin A is essential for retinal function; deficiency can cause night blindness.","Vitamin A आँखाको retina को कामका लागि आवश्यक हुन्छ; कमीले राति कम देखिन्छ।","Community Health"],
  ["A family planning method that also reduces STI transmission risk is:","STI सर्ने जोखिम पनि घटाउने परिवार नियोजन विधि कुन हो?",["Condom","Copper IUD","Oral pill","Implant"],0,"Correct and consistent condom use reduces risk of many STIs and pregnancy.","सही र नियमित condom प्रयोगले धेरै STI र गर्भधारणको जोखिम घटाउँछ।","Community Health"],
  ["Which is an example of a social determinant of health?","स्वास्थ्यको सामाजिक निर्धारकको उदाहरण कुन हो?",["Housing and education","Blood group only","Eye colour","Height alone"],0,"Housing, education, income and employment influence health opportunities and outcomes.","आवास, शिक्षा, आय र रोजगारीले स्वास्थ्य अवसर र नतिजामा प्रभाव पार्छन्।","Community Health"],
  ["The purpose of disease surveillance is to:","रोग निगरानीको मुख्य उद्देश्य के हो?",["Collect, analyze and use health data for action","Replace all clinical diagnosis","Record only hospital income","Avoid reporting outbreaks"],0,"Surveillance supports early detection, trend monitoring and public health response.","निगरानीले रोग चाँडो पहिचान, प्रवृत्ति अनुगमन र जनस्वास्थ्य प्रतिक्रिया सम्भव बनाउँछ।","Community Health"],
  ["Which waste should be placed in a puncture-resistant sharps container?","छेड्न नसकिने sharps container मा कुन फोहोर राख्नुपर्छ?",["Used needles","Food wrappers","Paper towels","Clean packaging"],0,"Used needles and other sharps must go directly into approved puncture-resistant containers.","प्रयोग भएका सुई र धारिला वस्तु तुरुन्त स्वीकृत puncture-resistant container मा राख्नुपर्छ।","Community Health"],
  ["Exclusive breastfeeding is generally recommended for the first:","पूर्ण स्तनपान सामान्यतया सुरुका कति महिनासम्म सिफारिस गरिन्छ?",["2 months","4 months","6 months","12 months"],2,"WHO recommends exclusive breastfeeding for the first six months, with complementary foods thereafter.","WHO ले सुरुका ६ महिना पूर्ण स्तनपान र त्यसपछि पूरक आहार सिफारिस गर्छ।","Community Health"],
  ["Which study design follows exposed and unexposed groups over time?","Exposure भएका र नभएका समूहलाई समयसँगै पछ्याउने अध्ययन कुन हो?",["Cohort study","Case report","Cross-sectional study","Case series"],0,"A cohort study follows groups to compare outcome occurrence over time.","Cohort अध्ययनले समयसँगै समूहहरूमा नतिजा तुलना गर्छ।","Community Health"],
  ["The most appropriate measure during a suspected foodborne outbreak is to:","खाद्यजन्य रोगको प्रकोप शंका हुँदा उपयुक्त कदम के हो?",["Notify public health authority and investigate promptly","Wait until all patients recover","Destroy all records","Give antibiotics to everyone without assessment"],0,"Prompt notification, case finding and source investigation help control outbreaks.","तुरुन्त सूचना, केस खोजी र स्रोत अनुसन्धानले प्रकोप नियन्त्रणमा मद्दत गर्छ।","Community Health"],
  ["Which symptom is a common feature of hypoglycemia?","Hypoglycemia को सामान्य लक्षण कुन हो?",["Sweating and tremor","Slow nail growth","Jaundice","Persistent ankle deformity"],0,"Low blood glucose may cause sweating, tremor, hunger, confusion or seizures.","रगतमा glucose घट्दा पसिना, हात काम्ने, भोक, अन्योल वा दौरा हुन सक्छ।","General Medicine"],
  ["Which finding suggests dehydration in a child?","बालबालिकामा dehydration को संकेत कुन हो?",["Sunken eyes and reduced urine","Excessive tears","Frequent urination with moist mouth","Rapid weight gain"],0,"Sunken eyes, thirst, poor drinking and reduced urine can indicate dehydration; assess using current IMNCI guidance.","आँखा गाडिनु, तिर्खा, कम पिउनु र पिसाब कम हुनु dehydration का संकेत हुन सक्छन्; IMNCI अनुसार मूल्याङ्कन गर्नुहोस्।","General Medicine"],
  ["Which condition commonly causes wheezing due to reversible airway narrowing?","श्वासनली साँघुरिँदा wheezing हुने सामान्य रोग कुन हो?",["Asthma","Appendicitis","Nephritis","Osteoarthritis"],0,"Asthma involves variable airway inflammation and narrowing, often causing wheeze and breathlessness.","Asthma मा श्वासनलीमा सूजन र साँघुरोपन बदलिँदै जान्छ, जसले wheeze र सास कष्ट गराउँछ।","General Medicine"],
  ["A classic symptom of pulmonary tuberculosis is:","फोक्सोको क्षयरोगको सामान्य लक्षण कुन हो?",["Persistent cough, sometimes with blood","Sudden toothache only","Ear discharge only","Acute ankle swelling"],0,"Pulmonary TB may cause prolonged cough, fever, night sweats, weight loss and sometimes hemoptysis.","फोक्सोको TB मा लामो खोकी, ज्वरो, राति पसिना, तौल घट्नु र कहिलेकाहीँ खकारमा रगत आउन सक्छ।","General Medicine"],
  ["Which symptom is most concerning for meningitis?","Meningitis को शंकामा कुन लक्षण बढी चिन्ताजनक हुन्छ?",["Fever with neck stiffness and altered consciousness","Mild seasonal sneezing","Isolated callus","Hair loss"],0,"Fever, neck stiffness, severe headache and altered mental status require urgent assessment.","ज्वरो, घाँटी कडापन, कडा टाउको दुखाइ र चेतना परिवर्तनमा तुरुन्त जाँच आवश्यक हुन्छ।","General Medicine"],
  ["Which is a common feature of hypothyroidism?","Hypothyroidism को सामान्य विशेषता कुन हो?",["Cold intolerance and fatigue","Heat intolerance and tremor only","Excessive thirst only","Sudden hearing loss"],0,"Reduced thyroid hormone may cause fatigue, cold intolerance, constipation and weight gain.","Thyroid hormone कम हुँदा थकान, चिसो सहन नसक्नु, कब्जियत र तौल बढ्न सक्छ।","General Medicine"],
  ["Which finding may indicate severe pneumonia in a young child?","सानो बालबालिकामा गम्भीर pneumonia को संकेत कुन हुन सक्छ?",["Chest indrawing or danger signs","Normal feeding and play","Mild isolated rash","Normal breathing"],0,"Chest indrawing, hypoxemia or general danger signs need urgent assessment and referral according to IMNCI.","छाती भित्र तानिनु, hypoxemia वा सामान्य खतरा संकेत भए IMNCI अनुसार तुरुन्त जाँच र referral चाहिन्छ।","General Medicine"],
  ["Which condition is characterized by inflammation of the liver?","कलेजोमा सूजन हुने अवस्थालाई के भनिन्छ?",["Hepatitis","Gastritis","Nephrosis","Arthritis"],0,"Hepatitis means inflammation of the liver and may be caused by viruses, toxins or other conditions.","Hepatitis भनेको कलेजोको सूजन हो; virus, विषाक्त पदार्थ वा अन्य कारण हुन सक्छ।","General Medicine"],
  ["A patient with sudden facial droop, arm weakness and speech difficulty may be having:","अचानक अनुहार बाङ्गिनु, हात कमजोर हुनु र बोली बिग्रनु कुन अवस्थाको संकेत हुन सक्छ?",["Stroke","Otitis externa","Gastritis","Conjunctivitis"],0,"Use a stroke recognition pathway and activate emergency referral immediately; time matters.","Stroke शंका भए तत्काल emergency referral सक्रिय गर्नुहोस्; समय अत्यन्त महत्त्वपूर्ण हुन्छ।","General Medicine"],
  ["Which is an appropriate approach to a patient with depression?","Depression भएका बिरामीसँग उपयुक्त व्यवहार कुन हो?",["Listen without judgment and assess safety, including self-harm risk","Dismiss symptoms as laziness","Promise a guaranteed cure","Stop all prescribed medicines abruptly"],0,"Respectful listening and safety assessment are important; urgent risk requires immediate support and referral.","सम्मानपूर्वक सुन्नु र सुरक्षाको मूल्याङ्कन महत्त्वपूर्ण हुन्छ; तत्काल जोखिम भए तुरुन्त सहयोग र referral चाहिन्छ।","General Medicine"],
  ["Which skin condition is commonly associated with intense itching at night and burrows?","राति धेरै चिलाउने र छालामा साना सुरुङजस्ता दाग हुने रोग कुन हो?",["Scabies","Vitiligo","Acne vulgaris","Alopecia"],0,"Scabies is caused by mites and often causes intense nocturnal itching and burrows.","Scabies mite का कारण हुन्छ र राति धेरै चिलाउने तथा burrow देखिन सक्छ।","General Medicine"],
  ["Which finding is typical of iron-deficiency anemia?","Iron deficiency anemia मा सामान्यतया के देखिन्छ?",["Low hemoglobin with microcytic hypochromic red cells","High hemoglobin with macrocytosis","High platelet count in every case","Normal iron stores"],0,"Iron deficiency commonly produces microcytic, hypochromic anemia; confirm with appropriate tests.","Iron कमीले प्रायः microcytic, hypochromic anemia गराउँछ; उपयुक्त परीक्षणबाट पुष्टि गर्नुपर्छ।","General Medicine"],
  ["Which medicine class is commonly used as a reliever in acute asthma under a treatment plan?","उपचार योजनाअनुसार acute asthma मा छिटो राहतका लागि कुन औषधि समूह प्रयोग हुन्छ?",["Short-acting bronchodilator","Antacid","Antifungal","Anticoagulant"],0,"A short-acting inhaled bronchodilator may be used for rapid relief according to the patient's prescribed plan and current guidelines.","बिरामीको prescribed plan र हालको guideline अनुसार short-acting inhaled bronchodilator छिटो राहतका लागि प्रयोग हुन सक्छ।","Pharmacology"],
  ["Paracetamol is primarily used as:","Paracetamol मुख्यतया केका लागि प्रयोग हुन्छ?",["Analgesic and antipyretic","Antibiotic","Anticoagulant","Antifungal"],0,"Paracetamol relieves pain and reduces fever; dose limits and liver risks must be considered.","Paracetamol ले दुखाइ र ज्वरो घटाउँछ; मात्रा सीमा र कलेजोसम्बन्धी जोखिम विचार गर्नुपर्छ।","Pharmacology"],
  ["Which route generally has the fastest systemic effect in an emergency when appropriately indicated?","आवश्यक अवस्थामा आकस्मिक उपचारमा कुन route ले सामान्यतया छिटो systemic प्रभाव दिन्छ?",["Intravenous","Oral","Topical","Rectal"],0,"Intravenous administration delivers medicine directly into circulation and can act rapidly; it requires trained staff and monitoring.","Intravenous बाट औषधि सिधै रक्तसञ्चारमा पुग्छ र छिटो काम गर्न सक्छ; तालिमप्राप्त कर्मचारी र निगरानी चाहिन्छ।","Pharmacology"],
  ["A contraindication is:","Contraindication भनेको के हो?",["A reason a medicine or procedure should not be used","The brand name of a drug","The price of a medicine","A routine follow-up date"],0,"A contraindication is a condition or factor that makes a treatment inadvisable or unsafe.","कुनै अवस्था वा कारणले उपचार अनुपयुक्त वा असुरक्षित बनाउँछ भने त्यसलाई contraindication भनिन्छ।","Pharmacology"],
  ["Which information is essential when calculating a medicine dose for a child?","बालबालिकाको औषधि मात्रा गणना गर्दा कुन जानकारी आवश्यक हुन्छ?",["Accurate current weight and prescribed dosing guidance","Hair colour","School grade","Shoe size"],0,"Many pediatric doses are weight-based; verify weight, concentration, maximum dose and local protocol.","धेरै बाल औषधिको मात्रा तौलअनुसार हुन्छ; तौल, concentration, अधिकतम मात्रा र स्थानीय protocol जाँच्नुहोस्।","Pharmacology"],
  ["What is the first priority when an unconscious patient is found?","बेहोस बिरामी भेटिँदा पहिलो प्राथमिकता के हो?",["Check responsiveness and call for help; assess airway and breathing","Give oral water","Make the patient stand","Leave the patient alone"],0,"Check response, summon emergency help and assess airway and normal breathing; follow BLS protocol.","प्रतिक्रिया जाँच्नुहोस्, आकस्मिक सहयोग बोलाउनुहोस् र airway तथा सामान्य श्वास जाँचेर BLS protocol पालना गर्नुहोस्।","General Surgery"],
  ["Which position is generally appropriate for a conscious patient with suspected shock while awaiting help, if no injury or breathing issue prevents it?","चेतन अवस्थामा shock शंका भएको र सहयोग पर्खिरहेको बिरामीलाई चोट वा श्वास समस्याले रोक्दैन भने सामान्यतया कुन अवस्था उपयुक्त हुन्छ?",["Lie flat and keep warm","Make the patient walk","Give a large meal","Sit in a hot bath"],0,"Keep the patient lying comfortably and warm; manage the cause and follow emergency protocol. Avoid unnecessary movement.","बिरामीलाई आरामदायी रूपमा सुताएर न्यानो राख्नुहोस्; कारणको व्यवस्थापन र आकस्मिक protocol पालना गर्नुहोस्। अनावश्यक हिँडडुल नगराउनुहोस्।","General Surgery"],
  ["Which action is important after a needle-stick injury?","सुईले घोचेपछि कुन कदम महत्त्वपूर्ण हुन्छ?",["Wash the area promptly and report immediately for risk assessment","Squeeze aggressively and hide the incident","Apply bleach","Wait several weeks before reporting"],0,"Wash with soap and water, report promptly and obtain occupational exposure assessment and indicated PEP without delay.","साबुनपानीले सफा गरी तुरुन्त रिपोर्ट गर्नुहोस् र occupational exposure मूल्याङ्कन तथा आवश्यक PEP ढिलाइ नगरी लिनुहोस्।","General Surgery"],
  ["Which symptom may indicate ectopic pregnancy rupture?","Ectopic pregnancy फुटेको संकेत कुन हुन सक्छ?",["Severe abdominal pain with dizziness or collapse","Mild hunger","Itchy scalp","Chronic mild backache only"],0,"Severe pain, vaginal bleeding, dizziness or collapse in possible pregnancy is an emergency.","गर्भावस्थाको सम्भावनासँगै कडा पेट दुखाइ, रक्तस्राव, चक्कर वा collapse आकस्मिक अवस्था हो।","General Surgery"],
  ["The third stage of labour is the period from birth of the baby until:","प्रसवको तेस्रो चरण बच्चा जन्मेदेखि के निस्किएसम्मको अवधि हो?",["Delivery of the placenta","Onset of contractions","Full cervical dilatation","First antenatal visit"],0,"The third stage ends with delivery of the placenta and membranes.","तेस्रो चरण placenta र membranes निस्किएपछि समाप्त हुन्छ।","General Surgery"],
  ["Which is a common sign of acute appendicitis?","Acute appendicitis को सामान्य संकेत कुन हो?",["Pain that may migrate to the right lower abdomen","Painless jaundice only","Bilateral ear pain","Chronic itchy eyes"],0,"Appendicitis often begins with central abdominal pain that migrates to the right lower quadrant, with nausea or fever.","Appendicitis मा सुरुमा पेटको बीच दुखेर दायाँ तल्लो भागमा सर्न सक्छ; वाकवाकी वा ज्वरो हुन सक्छ।","General Surgery"],
  ["A foreign body in the eye should generally be managed by:","आँखामा बाहिरी वस्तु परेमा सामान्यतया के गर्नुपर्छ?",["Avoid rubbing and arrange assessment; irrigate loose particles if appropriate","Rub the eye firmly","Use sharp instruments to remove it","Apply household chemicals"],0,"Do not rub or attempt removal of embedded objects; irrigate loose superficial particles when safe and refer for assessment.","आँखा नमिच्नुहोस् र गाडिएको वस्तु आफैँ ननिकाल्नुहोस्; सुरक्षित भए सतही कण पानीले पखालेर जाँचका लागि पठाउनुहोस्।","General Surgery"],
  ["Which condition commonly causes ear pain with a bulging tympanic membrane?","कान दुखाइसँग tympanic membrane फुलेको देखिने सामान्य अवस्था कुन हो?",["Acute otitis media","Cataract","Sinus bradycardia","Dermatitis"],0,"Acute otitis media can cause otalgia, fever and a bulging inflamed tympanic membrane.","Acute otitis media मा कान दुख्ने, ज्वरो र tympanic membrane फुलेको देखिन सक्छ।","General Surgery"],
  ["Which is the safest initial action for a suspected fracture?","हड्डी भाँचिएको शंका हुँदा सुरक्षित प्रारम्भिक कदम कुन हो?",["Immobilize in the position found and assess circulation","Force the limb straight","Massage the injured area","Ask the patient to test weight-bearing repeatedly"],0,"Support and immobilize the injured part, check distal circulation and arrange appropriate care.","घाइते भागलाई भेटिएको अवस्थामै सहारा दिएर स्थिर राख्नुहोस्, टाढाको रक्तसञ्चार जाँच्नुहोस् र उपचार मिलाउनुहोस्।","General Surgery"],
  ["Which blood component is mainly responsible for clot formation?","रगत जमाउन मुख्य भूमिका खेल्ने रक्तघटक कुन हो?",["Platelets","Red blood cells","Albumin","Neutrophils"],0,"Platelets adhere and aggregate to form the initial platelet plug in hemostasis.","Platelets टाँसिएर र एकत्रित भएर hemostasis को प्रारम्भिक plug बनाउँछन्।","Clinical Pathology"],
  ["Which test is commonly used to assess average blood glucose over about 2–3 months?","करिब २–३ महिनाको औसत blood glucose मूल्याङ्कन गर्न कुन परीक्षण प्रयोग हुन्छ?",["HbA1c","Bleeding time","Serum bilirubin","Urine microscopy"],0,"HbA1c reflects average glycemia over the preceding weeks to months, commonly about three months.","HbA1c ले पछिल्ला हप्ता/महिनाको औसत glucose देखाउँछ, सामान्यतया करिब तीन महिना।","Clinical Pathology"],

  ["Which structure carries urine from the kidney to the bladder?","मिर्गौलाबाट पिसाब bladder सम्म लैजाने संरचना कुन हो?",["Ureter","Urethra","Renal artery","Nephron"],0,"The ureter transports urine from each kidney to the urinary bladder.","Ureter ले प्रत्येक मिर्गौलाबाट पिसाब urinary bladder सम्म पुर्‍याउँछ।","Anatomy & Physiology"],
  ["Which condition is a common cause of acute watery diarrhea in children?","बालबालिकामा acute watery diarrhea को सामान्य कारण कुन हो?",["Infectious gastroenteritis","Cataract","Osteoporosis","Otitis externa"],0,"Acute gastroenteritis is a common cause; assess dehydration and follow current child-health protocols.","Acute gastroenteritis सामान्य कारण हो; dehydration जाँचेर बालस्वास्थ्य protocol पालना गर्नुहोस्।","General Medicine"],
  ["Which route is preferred for oral rehydration solution in a child who can drink?","पिउन सक्ने बालबालिकालाई ORS दिने उपयुक्त route कुन हो?",["Oral, in frequent small amounts","Intramuscular","Intravenous in every case","Topical"],0,"Give ORS orally in frequent small sips; severe dehydration or inability to drink needs urgent protocol-based care.","ORS मुखबाट थोरै-थोरै गरी पटकपटक दिनुहोस्; गम्भीर dehydration वा पिउन नसक्ने अवस्थामा protocol अनुसार तत्काल उपचार चाहिन्छ।","General Medicine"],
  ["Which laboratory finding is most consistent with bacterial infection in many acute cases?","धेरै acute अवस्थामा bacterial infection सँग मिल्ने laboratory finding कुन हो?",["Neutrophil predominance","Low platelet count in every case","Absent red blood cells","High urine glucose only"],0,"Neutrophilia can support bacterial infection but must be interpreted with clinical findings and other tests.","Neutrophil बढ्नु bacterial infection सँग मिल्न सक्छ, तर clinical अवस्था र अन्य परीक्षणसँगै व्याख्या गर्नुपर्छ।","Clinical Pathology"],
 ];
// Both learning modes use the complete bank, including questions appended below.


 Q.push(
 ["Which vaccine is routinely given at birth in Nepal's national immunization programme?","नेपालको राष्ट्रिय खोप कार्यक्रममा जन्मेपछि नियमित दिइने खोप कुन हो?",["BCG","Measles-rubella","DPT booster","Japanese encephalitis"],0,"BCG is given at birth to protect against severe forms of childhood tuberculosis; follow the current national schedule for all vaccines.","BCG ले बाल्यकालको गम्भीर क्षयरोगबाट सुरक्षा दिन्छ; अन्य खोपका लागि हालको राष्ट्रिय तालिका पालना गर्नुपर्छ।","Community Health"],
 ["The most appropriate first action when a health worker sustains a needle-stick injury is to:","स्वास्थ्यकर्मीलाई सुईले घोचेमा सबैभन्दा पहिले के गर्नुपर्छ?",["Wash the area with soap and running water","Squeeze the wound forcefully","Apply bleach","Ignore it if the needle looks clean"],0,"Wash promptly with soap and water, report immediately and follow the occupational exposure protocol for risk assessment and post-exposure care.","साबुन र बग्ने पानीले तुरुन्त धुनुहोस्, घटना रिपोर्ट गर्नुहोस् र exposure protocol अनुसार जोखिम मूल्याङ्कन तथा आवश्यक उपचार लिनुहोस्।","Community Health"],
 ["Which measure is most effective for preventing faeco-oral transmission at household level?","घरपरिवारमा दिसा–मुख मार्गबाट सर्ने संक्रमण रोक्न सबैभन्दा प्रभावकारी उपाय कुन हो?",["Safe water, sanitation and handwashing","Routine antibiotics for everyone","Avoiding all fruits","Taking vitamin supplements only"],0,"Safe drinking water, sanitation and hand hygiene interrupt faeco-oral transmission.","सुरक्षित पानी, सरसफाइ र हात धुने बानीले दिसा–मुख मार्गबाट संक्रमण सर्न रोक्छ।","Community Health"],
 ["A child with fast breathing and chest indrawing should be:","छिटो श्वास र छाती भित्र तानिने लक्षण भएको बालकलाई के गर्नुपर्छ?",["Urgently assessed and managed according to IMNCI guidelines","Given cough syrup and sent home without assessment","Observed for one week","Treated with an adult dose"],0,"Fast breathing with chest indrawing can indicate severe pneumonia and needs urgent assessment and appropriate referral/treatment under current IMNCI guidance.","छिटो श्वास र छाती भित्र तानिनु गम्भीर निमोनियाको संकेत हुन सक्छ; IMNCI अनुसार तुरुन्त मूल्याङ्कन र आवश्यक उपचार/रेफरल चाहिन्छ।","General Medicine"],
 ["Which finding is a common feature of iron-deficiency anaemia?","Iron-deficiency anaemia मा सामान्यतया कुन अवस्था देखिन्छ?",["Microcytic hypochromic red cells","Macrocytic hyperchromic red cells","Increased serum ferritin","High haemoglobin"],0,"Iron deficiency commonly causes microcytic, hypochromic anaemia with low ferritin, interpreted in clinical context.","Iron को कमीले प्रायः microcytic hypochromic anaemia र ferritin कम गराउँछ।","Clinical Pathology"],
 ["Which test is commonly used to monitor long-term glycaemic control?","लामो समयको रक्तचिनी नियन्त्रण मूल्याङ्कन गर्न कुन परीक्षण प्रयोग हुन्छ?",["HbA1c","Serum amylase","Bleeding time","Widal test"],0,"HbA1c reflects average glycaemia over approximately the preceding 2–3 months.","HbA1c ले पछिल्लो करिब २–३ महिनाको औसत रक्तचिनी अवस्थाबारे जानकारी दिन्छ।","Clinical Pathology"],
 ["Which specimen is generally preferred for routine urine culture?","Routine urine culture का लागि सामान्यतया कुन नमुना उपयुक्त हुन्छ?",["Clean-catch midstream urine","Urine collected from the floor","First drop only in an unclean container","Urine mixed with disinfectant"],0,"A properly collected clean-catch midstream specimen reduces contamination; use a sterile container and timely transport.","सफा तरिकाले संकलित midstream urine ले contamination घटाउँछ; sterile container प्रयोग गरी समयमै प्रयोगशालामा पठाउनुपर्छ।","Clinical Pathology"],
 ["Which route provides the fastest systemic effect in an emergency when immediate access is available?","आपतकालीन अवस्थामा तत्काल पहुँच उपलब्ध हुँदा कुन route बाट systemic effect सबैभन्दा छिटो आउँछ?",["Intravenous","Oral","Topical","Rectal"],0,"Intravenous administration delivers medicine directly into the circulation and has rapid onset, but requires trained staff and appropriate indication.","Intravenous route बाट औषधि सीधै रक्तसञ्चारमा पुग्छ र प्रभाव छिटो सुरु हुन्छ; तालिमप्राप्त व्यक्तिले उचित indication मा मात्र दिनुपर्छ।","Pharmacology & Pharmacy"],
 ["The main purpose of an expiry date on a medicine is to indicate:","औषधिमा expiry date राख्नुको मुख्य उद्देश्य के हो?",["The period for which quality is supported under specified storage conditions","The date the medicine was manufactured only","The date the patient must finish treatment","The price validity"],0,"The expiry date indicates the period during which the manufacturer supports quality when stored as specified; do not use expired products.","निर्धारित अवस्थामा भण्डारण गर्दा औषधिको गुणस्तर कायम रहने अवधिलाई expiry date ले जनाउँछ; म्याद गुज्रेको औषधि प्रयोग गर्नु हुँदैन।","Pharmacology & Pharmacy"],
 ["Which action helps prevent medication errors during dispensing?","औषधि वितरण गर्दा medication error रोक्न कुन उपाय उपयोगी हुन्छ?",["Check patient, medicine, dose, route and instructions","Rely only on package colour","Guess an unclear prescription","Use the same label for all patients"],0,"Systematic prescription review and patient/medicine/dose/route checks reduce dispensing errors; clarify unclear orders with the prescriber.","Prescription जाँच र बिरामी, औषधि, मात्रा तथा route पुष्टि गर्दा गल्ती घट्छ; अस्पष्ट आदेश prescriber सँग स्पष्ट गर्नुपर्छ।","Pharmacology & Pharmacy"],
 ["A patient with suspected stroke develops sudden facial droop and arm weakness. What is the priority?","Stroke शंका भएको बिरामीमा अचानक मुख बाङ्गिनु र हात कमजोर हुनु देखिएमा प्राथमिकता के हो?",["Activate emergency referral immediately and note symptom onset time","Give food and water","Wait until symptoms resolve","Massage the weak arm"],0,"Stroke is time-critical. Activate emergency care immediately, record last-known-well/onset time and do not delay referral.","Stroke मा समय अत्यन्त महत्त्वपूर्ण हुन्छ। तुरुन्त आकस्मिक सेवा सक्रिय गरी लक्षण सुरु भएको समय टिप्नुहोस् र रेफरल ढिला नगर्नुहोस्।","General Surgery"],
 ["What is the first-line immediate response to severe external bleeding?","धेरै बाहिरी रक्तस्राव हुँदा तत्काल पहिलो उपाय के हो?",["Apply firm direct pressure with appropriate dressing","Wash repeatedly without pressure","Give oral fluids first","Remove any embedded object"],0,"Firm direct pressure is the immediate first-aid measure; seek emergency help and do not remove embedded objects.","उचित dressing ले घाउमा दृढ प्रत्यक्ष दबाब दिनु पहिलो प्राथमिक उपचार हो; आकस्मिक सहायता बोलाउनुहोस् र गाडिएको वस्तु ननिकाल्नुहोस्।","General Surgery"],
 ["Which instrument is used to measure blood pressure?","रक्तचाप नाप्न कुन उपकरण प्रयोग हुन्छ?",["Sphygmomanometer","Stethoscope alone","Otoscope","Glucometer"],0,"A sphygmomanometer measures blood pressure; an appropriate cuff size and validated technique are essential.","Sphygmomanometer ले रक्तचाप नाप्छ; सही cuff size र मान्य विधि आवश्यक हुन्छ।","General Medicine"],
 ["Which symptom is a key warning sign of ectopic pregnancy?","Ectopic pregnancy को महत्त्वपूर्ण चेतावनी संकेत कुन हो?",["Lower abdominal pain with vaginal bleeding in early pregnancy","Mild bilateral ankle itching only","Increased appetite alone","Hair loss"],0,"Early pregnancy with abdominal/pelvic pain and vaginal bleeding requires urgent assessment to exclude ectopic pregnancy, especially with dizziness or collapse.","प्रारम्भिक गर्भावस्थामा पेट/पेल्भिक दुखाइ र योनीबाट रक्तस्राव भए ectopic pregnancy हटाउन तुरुन्त जाँच चाहिन्छ, विशेषगरी चक्कर वा बेहोसी भएमा।","General Surgery"],
 ["Which action is essential before a procedure requiring informed consent?","Informed consent आवश्यक पर्ने प्रक्रिया अघि कुन काम अनिवार्य हुन्छ?",["Explain the procedure, benefits, material risks and alternatives and confirm voluntary understanding","Ask a relative to sign without informing the patient","Proceed first and explain later","Use consent as a substitute for clinical assessment"],0,"Valid consent requires understandable information, capacity, voluntariness and an opportunity to ask questions; follow local law and policy.","वैध consent का लागि बुझिने जानकारी, निर्णय क्षमता, स्वेच्छा र प्रश्न सोध्ने अवसर आवश्यक हुन्छ; स्थानीय कानुन र नीति पालना गर्नुपर्छ।","General Surgery"],
 ["Which condition is classically associated with a painless, hard breast lump that needs urgent evaluation?","दुखाइ नहुने कडा breast lump देखिएमा कुन रोगको सम्भावना जाँच्नुपर्छ?",["Breast cancer","Simple muscle cramp","Acute tonsillitis","Otitis externa"],0,"A new breast lump requires clinical assessment; a painless hard lump is a concerning feature but is not diagnostic by itself.","नयाँ breast lump को चिकित्सकीय जाँच आवश्यक हुन्छ; दुखाइ नहुने कडा गाँठो चिन्ताजनक संकेत हो तर यसैले मात्र निदान हुँदैन।","General Surgery"],
 ["Which is the safest principle when giving oxygen to a patient with respiratory distress?","श्वासप्रश्वासमा समस्या भएको बिरामीलाई oxygen दिँदा सुरक्षित सिद्धान्त कुन हो?",["Use prescribed/indicated oxygen, monitor response and titrate to a target saturation","Give the highest flow to every patient without monitoring","Withhold oxygen from all COPD patients","Use oxygen instead of urgent assessment"],0,"Oxygen is a treatment that should be titrated to an appropriate target and monitored; patients at risk of hypercapnic respiratory failure may need a controlled target under protocol.","Oxygen उपचार हो; उपयुक्त target अनुसार मात्रा मिलाएर monitoring गर्नुपर्छ। hypercapnic respiratory failure को जोखिम भएकालाई protocol अनुसार नियन्त्रित target चाहिन्छ।","General Medicine"]
 );


 // Additional NHPC/CTEVT syllabus-aligned questions; reviewed as a separate expansion batch.
 Q.push(
  ["Which component of blood is primarily responsible for transporting oxygen?","रगतको कुन तत्वले मुख्य रूपमा अक्सिजन ओसार्छ?",["Red blood cells","Platelets","Plasma proteins","White blood cells"],0,"Haemoglobin inside red blood cells binds and transports most oxygen from the lungs to tissues.","रातो रक्तकोषभित्रको haemoglobin ले फोक्सोबाट तन्तुसम्म अधिकांश अक्सिजन बोकेर लैजान्छ।","Anatomy & Physiology"],
  ["Which hormone lowers blood glucose by promoting cellular uptake of glucose?","कोशिकाले glucose लिन सहयोग गरेर रगतको चिनी घटाउने हर्मोन कुन हो?",["Insulin","Glucagon","Cortisol","Adrenaline"],0,"Insulin promotes glucose uptake and storage; deficiency or resistance contributes to hyperglycaemia.","Insulin ले glucose कोशिकामा प्रवेश र भण्डारण गर्न सहयोग गर्छ; यसको कमी वा प्रतिरोधले रक्तचिनी बढाउँछ।","Anatomy & Physiology"],
  ["Which part of the nephron is the main site of filtration from blood?","Nephron को कुन भागमा रगतबाट मुख्य filtration हुन्छ?",["Glomerulus","Collecting duct","Loop of Henle","Distal tubule"],0,"The glomerular capillaries filter plasma into Bowman's space to form the initial filtrate.","Glomerulus का capillary बाट plasma Bowman's space मा छानिएर प्रारम्भिक filtrate बन्छ।","Anatomy & Physiology"],
  ["Which cranial nerve is responsible for the sense of smell?","सुँघ्ने क्षमता कुन cranial nerve ले सञ्चालन गर्छ?",["Olfactory nerve (I)","Optic nerve (II)","Facial nerve (VII)","Vagus nerve (X)"],0,"The olfactory nerve carries sensory information for smell from the nasal mucosa.","Olfactory nerve ले नाकको mucosa बाट गन्धसम्बन्धी संवेदना मस्तिष्कसम्म पुर्‍याउँछ।","Anatomy & Physiology"],
  ["A normal adult resting respiratory rate is generally:","आराम अवस्थामा वयस्कको सामान्य श्वासदर सामान्यतया कति हुन्छ?",["12–20 breaths per minute","4–8 breaths per minute","25–35 breaths per minute","40–50 breaths per minute"],0,"A typical adult resting respiratory rate is about 12–20 breaths per minute; interpret it with clinical context.","वयस्कको आराम अवस्थाको सामान्य श्वासदर करिब १२–२० पटक प्रतिमिनेट हुन्छ; बिरामीको अवस्थासँग मिलाएर बुझ्नुपर्छ।","General Medicine"],
  ["Which finding is most suggestive of dehydration in an infant?","शिशुमा पानीको कमी भएको संकेत कुन बढी मिल्दोजुल्दो हो?",["Sunken eyes and reduced urine output","Excessive tears and frequent urination","Rapid weight gain","Moist mouth with normal feeding"],0,"Sunken eyes, poor drinking, lethargy and reduced urine output can indicate dehydration and require assessment of severity.","आँखा गाडिनु, कम पिउनु, सुस्त हुनु र पिसाब कम हुनु dehydration का संकेत हुन सक्छन्; गम्भीरता मूल्याङ्कन गर्नुपर्छ।","General Medicine"],
  ["What is the recommended first action when a conscious adult has suspected hypoglycaemia and can swallow safely?","होसमा रहेको र सुरक्षित रूपमा निल्न सक्ने वयस्कमा hypoglycaemia शंका भए पहिलो कदम के हो?",["Give fast-acting oral glucose","Give long-acting insulin","Restrict all food and drink","Induce vomiting"],0,"If the person is conscious and can swallow, give fast-acting oral glucose and recheck glucose according to protocol; do not give oral intake to an unconscious patient.","बिरामी होसमा छ र निल्न सक्छ भने protocol अनुसार छिटो असर गर्ने oral glucose दिनु र glucose पुनः जाँच्नुहोस्; बेहोसलाई मुखबाट केही नदिनुहोस्।","General Medicine"],
  ["Which symptom is a classic feature of hyperthyroidism?","Hyperthyroidism को सामान्य विशेषता कुन हो?",["Heat intolerance and weight loss","Cold intolerance and weight gain","Slow pulse with marked lethargy only","Persistent constipation only"],0,"Excess thyroid hormone commonly causes heat intolerance, weight loss, tremor, palpitations and increased bowel frequency.","थाइराइड हर्मोन बढी हुँदा गर्मी सहन नसक्नु, तौल घट्नु, कम्पन, धड्कन बढ्नु र दिसा बढ्नु देखिन सक्छ।","General Medicine"],
  ["In a patient with suspected meningitis, which combination is concerning?","Meningitis शंका भएको बिरामीमा कुन लक्षणको संयोजन चिन्ताजनक हुन्छ?",["Fever, headache and neck stiffness","Itchy skin and sneezing","Knee pain after exercise","Mild tooth sensitivity"],0,"Fever, headache and neck stiffness are classic warning features; altered consciousness, seizures or a non-blanching rash require emergency care.","ज्वरो, टाउको दुखाइ र घाँटी कडा हुनु meningitis का मुख्य चेतावनी संकेत हुन्; चेतना बदलिनु, दौरा वा नथिच्दा नहराउने र्‍यास भए आकस्मिक सेवा चाहिन्छ।","General Medicine"],
  ["Which measure is most useful for assessing acute asthma severity at the bedside?","दमको आकस्मिक गम्भीरता bedside मा मूल्याङ्कन गर्न कुन उपाय उपयोगी हुन्छ?",["Ability to speak, respiratory effort and oxygen saturation","Hair colour","Body height alone","Visual acuity"],0,"Speech limitation, accessory muscle use, respiratory rate, air entry and oxygen saturation help assess severity; a silent chest is a danger sign.","बोल्न सक्ने अवस्था, सहायक मांसपेशीको प्रयोग, श्वासदर, हावाको प्रवेश र oxygen saturation ले गम्भीरता बुझाउँछन्; silent chest खतरा संकेत हो।","General Medicine"],
  ["Which infection-control practice is essential before and after every patient contact?","हरेक बिरामीलाई छुनुअघि र छोइसकेपछि कुन संक्रमण नियन्त्रण अभ्यास आवश्यक हुन्छ?",["Hand hygiene","Changing the examination room","Routine antibiotic prophylaxis","Wearing two pairs of gloves instead of hand hygiene"],0,"Hand hygiene at the appropriate moments is a core standard precaution and does not get replaced by gloves.","उचित समयमा हात सफा गर्नु standard precaution को आधार हो; पञ्जाले यसको विकल्प दिन सक्दैन।","Community Health"],
  ["The cold chain in immunization is maintained primarily to:","खोपको cold chain मुख्य रूपमा किन कायम राखिन्छ?",["Preserve vaccine potency","Make vaccines act immediately","Change vaccine colour","Avoid recording batch numbers"],0,"Correct temperature storage protects vaccine potency; monitor and document temperatures and follow national vaccine handling guidance.","सही तापक्रममा भण्डारण गर्दा खोपको प्रभावकारिता जोगिन्छ; तापक्रम निगरानी/अभिलेख गरी राष्ट्रिय निर्देशिका पालना गर्नुपर्छ।","Community Health"],
  ["Which indicator is commonly used to assess acute malnutrition in children aged 6–59 months?","६–५९ महिनाका बालबालिकामा acute malnutrition मूल्याङ्कन गर्न कुन सूचक प्रयोग हुन्छ?",["Weight-for-height/length or MUAC","Head circumference alone","Birth order","Dental eruption chart"],0,"Weight-for-height/length and mid-upper arm circumference (MUAC) are used to identify wasting; interpret using current national/WHO criteria.","Weight-for-height/length र MUAC ले wasting पहिचान गर्न मद्दत गर्छन्; हालको राष्ट्रिय/WHO मापदण्डअनुसार व्याख्या गर्नुपर्छ।","Community Health"],
  ["A disease that is constantly present in a particular area is described as:","कुनै क्षेत्रमा निरन्तर देखिइरहने रोगलाई के भनिन्छ?",["Endemic","Epidemic","Pandemic","Sporadic only"],0,"Endemic describes the usual or constant presence of a disease in a defined geographic population.","Endemic भन्नाले निश्चित भौगोलिक जनसंख्यामा रोग सामान्य वा निरन्तर रूपमा उपस्थित हुनु हो।","Community Health"],
  ["Which study design is best suited to measure prevalence at a single point in time?","एक निश्चित समयमा prevalence मापन गर्न कुन अध्ययन डिजाइन उपयुक्त हुन्छ?",["Cross-sectional study","Randomized controlled trial","Case report","Prospective cohort only"],0,"A cross-sectional study measures exposure and outcome in a defined population at a particular time or short period.","Cross-sectional अध्ययनले निश्चित समयमा वा छोटो अवधिमा जनसंख्याको exposure र outcome मापन गर्छ।","Community Health"],
  ["What is the main purpose of chlorination of drinking water?","पिउने पानीमा chlorination गर्नुको मुख्य उद्देश्य के हो?",["Disinfect water by inactivating many disease-causing microorganisms","Remove all dissolved salts","Increase water hardness","Add nutritional minerals"],0,"Appropriate chlorination disinfects water and reduces transmission of many waterborne pathogens; correct dose and contact time matter.","उचित chlorination ले पानीलाई disinfect गरी धेरै waterborne रोगाणुको प्रसार घटाउँछ; मात्रा र contact time महत्त्वपूर्ण हुन्छ।","Community Health"],
  ["Which route is generally preferred for routine intramuscular vaccination in the anterolateral thigh of an infant?","शिशुको anterolateral thigh मा नियमित intramuscular खोप दिन सामान्यतया कुन route प्रयोग हुन्छ?",["Intramuscular","Intradermal","Intrathecal","Intra-articular"],0,"The anterolateral thigh is a recommended IM site for many infant vaccines; use the vaccine-specific national schedule and correct needle technique.","धेरै शिशु खोपका लागि तिघ्राको अगाडिको बाहिरी भाग उपयुक्त IM site हो; खोपअनुसार राष्ट्रिय तालिका र सही needle technique अपनाउनुहोस्।","Community Health"],
  ["Which medicine class is commonly used as first-line treatment for uncomplicated hypertension in many guidelines, depending on patient factors?","धेरै guideline मा बिरामीको अवस्थाअनुसार uncomplicated hypertension को प्रारम्भिक उपचारमा कुन औषधि समूह प्रयोग हुन सक्छ?",["Thiazide-like diuretics","Antifungal medicines","Antitubercular medicines","Anthelmintics"],0,"Thiazide-like diuretics are one accepted first-line class in many guidelines; selection depends on comorbidities, age, pregnancy status and national protocol.","Thiazide-like diuretics धेरै guideline मा मान्य प्रारम्भिक समूह हो; अन्य रोग, उमेर, गर्भावस्था र राष्ट्रिय protocol अनुसार औषधि छनोट हुन्छ।","Pharmacology & Pharmacy"],
  ["Which adverse effect is commonly associated with oral iron therapy?","मुखबाट दिइने iron औषधिको सामान्य adverse effect कुन हो?",["Constipation and dark stools","Severe hypoglycaemia in all patients","Blue vision","Permanent hearing loss"],0,"Oral iron commonly causes gastrointestinal effects such as nausea, constipation and dark stools; counsel patients and review tolerance.","Oral iron ले वाकवाकी, कब्जियत र दिसा कालो हुनेजस्ता समस्या दिन सक्छ; बिरामीलाई जानकारी दिई सहनसक्ने अवस्था जाँच्नुहोस्।","Pharmacology & Pharmacy"],
  ["What does the term 'contraindication' mean?","'Contraindication' भन्नाले के बुझिन्छ?",["A condition or factor in which a treatment should not be used","The usual dose of a medicine","A medicine's brand name","The time a medicine expires"],0,"A contraindication is a patient condition or circumstance that makes a particular treatment potentially harmful or inappropriate.","Contraindication भनेको कुनै बिरामीको अवस्था वा परिस्थितिमा विशेष उपचार हानिकारक वा अनुपयुक्त हुन सक्ने कारण हो।","Pharmacology & Pharmacy"],
  ["Which information must be checked when calculating a paediatric medicine dose?","बालबालिकाको औषधि मात्रा गणना गर्दा कुन जानकारी जाँच्नुपर्छ?",["Current weight, prescribed dose and concentration","Only the child's age in years","Only the bottle colour","The parent's height"],0,"Many paediatric doses are weight-based; verify current weight, dose units, maximum dose, formulation concentration and prescription independently.","धेरै बाल औषधि तौलअनुसार गणना हुन्छन्; हालको तौल, dose unit, अधिकतम मात्रा, formulation concentration र prescription छुट्टाछुट्टै पुष्टि गर्नुहोस्।","Pharmacology & Pharmacy"],
  ["Which condition is a common contraindication to giving a live attenuated vaccine?","Live attenuated vaccine दिन सामान्यतया कुन अवस्था contraindication हुन सक्छ?",["Severe immunosuppression","Mild common cold without serious illness","Stable mild anaemia","A history of uncomplicated fracture"],0,"Live vaccines may be contraindicated in severe immunosuppression and pregnancy; check the specific vaccine and current national guidance.","गम्भीर immunosuppression र गर्भावस्थामा live vaccine निषेध हुन सक्छ; सम्बन्धित खोप र हालको राष्ट्रिय निर्देशिका जाँच्नुहोस्।","Pharmacology & Pharmacy"],
  ["A patient with a suspected fracture should initially have the injured part:","हड्डी भाँचिएको शंका भएको बिरामीमा सुरुमा चोट लागेको भागलाई के गर्नुपर्छ?",["Immobilized in the position found and assessed for circulation and sensation","Forcefully straightened","Massaged vigorously","Asked to bear weight repeatedly"],0,"Immobilize the limb in the position found, check distal circulation, sensation and movement before and after splinting, and arrange assessment.","अंगलाई भेटिएको अवस्थामै स्थिर राख्नुहोस्; splint अघि/पछि टाढाको रक्तसञ्चार, संवेदना र चलायमानता जाँचेर उपचारका लागि पठाउनुहोस्।","General Surgery"],
  ["Which finding after head injury requires urgent referral?","टाउकोमा चोट लागेपछि कुन संकेतले तुरुन्त referral आवश्यक बनाउँछ?",["Repeated vomiting or decreasing level of consciousness","Mild local tenderness only","A small bruise with normal behaviour","Brief fear without other symptoms"],0,"Repeated vomiting, worsening headache, seizure, focal deficit or declining consciousness may indicate serious brain injury and require emergency evaluation.","बारम्बार बान्ता, बढ्दो टाउको दुखाइ, दौरा, अंग कमजोर हुनु वा चेतना घट्नु गम्भीर मस्तिष्क चोटका संकेत हुन सक्छन्; आकस्मिक जाँच चाहिन्छ।","General Surgery"],
  ["What is the immediate priority for a pregnant woman with convulsions after 20 weeks of gestation?","गर्भावस्थाको २० हप्तापछि दौरा आएको महिलामा तत्काल प्राथमिकता के हो?",["Protect airway and safety, call emergency obstetric help and manage as suspected eclampsia","Give oral fluids during the seizure","Restrain the limbs forcefully","Wait for the seizure to recur"],0,"Convulsions in later pregnancy may be eclampsia. Protect from injury, support airway and urgent referral/treatment under obstetric protocol are essential.","गर्भावस्थाको पछिल्लो चरणमा दौरा eclampsia हुन सक्छ। चोटबाट जोगाउने, airway सुरक्षित गर्ने र obstetric protocol अनुसार तत्काल उपचार/रेफरल आवश्यक हुन्छ।","General Surgery"],
  ["Which instrument is used to examine the external auditory canal and tympanic membrane?","बाहिरी कानको नली र कानको पर्दा हेर्न कुन उपकरण प्रयोग हुन्छ?",["Otoscope","Ophthalmoscope","Laryngoscope","Tuning fork only"],0,"An otoscope provides illumination and magnification to inspect the external auditory canal and tympanic membrane.","Otoscope ले प्रकाश र magnification दिएर बाहिरी कानको नली र tympanic membrane हेर्न सहयोग गर्छ।","General Surgery"],
  ["Which test is commonly used to screen visual acuity at a distance?","टाढाको दृष्टि क्षमता जाँच्न सामान्यतया कुन परीक्षण प्रयोग हुन्छ?",["Snellen chart","Rinne test","Whisper test","Ishihara chart only"],0,"A Snellen chart assesses distance visual acuity; test each eye separately with appropriate correction and standard distance.","Snellen chart ले टाढाको visual acuity जाँच्छ; उपयुक्त चस्मासहित प्रत्येक आँखा छुट्टाछुट्टै र मानक दूरीमा जाँच्नुहोस्।","General Surgery"],
  ["Which blood film finding is characteristic of malaria?","Malaria मा blood film मा कुन विशेषता देखिन सक्छ?",["Plasmodium parasites inside red blood cells","Acid-fast bacilli in sputum","Budding yeast in urine","Adult worms in plasma"],0,"Microscopy of stained thick and thin blood films can identify Plasmodium species and parasite density; rapid tests may also be used.","रङ लगाइएको thick र thin blood film को microscopy बाट Plasmodium प्रजाति र parasite density पहिचान गर्न सकिन्छ; rapid test पनि प्रयोग हुन्छ।","Clinical Pathology"],
  ["Which laboratory value is most directly used to assess platelet quantity?","Platelet को संख्या मूल्याङ्कन गर्न कुन laboratory value प्रयोग हुन्छ?",["Platelet count","Serum sodium","Blood urea","Total bilirubin"],0,"A complete blood count includes platelet count; interpret low or high values with bleeding history, medications and clinical findings.","Complete blood count मा platelet count हुन्छ; कम वा बढी नतिजालाई रक्तस्रावको इतिहास, औषधि र clinical findings सँग मिलाएर बुझ्नुपर्छ।","Clinical Pathology"]
 );


  // Additional bilingual NHPC-aligned questions (reviewed batch).
  Q.push(
  ["Which hormone is released by the posterior pituitary to promote water reabsorption in the kidneys?","मिर्गौलामा पानी पुनःअवशोषण बढाउन posterior pituitary बाट कुन हर्मोन निस्कन्छ?",["Antidiuretic hormone","Thyroxine","Insulin","Cortisol"],0,"Antidiuretic hormone (ADH) increases water reabsorption in renal collecting ducts and helps regulate plasma osmolality.","ADH ले मिर्गौलाको collecting duct मा पानी पुनःअवशोषण बढाएर रगतको osmolarity नियन्त्रण गर्छ।","Anatomy & Physiology"],
  ["Which part of the brain is primarily responsible for coordination and balance?","शरीरको समन्वय र सन्तुलनका लागि मुख्य रूपमा मस्तिष्कको कुन भाग जिम्मेवार हुन्छ?",["Cerebellum","Medulla oblongata","Hypothalamus","Frontal lobe"],0,"The cerebellum coordinates voluntary movement, posture and balance; lesions can cause ataxia.","Cerebellum ले स्वेच्छिक चाल, posture र सन्तुलन मिलाउँछ; यसमा समस्या हुँदा ataxia हुन सक्छ।","Anatomy & Physiology"],
  ["Which blood component is mainly responsible for oxygen transport?","अक्सिजन ओसारपसार गर्ने मुख्य रक्तघटक कुन हो?",["Red blood cells","Platelets","Neutrophils","Plasma proteins"],0,"Haemoglobin inside red blood cells binds and transports most oxygen in blood.","रातो रक्तकोषभित्रको haemoglobin ले रगतमा अधिकांश अक्सिजन बाँधेर ओसार्छ।","Anatomy & Physiology"],
  ["Where does most nutrient absorption occur in the gastrointestinal tract?","पाचन प्रणालीमा अधिकांश पोषक तत्त्व कहाँ अवशोषित हुन्छन्?",["Small intestine","Stomach","Large intestine","Oesophagus"],0,"The small intestine has villi and microvilli that provide a large surface area for nutrient absorption.","सानो आन्द्राका villi र microvilli ले ठूलो सतह क्षेत्र बनाई पोषक तत्त्व अवशोषण गर्छन्।","Anatomy & Physiology"],
  ["Which structure prevents food from entering the trachea during swallowing?","निल्दा खाना trachea मा पस्नबाट कुन संरचनाले रोक्छ?",["Epiglottis","Uvula","Thyroid cartilage","Soft palate"],0,"The epiglottis helps cover the laryngeal inlet during swallowing, reducing aspiration risk.","निल्ने समयमा epiglottis ले larynx को प्रवेशद्वार छोप्न सहयोग गर्छ र aspiration को जोखिम घटाउँछ।","Anatomy & Physiology"],
  ["Which kidney structure is the functional unit responsible for urine formation?","पिसाब निर्माण गर्ने मिर्गौलाको कार्यात्मक एकाइ कुन हो?",["Nephron","Alveolus","Neuron","Hepatic lobule"],0,"Each nephron filters plasma and modifies filtrate through tubular reabsorption and secretion.","प्रत्येक nephron ले plasma filter गरी नलीमा पुनःअवशोषण र secretion मार्फत पिसाब बनाउँछ।","Anatomy & Physiology"],
  ["What is the main purpose of community-based disease surveillance?","समुदायमा आधारित रोग निगरानीको मुख्य उद्देश्य के हो?",["Early detection and prompt reporting of priority diseases","Replacing all hospital services","Counting only hospital beds","Providing treatment without diagnosis"],0,"Community surveillance identifies unusual events and priority diseases early so public health action can begin promptly.","समुदाय निगरानीले असामान्य घटना र प्राथमिकताका रोग चाँडै पहिचान गरी समयमै जनस्वास्थ्य कदम चाल्न मद्दत गर्छ।","Community Health"],
  ["Which measure is most useful for comparing mortality between populations with different age structures?","फरक उमेर संरचना भएका जनसंख्याबीच मृत्यु तुलना गर्न कुन मापन बढी उपयोगी हुन्छ?",["Age-standardized mortality rate","Crude birth count","Total population size","Bed occupancy rate"],0,"Age standardization reduces distortion caused by different age distributions when comparing mortality.","उमेर मानकीकरणले फरक उमेर वितरणका कारण मृत्यु दर तुलना गर्दा हुने विकृति घटाउँछ।","Community Health"],
  ["What is the recommended first action when a suspected outbreak is reported?","शंकास्पद प्रकोपको सूचना आएपछि पहिलो कदम के हुनुपर्छ?",["Verify the diagnosis and existence of an outbreak","Immediately announce a pandemic","Close every health facility","Start antibiotics for the whole community"],0,"Outbreak verification confirms the diagnosis and whether observed cases exceed the expected baseline before further investigation.","प्रकोप पुष्टि गर्दा निदान सही हो कि र केस अपेक्षित स्तरभन्दा बढी छन् कि छैनन् जाँचिन्छ।","Community Health"],
  ["Which method is most appropriate for measuring household access to safe drinking water during a community survey?","समुदाय सर्वेक्षणमा घरपरिवारको सुरक्षित खानेपानी पहुँच मापन गर्न कुन विधि उपयुक्त हुन्छ?",["Structured household interview with source observation","Only asking the local shopkeeper","Measuring household blood pressure","Reviewing school attendance only"],0,"A structured interview combined with observation of the water source gives more reliable information than either alone.","संरचित अन्तर्वार्ता र पानीको स्रोत अवलोकन गर्दा एउटामात्र विधिभन्दा भरपर्दो जानकारी मिल्छ।","Community Health"],
  ["Which intervention most directly reduces iodine deficiency disorders?","आयोडिन कमीसम्बन्धी विकार घटाउन सबैभन्दा प्रत्यक्ष उपाय कुन हो?",["Use of adequately iodized salt","Avoiding all seafood","Routine antibiotics","Reducing drinking water"],0,"Universal salt iodization is a population strategy to prevent iodine deficiency disorders.","आयोडिनयुक्त नुनको सर्वव्यापी प्रयोग आयोडिन कमीका विकार रोक्ने जनसंख्या-स्तरीय उपाय हो।","Community Health"],
  ["In a cold chain, what should be done if a vaccine has been exposed to an uncertain temperature excursion?","खोपको तापक्रम अनिश्चित रूपमा बिग्रिएको शंका भए cold chain मा के गर्नुपर्छ?",["Label and quarantine it pending guidance; do not use until assessed","Discard every vaccine immediately without documentation","Freeze all vials","Use it first without checking"],0,"Quarantine and document the affected stock, maintain recommended storage and seek immunization-program guidance before use or disposal.","प्रभावित खोप छुट्याएर अभिलेख राख्नुहोस्, सही तापक्रममा राखी कार्यक्रमको निर्देशन नआएसम्म प्रयोग वा नष्ट नगर्नुहोस्।","Community Health"],
  ["Which indicator is commonly used to assess the nutritional status of children under five at population level?","पाँच वर्षमुनिका बालबालिकाको पोषण अवस्था जनसंख्या स्तरमा जाँच्न कुन सूचक प्रयोग हुन्छ?",["Weight-for-height","Adult body mass index only","Maternal height only","Head circumference of adults"],0,"Weight-for-height helps identify wasting in children; interpretation should use the appropriate growth standards.","Weight-for-height ले बालबालिकामा wasting पहिचान गर्न मद्दत गर्छ; उपयुक्त growth standard प्रयोग गर्नुपर्छ।","Community Health"],
  ["Which symptom is most characteristic of left-sided heart failure?","बायाँतर्फको heart failure मा कुन लक्षण बढी विशेष हुन्छ?",["Breathlessness, especially on lying flat","Isolated jaundice","Painful urination","Ear discharge"],0,"Left ventricular failure raises pulmonary venous pressure and commonly causes exertional dyspnoea, orthopnoea and pulmonary congestion.","बायाँ ventricular failure ले फोक्सोको शिरागत चाप बढाउँछ र सास फेर्न गाह्रो, सुत्दा सास बढ्ने तथा pulmonary congestion गराउँछ।","General Medicine"],
  ["A patient with fever, neck stiffness and altered consciousness needs urgent assessment for which condition?","ज्वरो, घाँटी कडा र चेतना परिवर्तन भएको बिरामीमा कुन रोगको आकस्मिक मूल्याङ्कन चाहिन्छ?",["Meningitis","Osteoarthritis","Allergic rhinitis","Peptic ulcer"],0,"Fever with neck stiffness and altered mental status is concerning for meningitis or other serious CNS infection and requires urgent referral.","ज्वरो, घाँटी कडा र चेतना परिवर्तन meningitis वा गम्भीर CNS संक्रमणका संकेत हुन सक्छन्; तुरुन्त referral चाहिन्छ।","General Medicine"],
  ["Which finding is a typical feature of iron-deficiency anaemia?","Iron-deficiency anaemia को सामान्य विशेषता कुन हो?",["Microcytic, hypochromic red cells","Macrocytic red cells with high MCV","High platelet destruction in all cases","Increased haemoglobin concentration"],0,"Iron deficiency typically produces microcytosis and hypochromia, although early disease may have normal cell size.","Iron कमीमा प्रायः microcytic र hypochromic red cells देखिन्छन्; सुरुमा cell size सामान्य पनि हुन सक्छ।","General Medicine"],
  ["Which clinical feature is most suggestive of hyperthyroidism?","Hyperthyroidism को बढी संकेत गर्ने clinical feature कुन हो?",["Weight loss with heat intolerance and palpitations","Cold intolerance with weight gain","Slow pulse and constipation","Markedly reduced sweating"],0,"Excess thyroid hormone increases metabolic activity and may cause weight loss, heat intolerance, tremor and tachycardia.","थाइराइड हर्मोन बढी हुँदा metabolism बढेर तौल घट्ने, गर्मी सहन नसक्ने, कम्पन र मुटुको धड्कन बढ्न सक्छ।","General Medicine"],
  ["What is the priority in a patient with suspected stroke whose symptoms began recently?","हालै लक्षण सुरु भएको stroke शंकास्पद बिरामीमा प्राथमिकता के हो?",["Urgent referral to a stroke-capable facility after ABC assessment and time documentation","Give food and water immediately","Wait several hours to see if weakness resolves","Lower blood pressure rapidly without assessment"],0,"Stroke is time-critical. Record last-known-well time, assess ABC and glucose if available, and arrange urgent transfer under protocol.","Stroke मा समय अत्यन्त महत्त्वपूर्ण हुन्छ। अन्तिम पटक सामान्य देखिएको समय लेखी ABC र उपलब्ध भए glucose जाँचेर protocol अनुसार तुरुन्त पठाउनुहोस्।","General Medicine"],
  ["Which symptom commonly accompanies gastro-oesophageal reflux disease?","Gastro-oesophageal reflux disease मा कुन लक्षण सामान्य हुन्छ?",["Burning sensation behind the sternum after meals","Painless blood in urine","Sudden loss of hearing","Painful swollen knee"],0,"GERD commonly causes heartburn and regurgitation, often worse after meals or when lying down.","GERD मा प्रायः छातीको पछाडि पोल्ने र अमिलो पानी फर्किने हुन्छ, खाना पछि वा सुतेपछि बढ्न सक्छ।","General Medicine"],
  ["Which sign in a child with diarrhoea suggests severe dehydration?","पखाला लागेको बालबालिकामा कुन संकेतले गम्भीर निर्जलीकरण जनाउँछ?",["Lethargy or unconsciousness with very slow skin pinch","Normal drinking and alertness","Moist mouth and normal urine","Playful behaviour"],0,"Lethargy or unconsciousness, inability to drink and very slow skin pinch are danger signs requiring urgent management and referral.","सुस्त वा बेहोस हुनु, पिउन नसक्नु र छाला धेरै ढिलो फर्कनु खतरा संकेत हुन्; तत्काल व्यवस्थापन र referral चाहिन्छ।","General Medicine"],
  ["Which medicine is a bronchodilator commonly used for rapid relief of acute asthma symptoms?","तीव्र दमको लक्षण छिटो कम गर्न प्रयोग हुने bronchodilator कुन हो?",["Salbutamol","Amoxicillin","Omeprazole","Metformin"],0,"Salbutamol is a short-acting beta-2 agonist that relaxes bronchial smooth muscle; follow the asthma action plan and assess severity.","Salbutamol छोटो समय काम गर्ने beta-2 agonist हो जसले bronchial muscle खुकुलो बनाउँछ; asthma action plan अनुसार प्रयोग गरी गम्भीरता जाँच्नुहोस्।","Pharmacology & Pharmacy"],
  ["Which route avoids first-pass hepatic metabolism most directly?","First-pass hepatic metabolism लाई प्रत्यक्ष रूपमा छल्ने route कुन हो?",["Sublingual","Oral swallowed tablet","Enteral feeding tube into stomach","Oral capsule"],0,"Sublingual absorption enters systemic venous circulation and largely avoids initial portal passage through the liver.","Sublingual औषधि systemic circulation मा सोझै प्रवेश गर्ने भएकाले सुरुको portal liver passage धेरै हदसम्म छल्छ।","Pharmacology & Pharmacy"],
  ["What is the safest action when a prescription dose is illegible?","Prescription मा औषधिको मात्रा नबुझिने गरी लेखिएको छ भने सुरक्षित कदम के हो?",["Clarify with the prescriber before dispensing or administration","Guess the most common dose","Ask another patient","Double the dose to be safe"],0,"Never guess an unclear prescription; confirm the medicine, dose, route and frequency with the authorized prescriber.","नबुझिने prescription अनुमान गरेर प्रयोग नगर्नुहोस्; औषधि, मात्रा, route र frequency अधिकृत prescriber सँग पुष्टि गर्नुहोस्।","Pharmacology & Pharmacy"],
  ["Which drug group reduces gastric acid secretion by blocking the proton pump?","Proton pump रोकेर gastric acid secretion घटाउने औषधि समूह कुन हो?",["Proton pump inhibitors","Antacids only","Antihistamines H1","Antiplatelets"],0,"Proton pump inhibitors inhibit the gastric parietal-cell H+/K+ ATPase and reduce acid secretion.","Proton pump inhibitor ले gastric parietal cell को H+/K+ ATPase रोक्दै acid secretion घटाउँछ।","Pharmacology & Pharmacy"],
  ["Which instruction is appropriate for a patient prescribed an oral antibiotic course?","मुखबाट खाने antibiotic दिइएको बिरामीलाई कुन निर्देशन उपयुक्त हुन्छ?",["Take it exactly as prescribed and seek advice about missed doses or adverse effects","Share the medicine with family","Stop or extend treatment independently","Save leftover doses for future illness"],0,"Use antibiotics only for the prescribed indication and regimen; do not share or self-adjust, and seek advice for problems.","Antibiotic तोकिएको रोग र regimen अनुसार मात्र लिनुहोस्; अरूसँग बाँड्ने वा आफैँ मात्रा/अवधि बदल्ने नगर्नुहोस्।","Pharmacology & Pharmacy"],
  ["Which adverse reaction after a medicine requires emergency assessment?","औषधि खाएपछि कुन adverse reaction मा आकस्मिक जाँच चाहिन्छ?",["Facial or tongue swelling with breathing difficulty","Mild temporary bitter taste","Brief mild nausea without other symptoms","A single missed dose"],0,"Angioedema with breathing difficulty may indicate life-threatening anaphylaxis; call emergency help and follow the anaphylaxis protocol.","सास फेर्न गाह्रोसँग अनुहार वा जिब्रो सुन्निनु ज्यान जोखिमको anaphylaxis हुन सक्छ; आकस्मिक सहयोग बोलाई protocol पालना गर्नुहोस्।","Pharmacology & Pharmacy"],
  ["What is the first priority when managing an open fracture at the scene?","घटनास्थलमा खुला fracture व्यवस्थापन गर्दा पहिलो प्राथमिकता के हो?",["Control life-threatening bleeding, cover the wound and immobilize the limb","Push exposed bone back into the wound","Wash deeply inside the wound","Allow the patient to walk"],0,"Address major bleeding and overall trauma first, cover the wound with a sterile dressing, immobilize and arrange urgent surgical assessment.","पहिले ठूलो रक्तस्राव र समग्र trauma सम्हाल्नुहोस्, घाउ sterile dressing ले छोप्नुहोस्, अंग स्थिर राखी तुरुन्त शल्य मूल्याङ्कन गराउनुहोस्।","General Surgery"],
  ["Which finding is most consistent with appendicitis?","Appendicitis सँग बढी मेल खाने लक्षण कुन हो?",["Pain migrating from the periumbilical area to the right lower abdomen","Painless swelling of both ankles","Burning pain only during urination","Bilateral ear pain"],0,"Appendicitis often begins as vague periumbilical pain that migrates to the right lower quadrant, with anorexia, nausea or fever.","Appendicitis मा सुरुमा नाइटो वरिपरि अस्पष्ट दुखाइ भई पछि दायाँ तल्लो पेटतिर सर्न सक्छ; भोक नलाग्ने, वाकवाकी वा ज्वरो हुन सक्छ।","General Surgery"],
  ["What is the recommended immediate first aid for a nosebleed in an alert adult?","होसमा रहेको वयस्कको नाकबाट रगत बगेमा तत्काल प्राथमिक उपचार के हो?",["Sit leaning forward and pinch the soft part of the nose continuously","Tilt the head backward","Lie flat and swallow the blood","Blow the nose forcefully"],0,"Lean forward and pinch the soft nose for 10–15 minutes without repeatedly releasing pressure; seek care if severe or persistent.","अगाडि झुकाएर नाकको नरम भाग १०–१५ मिनेट लगातार थिच्नुहोस्; बीचमा बारम्बार नछोड्नुहोस्। धेरै वा नरोकिएको रक्तस्रावमा उपचार लिनुहोस्।","General Surgery"],
  ["Which condition is a major cause of postpartum haemorrhage?","प्रसवपछिको अत्यधिक रक्तस्रावको प्रमुख कारण कुन हो?",["Uterine atony","Mild morning sickness","Physiological breast engorgement","Normal uterine involution"],0,"Uterine atony is the commonest cause of postpartum haemorrhage; urgent uterine massage, uterotonics and escalation follow protocol.","Uterine atony प्रसवपछिको रक्तस्रावको सबैभन्दा सामान्य कारण हो; protocol अनुसार तुरुन्त uterine massage, uterotonic र थप उपचार आवश्यक हुन्छ।","General Surgery"],
  ["Which symptom is a red flag for acute angle-closure glaucoma?","Acute angle-closure glaucoma को खतरा संकेत कुन हो?",["Severe eye pain with blurred vision, halos and nausea","Mild itching in both eyes","Gradual painless difficulty reading","Watery eyes only in wind"],0,"Acute angle closure can rapidly damage vision and presents with severe painful red eye, blurred vision or halos, headache and nausea.","Acute angle closure ले छिट्टै दृष्टि बिगार्न सक्छ; कडा दुख्ने रातो आँखा, धमिलो दृष्टि/halo, टाउको दुखाइ र वाकवाकी हुन सक्छ।","General Surgery"],
  ["Which action is appropriate for a chemical splash in the eye?","आँखामा रासायनिक पदार्थ परेमा कुन कदम उपयुक्त हुन्छ?",["Immediately irrigate with copious clean water or saline and arrange urgent assessment","Rub the eye firmly","Neutralize with another chemical","Patch the eye without irrigation"],0,"Immediate prolonged irrigation is essential; remove contact lenses if easy, do not delay flushing, and obtain urgent ophthalmic assessment.","तुरुन्त प्रशस्त सफा पानी वा saline ले लामो समय पखाल्नु अत्यावश्यक हुन्छ; सजिलै निस्के contact lens हटाई ढिलाइ नगरी आँखा विशेषज्ञकहाँ पठाउनुहोस्।","General Surgery"],
  ["Which laboratory test is commonly used to assess long-term average blood glucose?","लामो अवधिको औसत रक्त glucose मूल्याङ्कन गर्न कुन परीक्षण प्रयोग हुन्छ?",["HbA1c","Serum amylase","Bleeding time","Serum calcium"],0,"HbA1c reflects glycation of haemoglobin over roughly the preceding 2–3 months and is used in diabetes assessment.","HbA1c ले करिब पछिल्ला २–३ महिनाको haemoglobin glycation देखाउँछ र मधुमेह मूल्याङ्कनमा प्रयोग हुन्छ।","Clinical Pathology"],
  ["Which anticoagulant is commonly present in a tube used for complete blood count?","Complete blood count का लागि प्रयोग हुने tube मा सामान्यतया कुन anticoagulant हुन्छ?",["EDTA","Sodium fluoride only","Plain clot activator","Sodium citrate for coagulation"],0,"EDTA prevents clotting by binding calcium and preserves cellular components for a CBC.","EDTA ले calcium बाँधेर clot बन्न रोक्छ र CBC का लागि रक्तकोषहरू सुरक्षित राख्छ।","Clinical Pathology"],
  ["Which urine finding is most suggestive of a urinary tract infection when accompanied by urinary symptoms?","पिसाबसम्बन्धी लक्षणसँगै कुन urine finding ले urinary tract infection को बढी संकेत गर्छ?",["Leukocyte esterase and nitrite positivity","Glucose alone","Ketones alone","High urine specific gravity alone"],0,"Leukocyte esterase suggests white cells and nitrite may indicate nitrate-reducing bacteria; interpret with symptoms and culture when indicated.","Leukocyte esterase ले सेता रक्तकोष र nitrite ले nitrate घटाउने bacteria को संकेत दिन सक्छ; लक्षण र आवश्यकताअनुसार culture सँग मिलाएर बुझ्नुहोस्।","Clinical Pathology"],
  ["Which specimen is preferred for routine sputum microscopy for pulmonary tuberculosis in a patient able to expectorate?","खकार निकाल्न सक्ने बिरामीमा pulmonary tuberculosis को routine परीक्षणका लागि कुन नमुना उपयुक्त हुन्छ?",["A properly collected sputum specimen","Saliva collected after rinsing","Urine sample","Skin swab"],0,"A good lower-respiratory sputum specimen is preferred; follow the national TB diagnostic algorithm for timing, testing and transport.","तल्लो श्वासप्रश्वासबाट आएको राम्रो खकार नमुना उपयुक्त हुन्छ; समय, परीक्षण र ढुवानीका लागि राष्ट्रिय TB algorithm पालना गर्नुहोस्।","Clinical Pathology"],
  ["What does a positive blood culture most directly indicate?","Positive blood culture ले प्रत्यक्ष रूपमा के जनाउँछ?",["Microorganisms have grown from the blood sample, requiring clinical correlation","The patient definitely has malaria","The haemoglobin is low","The blood group is Rh negative"],0,"A positive culture may identify bloodstream infection, but contaminants are possible; interpret organism, number of sets and clinical condition.","Positive culture ले रगतमा microorganism बढेको देखाउँछ, तर contamination पनि हुन सक्छ; organism, sets को संख्या र बिरामीको अवस्था विचार गर्नुहोस्।","Clinical Pathology"],
  ["Which blood test is commonly used to assess kidney filtration function alongside clinical assessment?","Clinical assessment सँगै मिर्गौलाको filtration function जाँच्न कुन रक्त परीक्षण सामान्य प्रयोग हुन्छ?",["Serum creatinine","Serum bilirubin","Troponin I","Serum amylase"],0,"Serum creatinine is used to estimate glomerular filtration rate, interpreted with age, sex and other patient factors.","Serum creatinine बाट glomerular filtration rate अनुमान गरिन्छ; उमेर, लिङ्ग र अन्य अवस्थासँग मिलाएर बुझ्नुपर्छ।","Clinical Pathology"]
  );


 Q.push(
  ["Which hormone stimulates uterine contraction during labour?","प्रसवमा पाठेघर खुम्चिन कुन hormone ले उत्तेजित गर्छ?",["Oxytocin","Insulin","Thyroxine","Glucagon"],0,"Oxytocin stimulates uterine smooth-muscle contraction and milk ejection.","Oxytocin ले पाठेघरको smooth muscle खुम्च्याउँछ र दूध निस्कन सहयोग गर्छ।","Anatomy & Physiology"],
  ["Which brain structure regulates temperature, hunger and thirst?","तापक्रम, भोक र तिर्खा कुन मस्तिष्क संरचनाले नियमन गर्छ?",["Hypothalamus","Cerebellum","Occipital lobe","Medulla"],0,"The hypothalamus regulates temperature, hunger, thirst and several autonomic functions.","Hypothalamus ले तापक्रम, भोक, तिर्खा र autonomic कार्य नियमन गर्छ।","Anatomy & Physiology"],
  ["What is the main function of pulmonary surfactant?","Pulmonary surfactant को मुख्य काम के हो?",["Reduce alveolar surface tension","Increase blood viscosity","Close bronchioles","Digest particles"],0,"Surfactant lowers alveolar surface tension and helps prevent alveolar collapse.","Surfactant ले alveoli को surface tension घटाएर खुम्चिनबाट जोगाउँछ।","Anatomy & Physiology"],
  ["Which structure connects the middle ear to the nasopharynx?","मध्यकानलाई nasopharynx सँग जोड्ने संरचना कुन हो?",["Eustachian tube","Cochlea","Semicircular canal","External auditory canal"],0,"The Eustachian tube ventilates the middle ear and equalizes pressure.","Eustachian tube ले मध्यकानमा हावा पुर्‍याएर दबाब बराबर गर्छ।","Anatomy & Physiology"],
  ["Where does most gas exchange occur in the lungs?","फोक्सोमा अधिकांश gas exchange कहाँ हुन्छ?",["Alveoli","Trachea","Main bronchi","Pleural cavity"],0,"Alveoli provide a thin surface for oxygen and carbon dioxide diffusion.","Alveoli को पातलो सतहबाट oxygen र carbon dioxide diffusion हुन्छ।","Anatomy & Physiology"],
  ["Which vitamin is required for normal collagen synthesis?","सामान्य collagen निर्माणका लागि कुन vitamin चाहिन्छ?",["Vitamin C","Vitamin D","Vitamin K","Vitamin B12"],0,"Vitamin C is required for collagen hydroxylation and supports wound healing.","Collagen निर्माणमा Vitamin C आवश्यक हुन्छ र घाउ निको हुन सहयोग गर्छ।","Anatomy & Physiology"],
  ["A community reports several watery diarrhoea cases linked to one water source. What is the first action?","एउटै पानीको स्रोतसँग सम्बन्धित धेरै पातलो दिसाका घटना आएमा पहिलो कदम के हो?",["Verify reports and notify the surveillance team","Wait for monthly reporting","Close every clinic","Give antibiotics to all"],0,"Verify the signal, assess cases and shared exposure, and promptly notify surveillance staff.","सूचना पुष्टि गरी बिरामी र साझा exposure मूल्याङ्कन गरेर निगरानी टोलीलाई खबर गर्नुहोस्।","Community Health"],
  ["What is the main purpose of a community health needs assessment?","समुदायको स्वास्थ्य आवश्यकता मूल्याङ्कनको उद्देश्य के हो?",["Identify priority problems and available resources","List staff leave days","Count hospital beds only","Replace clinical examination"],0,"It identifies problems, affected groups, determinants and resources for planning.","यसले स्वास्थ्य समस्या, प्रभावित समूह, कारण र स्रोत पहिचान गरी योजना बनाउन मद्दत गर्छ।","Community Health"],
  ["Which action helps reduce Aedes mosquito breeding near homes?","घर वरिपरि Aedes लामखुट्टेको प्रजनन घटाउन के गर्नुपर्छ?",["Remove stagnant water and cover containers","Keep containers uncovered","Store rain-filled tyres","Spray perfume"],0,"Removing stagnant water and covering or cleaning containers reduces breeding sites.","जमेको पानी हटाउने र भाँडा छोप्ने वा सफा गर्दा प्रजननस्थल घट्छ।","Community Health"],
  ["Which practice prevents cross-contamination during food preparation?","खाना तयार गर्दा cross-contamination रोक्ने अभ्यास कुन हो?",["Separate raw and cooked foods","Use one unwashed board for meat and salad","Leave food uncovered overnight","Taste food to test safety"],0,"Separating raw and cooked foods prevents pathogens contaminating ready-to-eat foods.","काँचो र पकाएको खाना अलग राख्दा रोगाणु तयार खानामा सर्दैनन्।","Community Health"],
  ["What is the purpose of a child growth chart?","बाल वृद्धि चार्टको उद्देश्य के हो?",["Track growth and detect faltering early","Diagnose every infection","Measure intelligence","Replace examination"],0,"Serial plotting of growth indicators identifies faltering and prompts nutrition assessment.","वृद्धि सूचक नियमित लेख्दा वृद्धि कमजोर भएको चाँडै पत्ता लाग्छ।","Community Health"],
  ["A pregnant woman has severe headache, blurred vision and epigastric pain. What is appropriate?","गर्भवती महिलालाई कडा टाउको दुखाइ, धमिलो दृष्टि र माथिल्लो पेट दुखाइ छ। के गर्नुपर्छ?",["Arrange urgent obstetric assessment","Reassure these are normal","Restrict fluids at home","Wait for routine visit"],0,"These may indicate severe pre-eclampsia and require urgent assessment and referral.","यी severe pre-eclampsia का संकेत हुन सक्छन्; तत्काल मूल्याङ्कन र referral चाहिन्छ।","Community Health"],
  ["A patient develops sudden facial droop and one-arm weakness. What is the priority?","बिरामीको अनुहार अचानक बाङ्गियो र एउटा हात कमजोर भयो। प्राथमिकता के हो?",["Suspect stroke and activate emergency referral","Give food and observe overnight","Massage the arm","Routine visit next week"],0,"Sudden facial and arm weakness are FAST warning signs; rapid assessment is time-critical.","अनुहार र हात अचानक कमजोर हुनु stroke का FAST संकेत हुन्; तत्काल मूल्याङ्कन चाहिन्छ।","General Medicine"],
  ["Which feature is commonly associated with hypothyroidism?","Hypothyroidism सँग कुन लक्षण सम्बन्धित हुन्छ?",["Cold intolerance, weight gain and fatigue","Heat intolerance and weight loss","Excessive thirst only","Sudden paralysis"],0,"Low thyroid hormone can cause fatigue, cold intolerance, constipation and weight gain.","Thyroid hormone कम हुँदा थकान, चिसो सहन नसक्नु, कब्जियत र तौल बढ्न सक्छ।","General Medicine"],
  ["An asthma patient cannot speak full sentences and has severe breathlessness. What should be done?","दम भएको बिरामी पूरा वाक्य बोल्न सक्दैन र धेरै सास फेर्न गाह्रो छ। के गर्नुपर्छ?",["Urgent emergency management and reliever treatment","Send home without assessment","Give a sedative","Wait lying flat"],0,"Inability to speak full sentences suggests severe exacerbation requiring urgent treatment.","पूरा वाक्य बोल्न नसक्नु गम्भीर asthma को संकेत हो; तत्काल उपचार चाहिन्छ।","General Medicine"],
  ["Which test supports iron deficiency diagnosis when available?","उपलब्ध भएमा iron deficiency पुष्टि गर्न कुन परीक्षण उपयोगी हुन्छ?",["Serum ferritin","Serum sodium","Troponin","Amylase"],0,"Low ferritin supports depleted iron stores, interpreted with inflammation and clinical findings.","Ferritin कम हुनु iron store घटेको संकेत हो; inflammation र clinical अवस्था पनि विचार गर्नुपर्छ।","General Medicine"],
  ["Which drug class commonly provides rapid relief in acute bronchospasm?","Acute bronchospasm मा छिटो राहत दिने औषधि वर्ग कुन हो?",["Short-acting beta-2 agonist","Anticoagulant","Antifungal","Thyroid hormone"],0,"Salbutamol is a short-acting beta-2 agonist that relaxes bronchial smooth muscle.","Salbutamol ले bronchial smooth muscle खुकुलो पारेर bronchodilation गर्छ।","Pharmacology & Pharmacy"],
  ["What should be checked before dispensing a look-alike medicine?","मिल्दोजुल्दो देखिने औषधि दिनुअघि के जाँच्नुपर्छ?",["Generic name, strength, dosage form and prescription","Package colour only","Manufacturer logo only","Tablet shape only"],0,"Verification of name, strength, form and prescription helps prevent medication errors.","नाम, strength, dosage form र prescription जाँच्दा औषधि त्रुटि रोक्न सकिन्छ।","Pharmacology & Pharmacy"],
  ["A deep wound has visible bone after a road traffic injury. What is appropriate first aid?","सडक दुर्घटनापछि गहिरो घाउमा हड्डी देखिएको छ। पहिलो सहायता के हो?",["Cover with sterile dressing, control bleeding and refer urgently","Push the bone back","Apply household chemicals","Allow walking"],0,"A suspected open fracture needs bleeding control, sterile covering, immobilization and urgent referral.","Open fracture मा रक्तस्राव नियन्त्रण, sterile dressing, immobilization र referral चाहिन्छ।","General Surgery"],
  ["A patient has a rigid abdomen with guarding and severe pain. What is the priority?","बिरामीको पेट कडा छ, guarding र धेरै दुखाइ छ। प्राथमिकता के हो?",["Urgent surgical assessment","Give laxatives and discharge","Massage abdomen","Delay until tomorrow"],0,"A rigid abdomen with guarding may indicate peritonitis or another surgical emergency.","पेट कडा र guarding हुनु peritonitis वा surgical emergency को संकेत हुन सक्छ।","General Surgery"],
  ["What should be done with clothing stuck to a burn?","जलेको घाउमा कपडा टाँसिएको छ भने के गर्नुपर्छ?",["Do not pull it off; cool with clean running water","Pull it forcefully","Apply toothpaste","Break blisters"],0,"Do not remove material stuck to a burn; cool with clean running water and seek care according to severity.","टाँसिएको कपडा नतान्नुहोस्; सफा बग्ने पानीले चिस्याएर गम्भीरताअनुसार उपचार खोज्नुहोस्।","General Surgery"],
  ["Which specimen is suitable for routine urine culture?","सामान्य urine culture का लागि कुन नमुना उपयुक्त हुन्छ?",["Clean-catch midstream urine in a sterile container","Urine left in a bedpan","Urine mixed with disinfectant","Sample in an unclean bottle"],0,"A clean-catch midstream specimen in a sterile container reduces contamination.","Sterile container मा clean-catch midstream urine लिँदा contamination कम हुन्छ।","Clinical Pathology"]
 );


 Q.push(
  ["Which blood test is most useful for monitoring long-term average glycaemic control?","लामो समयको औसत glucose नियन्त्रण हेर्न कुन रक्त परीक्षण उपयोगी हुन्छ?",["HbA1c","Serum sodium","Bleeding time","Serum amylase"],0,"HbA1c reflects average glycaemia over approximately the previous 2–3 months.","HbA1c ले करिब पछिल्ला २–३ महिनाको औसत glucose नियन्त्रण देखाउँछ।","Clinical Pathology"],
  ["Which anticoagulant is commonly used in a tube for a complete blood count?","Complete blood count का लागि प्रयोग हुने tube मा सामान्यतया कुन anticoagulant हुन्छ?",["EDTA","Sodium fluoride","Plain clot activator","Heparin only"],0,"EDTA preserves cellular components and is commonly used for CBC specimens.","EDTA ले रक्तकोषिका सुरक्षित राख्छ र CBC नमुनामा सामान्यतया प्रयोग हुन्छ।","Clinical Pathology"],
  ["Which urine dipstick findings may support a diagnosis of urinary tract infection?","Urinary tract infection को सम्भावना देखाउन urine dipstick मा कुन नतिजा उपयोगी हुन्छ?",["Leukocyte esterase and nitrite","Glucose and ketone only","Bilirubin only","Protein alone"],0,"Leukocyte esterase suggests white cells and nitrite may indicate nitrate-reducing bacteria; results need clinical interpretation.","Leukocyte esterase ले white cells र nitrite ले nitrate घटाउने bacteria को संकेत दिन सक्छ; clinical अवस्था पनि विचार गर्नुपर्छ।","Clinical Pathology"],
  ["Which sample is preferred for sputum microscopy in suspected pulmonary tuberculosis?","फोक्सोको TB शंका हुँदा microscopy का लागि कुन नमुना उपयुक्त हुन्छ?",["Good-quality deep-cough sputum in a clean leak-proof container","Saliva collected after drinking water","Nasal swab only","Sample mixed with disinfectant"],0,"A deep-cough sputum sample is preferred; follow local instructions for timing, labelling and transport.","गहिरो खोकीबाट आएको sputum नमुना उपयुक्त हुन्छ; समय, label र transport का लागि स्थानीय निर्देशन पालना गर्नुहोस्।","Clinical Pathology"],
  ["What does a positive blood culture usually indicate?","Positive blood culture ले सामान्यतया के संकेत गर्छ?",["Growth of microorganisms from the blood specimen","Low blood glucose","Normal clotting","Reduced haemoglobin only"],0,"A positive culture indicates microbial growth, but contamination must be distinguished from true bloodstream infection.","Positive culture ले सूक्ष्मजीव बढेको देखाउँछ; contamination र वास्तविक bloodstream infection छुट्याउनुपर्छ।","Clinical Pathology"],
  ["Which laboratory test is commonly used to assess kidney filtration alongside clinical assessment?","Clinical assessment सँगै मिर्गौलाको filtration जाँच्न कुन परीक्षण सामान्यतया प्रयोग हुन्छ?",["Serum creatinine","Serum bilirubin","Troponin I","Serum amylase"],0,"Serum creatinine is used to estimate GFR, interpreted with age, sex and clinical context.","Serum creatinine बाट GFR अनुमान गरिन्छ; उमेर, लिङ्ग र clinical अवस्थासँग मिलाएर बुझ्नुपर्छ।","Clinical Pathology"],
  ["Which medicine is commonly used as first-line emergency treatment for anaphylaxis?","Anaphylaxis को आकस्मिक उपचारमा पहिलो प्राथमिकतामा कुन औषधि प्रयोग हुन्छ?",["Intramuscular adrenaline","Oral paracetamol","Topical antifungal","Oral iron"],0,"Intramuscular adrenaline into the anterolateral thigh is first-line treatment; activate emergency support and follow protocol.","जाँघको अगाडिपट्टि-बाहिरी भागमा intramuscular adrenaline पहिलो उपचार हो; आकस्मिक सहयोग बोलाएर protocol पालना गर्नुपर्छ।","Pharmacology & Pharmacy"],
  ["Which instruction is safest when a patient is prescribed an antibiotic?","Antibiotic दिइएको बिरामीलाई कुन निर्देशन सुरक्षित हुन्छ?",["Take exactly as prescribed and seek advice about adverse effects or missed doses","Share tablets with family","Save leftover doses for the next illness","Stop or extend treatment without advice"],0,"Use antibiotics only as prescribed; do not share or save them, and contact a clinician if a dose is missed or adverse effects occur.","Antibiotic prescription अनुसार मात्र लिनुहोस्; अरूलाई नदिनुहोस्, बाँकी नराख्नुहोस् र dose छुटे वा side effect भए स्वास्थ्यकर्मीसँग सल्लाह लिनुहोस्।","Pharmacology & Pharmacy"],
  ["Which route avoids first-pass metabolism for a medicine absorbed under the tongue?","जिब्रोमुनि अवशोषित हुने औषधिको कुन route ले first-pass metabolism टार्छ?",["Sublingual","Oral swallowed","Rectal in all cases","Intragastric"],0,"Sublingual absorption enters systemic circulation through oral mucosa and largely bypasses initial hepatic first-pass metabolism.","Sublingual औषधि मुखको mucosa बाट रगतमा पुग्ने भएकाले प्रारम्भिक hepatic first-pass metabolism धेरै हदसम्म टर्छ।","Pharmacology & Pharmacy"],
  ["What should be done if a prescription is illegible or an essential dose is missing?","Prescription पढ्न नसकिने वा आवश्यक dose छुटेको छ भने के गर्नुपर्छ?",["Clarify with the prescriber before dispensing","Guess the dose from memory","Ask another patient","Dispense the most common strength"],0,"Never guess unclear prescription details; verify them with the prescriber to prevent medication errors.","नबुझिने prescription को विवरण अनुमान नगर्नुहोस्; औषधि त्रुटि रोक्न prescriber सँग पुष्टि गर्नुहोस्।","Pharmacology & Pharmacy"],
  ["Which medicine group reduces gastric acid secretion by inhibiting the proton pump?","Proton pump रोक्दै पेटको acid secretion घटाउने औषधि समूह कुन हो?",["Proton pump inhibitors","Antacids only","Antihistamines H1","Anthelmintics"],0,"Proton pump inhibitors suppress gastric acid secretion by inhibiting the gastric H+/K+ ATPase.","Proton pump inhibitors ले gastric H+/K+ ATPase रोक्दै पेटको acid secretion घटाउँछन्।","Pharmacology & Pharmacy"],
  ["A patient has sudden severe abdominal pain and repeated vomiting with abdominal distension. What should be considered?","बिरामीलाई अचानक कडा पेट दुखाइ, बारम्बार बान्ता र पेट फुलेको छ। के विचार गर्नुपर्छ?",["Intestinal obstruction or another acute abdominal emergency","Simple seasonal rhinitis","Uncomplicated skin rash","Chronic myopia"],0,"Pain, vomiting and distension may indicate bowel obstruction and need urgent assessment and referral.","दुखाइ, बान्ता र पेट फुल्नु bowel obstruction को संकेत हुन सक्छ; तत्काल मूल्याङ्कन र referral चाहिन्छ।","General Surgery"],
  ["What is the appropriate first aid for severe epistaxis?","नाकबाट धेरै रगत बगेमा पहिलो सहायता के हो?",["Sit forward and pinch the soft part of the nose continuously","Tilt the head far backward","Lie flat and swallow blood","Blow the nose repeatedly"],0,"Sit the person leaning forward and pinch the soft nose continuously; seek urgent care if bleeding is severe or persistent.","बिरामीलाई अगाडि झुकाएर नाकको नरम भाग लगातार थिच्नुहोस्; रक्तस्राव धेरै वा नरोकिने भए तत्काल उपचार खोज्नुहोस्।","General Surgery"],
  ["A patient with a suspected fracture has a cold, pale foot and absent distal pulse. What does this suggest?","हड्डी भाँचिएको शंका भएको बिरामीको खुट्टा चिसो, फिक्का र तलको नाडी छैन। यसले के देखाउँछ?",["Possible vascular compromise requiring emergency referral","Normal fracture healing","Simple muscle fatigue","A minor skin allergy"],0,"A cold pale limb with absent pulse suggests impaired blood flow and is a limb-threatening emergency.","चिसो, फिक्का अंग र नाडी नहुनु रक्तप्रवाह अवरुद्ध भएको संकेत हो; अंग जोखिममा पर्ने आकस्मिक अवस्था हो।","General Surgery"],
  ["Which action reduces the risk of pressure injury in an immobile patient?","चल्न नसक्ने बिरामीमा pressure injury को जोखिम घटाउने उपाय कुन हो?",["Regular repositioning and skin inspection with an individualized plan","Massage reddened bony areas vigorously","Keep wet linen under the patient","Avoid nutrition assessment"],0,"Individualized repositioning, pressure redistribution, moisture management and skin checks reduce pressure injury risk.","व्यक्तिअनुसार नियमित position परिवर्तन, pressure घटाउने व्यवस्था, छाला सफा-सुक्खा राख्ने र जाँच गर्दा जोखिम घट्छ।","General Surgery"],
  ["Which cell type is primarily responsible for antibody production after differentiation?","Differentiation पछि antibody उत्पादन गर्ने मुख्य कोषिका कुन हो?",["Plasma cell","Neutrophil","Platelet","Erythrocyte"],0,"Activated B lymphocytes can differentiate into plasma cells that secrete antibodies.","सक्रिय B lymphocyte plasma cell मा परिवर्तन भई antibody उत्पादन गर्छ।","Anatomy & Physiology"],
  ["Which clinical sign is most consistent with left-sided heart failure?","Left-sided heart failure सँग बढी मिल्ने clinical sign कुन हो?",["Breathlessness and lung crackles","Isolated ankle rash","Ear discharge","Painless enlarged thyroid"],0,"Left ventricular failure can cause pulmonary congestion, dyspnoea and crackles on auscultation.","Left ventricular failure हुँदा फोक्सोमा congestion भएर सास फेर्न गाह्रो र crackles सुनिन सक्छ।","General Medicine"],
  ["Which condition is a common cause of acute unilateral painful red eye with halos and nausea?","एकातिरको आँखा अचानक दुख्ने, रातो हुने, बत्ती वरिपरि घेरा देखिने र वाकवाकी हुने अवस्थाको सम्भावित कारण के हो?",["Acute angle-closure glaucoma","Simple refractive error","Chronic dry eye","Allergic rhinitis"],0,"Acute angle-closure glaucoma is an ophthalmic emergency requiring immediate specialist assessment.","Acute angle-closure glaucoma आँखाको आकस्मिक अवस्था हो; तत्काल विशेषज्ञ मूल्याङ्कन चाहिन्छ।","General Medicine"]
 );


 Q.push(
  ["Which part of the nephron is the main site of glucose reabsorption under normal conditions?","सामान्य अवस्थामा nephron को कुन भागमा glucose को अधिकांश पुनःअवशोषण हुन्छ?",["Proximal convoluted tubule","Loop of Henle","Distal convoluted tubule","Collecting duct"],0,"Most filtered glucose is reabsorbed in the proximal convoluted tubule.","छानिएको glucose को अधिकांश proximal convoluted tubule मा पुनःअवशोषित हुन्छ।","Anatomy & Physiology"],
  ["Which chamber receives deoxygenated blood from the systemic veins?","शरीरका systemic vein बाट oxygen कम भएको रगत कुन chamber मा आउँछ?",["Right atrium","Left atrium","Left ventricle","Aorta"],0,"The right atrium receives systemic venous blood through the superior and inferior vena cava.","Right atrium ले superior र inferior vena cava बाट शरीरको venous blood लिन्छ।","Anatomy & Physiology"],
  ["Which structure is the primary site of fertilization in humans?","मानिसमा fertilization सामान्यतया कहाँ हुन्छ?",["Ampulla of the uterine tube","Cervix","Uterine cavity","Vagina"],0,"Fertilization most commonly occurs in the ampulla of the uterine tube.","Fertilization प्रायः uterine tube को ampulla भागमा हुन्छ।","Anatomy & Physiology"],
  ["Which hormone lowers blood glucose by promoting cellular uptake?","कोषिकाले glucose लिन सहयोग गरेर रगतको glucose घटाउने hormone कुन हो?",["Insulin","Glucagon","Cortisol","Adrenaline"],0,"Insulin promotes glucose uptake in several tissues and supports storage as glycogen and fat.","Insulin ले विभिन्न tissue मा glucose प्रवेश र glycogen तथा fat का रूपमा भण्डारण बढाउँछ।","Anatomy & Physiology"],
  ["Which type of joint permits movement in multiple directions, such as at the shoulder?","काँधमा जस्तै धेरै दिशामा चल्न दिने joint कुन प्रकारको हो?",["Ball-and-socket joint","Hinge joint","Pivot joint","Fixed suture"],0,"The shoulder is a ball-and-socket synovial joint allowing movement in several planes.","काँध ball-and-socket synovial joint हो, जसले धेरै दिशामा movement दिन्छ।","Anatomy & Physiology"],
  ["What is the main purpose of community mapping before a health programme?","स्वास्थ्य कार्यक्रमअघि community mapping गर्नुको मुख्य उद्देश्य के हो?",["Locate households, services and vulnerable groups","Replace disease surveillance","Count only private hospitals","Select medicine brands"],0,"Mapping helps identify population distribution, service locations and underserved or vulnerable groups.","Mapping ले जनसंख्या, सेवा केन्द्र र सेवा नपुगेका वा जोखिममा रहेका समूह पहिचान गर्छ।","Community Health"],
  ["Which method is most appropriate for collecting information about household sanitation practices?","घरपरिवारको सरसफाइ अभ्यासबारे जानकारी लिन कुन विधि उपयुक्त हुन्छ?",["Structured household interview and observation","Only hospital admission register","Only pharmacy sales record","Random guess"],0,"A structured interview combined with direct observation gives useful information on sanitation practices.","संरचित घरभेट अन्तर्वार्ता र प्रत्यक्ष अवलोकनले सरसफाइ अभ्यासबारे उपयोगी जानकारी दिन्छ।","Community Health"],
  ["What does herd immunity mean?","Herd immunity भन्नाले के बुझिन्छ?",["Indirect protection when enough people are immune, reducing transmission","Everyone must receive antibiotics","A disease becomes non-infectious in all cases","Only older adults are protected"],0,"When a sufficient proportion of a population is immune, transmission becomes less likely and susceptible people gain indirect protection.","जनसंख्याको पर्याप्त भागमा प्रतिरक्षा हुँदा रोग सर्ने सम्भावना घट्छ र संवेदनशील व्यक्तिलाई अप्रत्यक्ष सुरक्षा मिल्छ।","Community Health"],
  ["Which household measure helps prevent diarrhoeal disease transmission?","घरपरिवारमा पखाला सर्ने जोखिम घटाउने उपाय कुन हो?",["Handwashing with soap after defecation and before food handling","Sharing unwashed utensils","Storing drinking water uncovered","Disposing faeces near water sources"],0,"Handwashing with soap at critical times reduces faecal-oral transmission.","शौचपछि र खाना सम्हाल्नुअघि साबुनपानीले हात धुँदा faecal-oral transmission घट्छ।","Community Health"],
  ["Why is health data disaggregation by sex, age and location useful?","स्वास्थ्य तथ्याङ्कलाई लिङ्ग, उमेर र स्थानअनुसार छुट्याउनु किन उपयोगी हुन्छ?",["Reveal inequalities and groups needing targeted services","Make data harder to interpret","Remove the need for analysis","Ensure all groups have identical risks"],0,"Disaggregation can reveal differences in access and outcomes that overall averages may hide.","विभाजन गरिएको तथ्याङ्कले समग्र औसतले लुकाउने सेवा पहुँच र नतिजाका असमानता देखाउँछ।","Community Health"],
  ["A patient with fever has a non-blanching rash and appears very unwell. What is the priority?","ज्वरो भएको बिरामीको छालामा थिच्दा नफिक्का हुने rash छ र अवस्था गम्भीर देखिन्छ। प्राथमिकता के हो?",["Urgent emergency assessment for possible sepsis or meningococcal disease","Routine review after a week","Apply cosmetic cream","Advise vigorous exercise"],0,"A non-blanching rash with systemic illness is a red flag requiring immediate emergency assessment.","शरीर बिरामी भएको अवस्थामा नफिक्का हुने rash गम्भीर खतरा संकेत हो; तत्काल आकस्मिक मूल्याङ्कन चाहिन्छ।","General Medicine"],
  ["Which finding is most consistent with diabetic ketoacidosis?","Diabetic ketoacidosis सँग कुन निष्कर्ष बढी मिल्छ?",["Hyperglycaemia, ketones and metabolic acidosis","Low glucose with no ketones","Isolated high calcium","Low blood pressure after standing only"],0,"DKA involves insulin deficiency, hyperglycaemia, ketonaemia and metabolic acidosis and needs urgent hospital care.","DKA मा insulin कमी, hyperglycaemia, ketone र metabolic acidosis हुन्छ; तत्काल अस्पताल उपचार चाहिन्छ।","General Medicine"],
  ["A patient has crushing central chest pain radiating to the arm with sweating. What should be suspected?","छातीको बीचमा थिचेजस्तो दुखाइ हाततिर सर्छ र पसिना आउँछ। के शंका गर्नुपर्छ?",["Acute coronary syndrome","Simple muscle itch","Otitis externa","Uncomplicated gastritis in every case"],0,"This presentation may indicate acute coronary syndrome and requires urgent emergency evaluation.","यस्तो लक्षण acute coronary syndrome हुन सक्छ; तत्काल आकस्मिक मूल्याङ्कन आवश्यक हुन्छ।","General Medicine"],
  ["Which symptom is a common feature of benign prostatic enlargement?","Benign prostatic enlargement को सामान्य लक्षण कुन हो?",["Hesitancy and weak urinary stream","Sudden loss of vision","Bloody diarrhoea","Severe ear pain"],0,"Prostatic enlargement can cause lower urinary tract symptoms such as hesitancy, weak stream and nocturia.","Prostate बढ्दा पिसाब सुरु गर्न गाह्रो, धार कमजोर र राति पटकपटक पिसाब लाग्न सक्छ।","General Medicine"],
  ["A patient with fever has a painful swollen joint and cannot bear weight. What is the concern?","ज्वरोसँगै जोर्नी सुन्निएको र दुखेको छ, बिरामीले भार राख्न सक्दैन। के चिन्ता हुन्छ?",["Septic arthritis","Simple muscle fatigue","Chronic stable osteoarthritis only","Uncomplicated headache"],0,"A hot swollen joint with fever and inability to bear weight may be septic arthritis, requiring urgent assessment.","ज्वरोसहित तातो सुन्निएको जोर्नी र भार राख्न नसक्नु septic arthritis हुन सक्छ; तत्काल जाँच चाहिन्छ।","General Medicine"],
  ["Which instruction is important when administering an intramuscular injection?","Intramuscular injection दिँदा कुन निर्देशन महत्वपूर्ण हुन्छ?",["Use an appropriate site and needle length based on patient and medicine","Use the same needle for multiple patients","Inject through clothing without assessment","Ignore aseptic technique"],0,"Site, needle length, patient factors and aseptic technique reduce injury and infection risk.","उपयुक्त site, needle length, बिरामीको अवस्था र aseptic technique ले चोट तथा संक्रमणको जोखिम घटाउँछ।","Pharmacology & Pharmacy"],
  ["What is the safest way to dispose of a used hypodermic needle?","प्रयोग भइसकेको hypodermic needle सुरक्षित रूपमा कसरी फाल्नुपर्छ?",["Immediately into a puncture-resistant sharps container","Recap with both hands and place in general waste","Break it by hand","Leave it on the tray"],0,"Dispose of used sharps immediately at the point of use in an approved puncture-resistant container.","प्रयोग भएको sharp वस्तु तुरुन्त प्रयोगस्थलमै स्वीकृत puncture-resistant sharps container मा राख्नुपर्छ।","Pharmacology & Pharmacy"],
  ["Which factor can alter the dose of a medicine in children?","बालबालिकामा औषधिको dose कुन कारणले फरक पर्न सक्छ?",["Body weight and age","Hair colour","Shoe brand","Birth order only"],0,"Paediatric doses often depend on weight, age, indication and maximum recommended dose; verify calculations carefully.","बालबालिकाको dose प्रायः तौल, उमेर, indication र अधिकतम dose मा निर्भर हुन्छ; हिसाब सावधानीपूर्वक जाँच्नुपर्छ।","Pharmacology & Pharmacy"],
  ["A patient with suspected bowel obstruction is vomiting repeatedly. What should be avoided before assessment?","आन्द्रा बन्द भएको शंका र बारम्बार बान्ता भएको बिरामीमा जाँचअघि के गर्नु हुँदैन?",["Giving oral food or fluids until clinically assessed","Urgent referral","Monitoring vital signs","Assessing hydration"],0,"Possible obstruction needs urgent assessment; oral intake may be withheld pending clinical direction and aspiration risk assessment.","आन्द्रा बन्द भएको शंकामा तत्काल जाँच चाहिन्छ; चिकित्सकीय निर्देशन र aspiration जोखिम मूल्याङ्कन नभएसम्म मुखबाट खाना-पानी रोक्नुपर्ने हुन सक्छ।","General Surgery"],
  ["Which action is appropriate for a patient with a suspected hip fracture after a fall?","लडेर hip fracture शंका भएको बिरामीमा कुन कदम उपयुक्त हुन्छ?",["Keep the patient still, support the limb and arrange urgent transfer","Ask the patient to stand and walk","Attempt to straighten the leg forcibly","Massage the hip"],0,"Avoid movement and arrange urgent assessment; check circulation and sensation while minimizing pain and further injury.","बिरामीलाई नचलाइ अंग support गरी तत्काल transfer गर्नुहोस्; रक्तसञ्चार र संवेदना जाँच्दै थप चोट रोक्नुहोस्।","General Surgery"],
  ["Which finding may indicate internal bleeding after abdominal trauma?","पेटमा चोटपछि कुन संकेतले आन्तरिक रक्तस्राव देखाउन सक्छ?",["Pallor, rapid pulse and falling blood pressure","Improved appetite","Stable vital signs with no symptoms","Itchy scalp"],0,"Pallor, tachycardia, hypotension, abdominal tenderness or altered consciousness may indicate internal bleeding and shock.","फिक्कापन, छिटो नाडी, रक्तचाप घट्नु, पेट दुख्नु वा चेतना परिवर्तन आन्तरिक रक्तस्राव र shock का संकेत हुन सक्छन्।","General Surgery"],
  ["What is the appropriate immediate care for a suspected chemical splash in the eye?","आँखामा chemical परेको शंका भए तत्काल के गर्नुपर्छ?",["Irrigate immediately with plenty of clean running water or saline","Patch the eye without washing","Rub the eye","Wait for pain to settle"],0,"Immediate copious irrigation is critical; remove contact lenses if easy and arrange urgent assessment.","तुरुन्त प्रशस्त सफा पानी वा saline ले आँखा पखाल्नु अत्यन्त महत्वपूर्ण हुन्छ; सम्भव भए contact lens हटाएर तत्काल जाँच गराउनुहोस्।","General Surgery"],
  ["Which measure helps prevent postoperative deep vein thrombosis in eligible patients?","उपयुक्त बिरामीमा शल्यक्रियापछि deep vein thrombosis रोक्न कुन उपाय सहयोगी हुन्छ?",["Early mobilization and prescribed thromboprophylaxis","Prolonged unnecessary bed rest","Dehydration","Tight massage of painful calf"],0,"Early mobilization, hydration and prescribed mechanical or pharmacological prophylaxis reduce VTE risk according to patient assessment.","चाँडो चलायमान गराउने, hydration र बिरामीअनुसार prescribed mechanical वा औषधीय prophylaxis ले VTE जोखिम घटाउँछ।","General Surgery"]
 );


 Q.push(
  ["Which organ produces bile?","पित्त (bile) कुन अंगले उत्पादन गर्छ?",["Liver","Pancreas","Spleen","Gallbladder"],0,"The liver produces bile; the gallbladder stores and concentrates it.","Liver ले bile उत्पादन गर्छ; gallbladder ले भण्डारण र गाढा बनाउँछ।","Anatomy & Physiology"],
  ["Which blood vessel carries oxygenated blood from the lungs to the heart?","फोक्सोबाट oxygen भएको रगत मुटुमा ल्याउने रक्तनली कुन हो?",["Pulmonary vein","Pulmonary artery","Vena cava","Aorta"],0,"Pulmonary veins return oxygenated blood from the lungs to the left atrium.","Pulmonary vein ले फोक्सोबाट oxygen भएको रगत left atrium मा ल्याउँछ।","Anatomy & Physiology"],
  ["Which part of the eye controls the amount of light entering the pupil?","Pupil भित्र जाने प्रकाशको मात्रा कुन भागले नियन्त्रण गर्छ?",["Iris","Retina","Cornea","Optic nerve"],0,"The iris changes pupil diameter to regulate incoming light.","Iris ले pupil को आकार परिवर्तन गरी आँखामा जाने प्रकाश नियन्त्रण गर्छ।","Anatomy & Physiology"],
  ["Which structure stores urine before it is expelled?","पिसाब बाहिर निस्कनुअघि कुन संरचनामा जम्मा हुन्छ?",["Urinary bladder","Ureter","Renal cortex","Urethral meatus"],0,"The urinary bladder temporarily stores urine before micturition.","Urinary bladder ले पिसाब बाहिर निकाल्नुअघि अस्थायी रूपमा जम्मा गर्छ।","Anatomy & Physiology"],
  ["Which body system includes lymph nodes and helps return tissue fluid to circulation?","Lymph node समेट्ने र tissue fluid लाई रक्तसञ्चारमा फर्काउन मद्दत गर्ने प्रणाली कुन हो?",["Lymphatic system","Digestive system","Endocrine system","Integumentary system"],0,"The lymphatic system returns interstitial fluid to the bloodstream and supports immune defence.","Lymphatic system ले tissue fluid रक्तसञ्चारमा फर्काउँछ र प्रतिरक्षामा सहयोग गर्छ।","Anatomy & Physiology"],
  ["What is the purpose of a community diagnosis?","Community diagnosis को उद्देश्य के हो?",["Identify and prioritize community health problems","Diagnose an individual patient's fracture","Replace all laboratory tests","Select hospital uniforms"],0,"Community diagnosis uses local data and participation to identify priority health problems and determinants.","Community diagnosis ले स्थानीय तथ्याङ्क र सहभागिताबाट प्राथमिक स्वास्थ्य समस्या र कारण पहिचान गर्छ।","Community Health"],
  ["Which practice is most effective to reduce transmission of respiratory infections in crowded indoor settings?","भीडभाड भएको बन्द कोठामा श्वासप्रश्वास संक्रमण सर्न कम गर्न कुन अभ्यास प्रभावकारी हुन्छ?",["Improve ventilation and use appropriate respiratory hygiene","Keep windows closed at all times","Share drinking cups","Ignore cough etiquette"],0,"Ventilation, respiratory hygiene, staying home when ill and appropriate masking in risk settings reduce transmission.","हावा आवतजावत, श्वासप्रश्वास शिष्टाचार, बिरामी हुँदा घरमै बस्ने र जोखिममा mask ले संक्रमण घटाउँछ।","Community Health"],
  ["Why should a health worker obtain informed consent before a procedure?","प्रक्रिया गर्नुअघि informed consent लिनु किन आवश्यक हुन्छ?",["Respect autonomy after explaining benefits, risks and alternatives","Transfer all responsibility to the patient","Avoid documenting the procedure","Guarantee a successful outcome"],0,"Valid consent requires understandable information, capacity and a voluntary decision; it does not guarantee outcomes.","वैध consent का लागि बुझिने जानकारी, निर्णय क्षमता र स्वेच्छिक निर्णय चाहिन्छ; यसले नतिजाको ग्यारेन्टी गर्दैन।","Community Health"],
  ["Which measure is most useful for assessing acute malnutrition in children aged 6–59 months?","६–५९ महिनाका बालबालिकामा acute malnutrition मूल्याङ्कन गर्न कुन मापन उपयोगी हुन्छ?",["Weight-for-height or length and MUAC","Height-for-age alone","Head circumference alone","Birth order"],0,"Weight-for-height/length, MUAC and bilateral pitting oedema are used to assess acute malnutrition.","Weight-for-height/length, MUAC र दुवै खुट्टामा pitting oedema जाँचेर acute malnutrition मूल्याङ्कन गरिन्छ।","Community Health"],
  ["What is the key role of a female community health volunteer in many Nepal community programmes?","नेपालका धेरै सामुदायिक कार्यक्रममा महिला स्वास्थ्य स्वयंसेविकाको मुख्य भूमिका के हो?",["Community health education, mobilization and linkage to services","Perform major surgery","Prescribe all antibiotics independently","Replace the health facility"],0,"FCHVs support health promotion, community mobilization, selected preventive services and referral linkages within programme guidance.","FCHV ले स्वास्थ्य प्रवर्द्धन, समुदाय परिचालन, तोकिएका preventive सेवा र referral सम्बन्धमा सहयोग गर्छिन्।","Community Health"],
  ["A patient with chronic kidney disease has facial puffiness and reduced urine output. What should be assessed?","दीर्घकालीन मिर्गौला रोग भएको बिरामीको अनुहार सुन्निएको र पिसाब कम भएको छ। के मूल्याङ्कन गर्नुपर्छ?",["Fluid status, blood pressure and renal function","Only hair texture","Hearing acuity","Visual colour perception"],0,"Oedema and oliguria may reflect fluid retention or worsening renal function and need prompt clinical review.","सुन्निनु र पिसाब कम हुनु तरल जम्मा वा मिर्गौलाको अवस्था बिग्रिएको संकेत हुन सक्छ; छिटो जाँच चाहिन्छ।","General Medicine"],
  ["Which symptom is most typical of gastro-oesophageal reflux disease?","Gastro-oesophageal reflux disease को सामान्य लक्षण कुन हो?",["Burning retrosternal discomfort after meals","Painful urination","Sudden unilateral weakness","Painless haematuria"],0,"GERD commonly causes heartburn and regurgitation, often worse after meals or lying down.","GERD मा खाना खाएपछि वा सुतेपछि छाती पोल्ने र अमिलो पानी आउने हुन सक्छ।","General Medicine"],
  ["A patient has fever, productive cough and focal crackles on lung examination. What is a likely diagnosis?","ज्वरो, खकारसहित खोकी र फोक्सोको एउटा भागमा crackles छन्। सम्भावित निदान के हो?",["Pneumonia","Migraine","Dermatitis","Glaucoma"],0,"Fever, cough and focal crackles may indicate pneumonia; severity and oxygenation must be assessed.","ज्वरो, खोकी र focal crackles निमोनियाका संकेत हुन सक्छन्; गम्भीरता र oxygenation जाँच्नुपर्छ।","General Medicine"],
  ["Which symptom may indicate peripheral neuropathy in a patient with diabetes?","मधुमेह भएको बिरामीमा peripheral neuropathy को संकेत कुन हुन सक्छ?",["Numbness or burning in the feet","Improved night vision","Sudden hair whitening","Ear wax accumulation"],0,"Diabetic neuropathy commonly causes distal numbness, tingling, burning or loss of protective sensation.","Diabetic neuropathy मा खुट्टाको टुप्पोमा लाटोपन, झमझम, पोल्ने वा protective sensation हराउन सक्छ।","General Medicine"],
  ["A patient with suspected stroke arrives at a health facility. Which information is especially time-critical?","Stroke शंका भएको बिरामी स्वास्थ्य संस्थामा आइपुग्यो। कुन जानकारी समयका हिसाबले अत्यन्त महत्वपूर्ण हुन्छ?",["Time last known well","Favourite food","Number of siblings","Usual shoe size"],0,"The last-known-well time helps determine eligibility for time-dependent stroke interventions.","Last-known-well समयले समयमै गर्नुपर्ने stroke intervention सम्भव छ कि छैन निर्धारण गर्न मद्दत गर्छ।","General Medicine"],
  ["Which medicine is a commonly used antiplatelet agent?","सामान्यतया प्रयोग हुने antiplatelet औषधि कुन हो?",["Aspirin","Amoxicillin","Omeprazole","Cetirizine"],0,"Aspirin inhibits platelet cyclo-oxygenase and reduces thromboxane A2 production; use depends on indication and bleeding risk.","Aspirin ले platelet cyclo-oxygenase रोकेर thromboxane A2 घटाउँछ; प्रयोग indication र bleeding risk अनुसार हुन्छ।","Pharmacology & Pharmacy"],
  ["What is the main purpose of a medicine stock rotation system using FEFO?","औषधि भण्डारणमा FEFO stock rotation को मुख्य उद्देश्य के हो?",["Dispense items with the earliest expiry date first","Use newest stock first regardless of expiry","Store all medicines in direct sunlight","Ignore expiry dates"],0,"First-expiry-first-out reduces wastage and the risk of dispensing expired medicines.","First-expiry-first-out ले म्याद सकिन लागेको औषधि पहिले प्रयोग गरी wastage र expired medicine वितरणको जोखिम घटाउँछ।","Pharmacology & Pharmacy"],
  ["Which action is important when a patient reports a possible adverse drug reaction?","बिरामीले औषधिको सम्भावित adverse reaction बताएमा कुन कदम महत्वपूर्ण हुन्छ?",["Assess severity, document and report through the appropriate system","Dismiss the report without assessment","Tell the patient to double the dose","Delete the medicine record"],0,"Assess and manage the patient, document the suspected reaction and report according to pharmacovigilance procedures.","बिरामीको अवस्था मूल्याङ्कन र व्यवस्थापन गरी suspected reaction अभिलेख र pharmacovigilance प्रणालीमा report गर्नुपर्छ।","Pharmacology & Pharmacy"],
  ["A patient with a penetrating chest wound has difficulty breathing. What is the priority?","छातीमा छेडिएको घाउ भएको बिरामीलाई सास फेर्न गाह्रो छ। प्राथमिकता के हो?",["Activate emergency care, support breathing and arrange urgent transfer","Remove any deeply embedded object","Give oral fluids","Ask the patient to walk"],0,"Penetrating chest injury with respiratory distress is life-threatening; avoid removing embedded objects and obtain emergency help.","सास गाह्रोसहितको penetrating chest injury जीवन जोखिमपूर्ण हुन्छ; गाडिएको वस्तु ननिकाली आकस्मिक सहयोग लिनुपर्छ।","General Surgery"],
  ["Which sign may suggest compartment syndrome after a limb injury?","अंगमा चोटपछि compartment syndrome को संकेत कुन हुन सक्छ?",["Severe pain out of proportion, especially with passive stretch","Mild itch only","Improving pain and normal sensation","Isolated small bruise without pain"],0,"Disproportionate pain, pain on passive stretch, tense swelling and sensory changes are warning signs requiring emergency surgical assessment.","अत्यधिक दुखाइ, passive stretch गर्दा दुखाइ, कडा सुन्निनु र संवेदना परिवर्तन compartment syndrome का संकेत हुन्; आकस्मिक surgical जाँच चाहिन्छ।","General Surgery"],
  ["Which action is appropriate when a patient has a suspected foreign body embedded in the eye?","आँखामा बाहिरी वस्तु गाडिएको शंका भए कुन कदम उपयुक्त हुन्छ?",["Do not attempt removal; protect the eye and arrange urgent referral","Rub the eye firmly","Press directly on the object","Use tweezers to remove it"],0,"Do not remove an embedded ocular object or apply pressure; shield the eye and refer urgently.","आँखामा गाडिएको वस्तु ननिकाल्नुहोस् र दबाब नदिनुहोस्; आँखा सुरक्षित छोपेर तत्काल referral गर्नुहोस्।","General Surgery"],
  ["What is the first priority in managing a patient with suspected shock?","Shock शंका भएको बिरामीको व्यवस्थापनमा पहिलो प्राथमिकता के हो?",["Rapid ABC assessment and emergency support","Give a large meal","Encourage walking","Delay vital signs until later"],0,"Shock is life-threatening; assess airway, breathing and circulation rapidly, control causes and arrange urgent care.","Shock जीवन जोखिमपूर्ण हुन्छ; airway, breathing र circulation छिटो जाँचेर कारण नियन्त्रण र आकस्मिक उपचार मिलाउनुपर्छ।","General Surgery"],
  ["Which measure helps prevent surgical wound contamination during dressing?","Surgical wound dressing गर्दा संक्रमण/contamination रोक्न कुन उपाय सहयोगी हुन्छ?",["Hand hygiene and aseptic non-touch technique","Reuse contaminated gauze","Touch the wound with bare hands","Keep dressing materials uncovered"],0,"Hand hygiene and aseptic technique reduce transfer of microorganisms into the wound.","Hand hygiene र aseptic technique ले घाउमा सूक्ष्मजीव सर्ने जोखिम घटाउँछ।","General Surgery"]
 );


 Q.push(
  ["Which hormone is primarily responsible for increasing metabolic rate?","शरीरको metabolic rate बढाउन मुख्य भूमिका खेल्ने hormone कुन हो?",["Thyroxine","Insulin","Oxytocin","Prolactin"],0,"Thyroid hormones increase basal metabolic activity and influence growth and development.","Thyroid hormone ले basal metabolic activity बढाउँछ र वृद्धि तथा विकासमा प्रभाव पार्छ।","Anatomy & Physiology"],
  ["Which organ is the main site of absorption of most digested nutrients?","पचेका अधिकांश पोषक तत्त्व अवशोषण हुने मुख्य अंग कुन हो?",["Small intestine","Stomach","Large intestine","Oesophagus"],0,"The small intestine has villi and microvilli that provide a large surface for nutrient absorption.","Small intestine मा villi र microvilli ले पोषक तत्त्व अवशोषणका लागि ठूलो सतह दिन्छन्।","Anatomy & Physiology"],
  ["Which part of the spinal cord carries sensory information toward the brain?","संवेदनाको सूचना मस्तिष्कतर्फ लैजाने spinal cord को भाग कुन हो?",["Dorsal root","Ventral root","Anterior horn","Motor end plate"],0,"Sensory afferent fibres enter the spinal cord through dorsal roots.","Sensory afferent fibre dorsal root बाट spinal cord मा प्रवेश गर्छ।","Anatomy & Physiology"],
  ["Which muscle is the primary muscle of quiet inspiration?","सामान्य शान्त श्वास लिँदा मुख्य काम गर्ने मांसपेशी कुन हो?",["Diaphragm","Rectus abdominis","Internal intercostals","Trapezius"],0,"Contraction of the diaphragm increases thoracic volume during quiet inspiration.","Diaphragm खुम्चिँदा छातीको volume बढ्छ र सामान्य श्वास भित्र जान्छ।","Anatomy & Physiology"],
  ["Which blood group is the universal red-cell donor in an emergency when crossmatching is unavailable?","Crossmatch उपलब्ध नभएको आकस्मिक अवस्थामा universal red-cell donor कुन blood group हो?",["O negative","AB positive","A positive","B negative"],0,"O negative red cells lack A, B and RhD antigens and may be used under emergency transfusion protocols.","O negative red cell मा A, B र RhD antigen हुँदैन; आकस्मिक transfusion protocol अनुसार प्रयोग हुन सक्छ।","Anatomy & Physiology"],
  ["Which approach is most appropriate when planning a community health programme?","समुदाय स्वास्थ्य कार्यक्रम योजना बनाउँदा कुन तरिका उपयुक्त हुन्छ?",["Involve community members in identifying needs and solutions","Plan without local consultation","Use only national averages","Exclude marginalized groups"],0,"Community participation improves relevance, ownership and sustainability of health interventions.","समुदायको सहभागिताले स्वास्थ्य कार्यक्रम सान्दर्भिक, अपनत्वपूर्ण र दिगो बनाउन सहयोग गर्छ।","Community Health"],
  ["Which indicator measures the proportion of people with a disease at a specific point in time?","कुनै निश्चित समयमा रोग भएका व्यक्तिको अनुपात कुन सूचकले मापन गर्छ?",["Point prevalence","Incidence rate","Case fatality rate","Crude birth rate"],0,"Point prevalence measures existing cases in a population at a specified point in time.","Point prevalence ले निश्चित समयमा जनसंख्यामा रहेका कुल विद्यमान केसको अनुपात मापन गर्छ।","Community Health"],
  ["What is the main purpose of contact tracing in an infectious disease outbreak?","संक्रामक रोगको प्रकोपमा contact tracing को मुख्य उद्देश्य के हो?",["Identify exposed contacts for assessment, advice and control measures","Punish people who were exposed","Replace laboratory diagnosis","Stop all community services"],0,"Contact tracing identifies exposed people so they can receive information, monitoring, testing or prophylaxis when indicated.","Contact tracing ले exposure भएका व्यक्तिलाई पहिचान गरी आवश्यक जानकारी, निगरानी, परीक्षण वा prophylaxis दिन मद्दत गर्छ।","Community Health"],
  ["Which water treatment method is commonly recommended for household drinking water when safe piped water is unavailable?","सुरक्षित पाइपको पानी उपलब्ध नभए घरमा पिउने पानी शुद्ध गर्न कुन उपाय सामान्यतया सिफारिस हुन्छ?",["Boiling or correctly chlorinating water","Adding sugar","Leaving water uncovered","Mixing with raw milk"],0,"Boiling or correct chlorination can make water safer when used according to guidance and with safe storage.","निर्देशनअनुसार उमाल्ने वा सही मात्रामा chlorination गर्ने र सुरक्षित भण्डारण गर्दा पानी सुरक्षित हुन्छ।","Community Health"],
  ["Which practice is important for maintaining vaccine cold-chain quality?","खोपको cold-chain गुणस्तर कायम राख्न कुन अभ्यास महत्वपूर्ण हुन्छ?",["Monitor and record refrigerator temperature regularly","Store vaccines in direct sunlight","Ignore temperature excursions","Freeze all vaccines"],0,"Regular temperature monitoring and documentation help maintain vaccine potency and identify cold-chain problems.","नियमित तापक्रम अनुगमन र अभिलेखले खोपको potency जोगाउँछ र cold-chain समस्या पहिचान गर्छ।","Community Health"],
  ["A patient with suspected acute myocardial infarction has chest pain. Which investigation should be arranged urgently where available?","Acute myocardial infarction शंका भएको छाती दुख्ने बिरामीमा उपलब्ध भए कुन जाँच तत्काल गराउनुपर्छ?",["12-lead ECG","Stool culture","Visual acuity chart","Skin prick test"],0,"A 12-lead ECG should be obtained promptly in suspected acute coronary syndrome, alongside clinical assessment and referral.","Acute coronary syndrome शंका हुँदा clinical assessment र referral सँगै 12-lead ECG तुरुन्त गराउनुपर्छ।","General Medicine"],
  ["Which condition commonly causes a butterfly-shaped rash over the cheeks and nasal bridge?","गाला र नाकको पुलमा butterfly-shaped rash कुन रोगमा देखिन सक्छ?",["Systemic lupus erythematosus","Scabies","Tinea pedis","Acute otitis media"],0,"A malar rash can occur in systemic lupus erythematosus, though diagnosis requires broader clinical assessment.","Malar rash systemic lupus erythematosus मा देखिन सक्छ; निदानका लागि अन्य clinical मूल्याङ्कन पनि चाहिन्छ।","General Medicine"],
  ["Which symptom is a warning sign of possible colorectal cancer?","Colorectal cancer को सम्भावित चेतावनी संकेत कुन हो?",["Persistent change in bowel habit or blood in stool","Brief hiccups after meals","Occasional sneezing","Mild seasonal itching"],0,"Persistent bowel habit change, rectal bleeding, unexplained weight loss or iron deficiency anaemia warrants assessment.","दिसा गर्ने बानीमा लगातार परिवर्तन, दिसामा रगत, कारण नखुलेको तौल घट्नु वा iron deficiency anaemia भए जाँच आवश्यक हुन्छ।","General Medicine"],
  ["A patient has sudden severe headache described as the worst ever. What is the priority?","बिरामीले जीवनकै सबैभन्दा कडा अचानक टाउको दुखाइ भएको बताउँछ। प्राथमिकता के हो?",["Urgent emergency assessment for possible intracranial haemorrhage","Routine eye check next month","Give reassurance only","Advise vigorous exercise"],0,"A thunderclap or worst-ever headache is a red flag for subarachnoid haemorrhage and other emergencies.","अचानक अत्यन्त कडा टाउको दुखाइ subarachnoid haemorrhage लगायत आकस्मिक अवस्थाको संकेत हुन सक्छ; तत्काल जाँच चाहिन्छ।","General Medicine"],
  ["Which finding is characteristic of nephrotic syndrome?","Nephrotic syndrome को विशेषता कुन हो?",["Heavy proteinuria with oedema and low serum albumin","Severe isolated neutropenia","High serum calcium only","Persistent wheezing"],0,"Nephrotic syndrome classically involves marked proteinuria, hypoalbuminaemia and oedema, often with hyperlipidaemia.","Nephrotic syndrome मा धेरै proteinuria, रगतमा albumin कम र oedema हुन्छ; hyperlipidaemia पनि हुन सक्छ।","General Medicine"],
  ["Which medicine is an example of an H1 antihistamine?","H1 antihistamine को उदाहरण कुन औषधि हो?",["Cetirizine","Metformin","Amoxicillin","Amlodipine"],0,"Cetirizine blocks peripheral H1 receptors and is used for allergic symptoms.","Cetirizine ले peripheral H1 receptor रोक्छ र एलर्जीका लक्षणमा प्रयोग हुन्छ।","Pharmacology & Pharmacy"],
  ["Why should the medicine dose and expiry date be checked before administration?","औषधि दिनुअघि dose र expiry date किन जाँच्नुपर्छ?",["To reduce medication error and avoid expired products","To make the medicine act faster","To change the prescribed route","To avoid recording administration"],0,"Checking the right medicine, dose, route, patient and expiry is part of safe medication practice.","सही औषधि, dose, route, बिरामी र expiry जाँच्नु सुरक्षित औषधि अभ्यासको भाग हो।","Pharmacology & Pharmacy"],
  ["Which medicine is commonly used as an oral rehydration solution component to support sodium-glucose co-transport?","Sodium-glucose co-transport मार्फत पानी अवशोषण सहयोग गर्ने ORS को मुख्य carbohydrate कुन हो?",["Glucose","Sucrose only","Starch","Lactose"],0,"Glucose facilitates sodium and water absorption through intestinal sodium-glucose co-transport.","Glucose ले आन्द्रामा sodium-glucose co-transport मार्फत sodium र पानी अवशोषणमा सहयोग गर्छ।","Pharmacology & Pharmacy"],
  ["A patient has a crush injury with severe swelling and dark urine. What serious complication should be considered?","Crush injury पछि धेरै सुन्निएको र पिसाब गाढा भएको छ। कुन गम्भीर जटिलता विचार गर्नुपर्छ?",["Rhabdomyolysis with acute kidney injury","Simple allergic rhinitis","Chronic otitis externa","Uncomplicated conjunctivitis"],0,"Muscle breakdown can release myoglobin, causing dark urine and acute kidney injury; urgent hospital assessment is needed.","मांसपेशी बिग्रँदा myoglobin निस्केर गाढा पिसाब र acute kidney injury हुन सक्छ; तत्काल अस्पताल जाँच चाहिन्छ।","General Surgery"],
  ["Which action is appropriate for a patient with a suspected snakebite?","सर्पले टोकेको शंका भएको बिरामीमा कुन कदम उपयुक्त हुन्छ?",["Keep the patient calm, immobilize the limb and arrange urgent transport","Cut and suck the wound","Apply a tight tourniquet","Encourage running to the facility"],0,"Immobilize the patient and bitten limb, avoid harmful traditional measures and arrange prompt medical assessment.","बिरामी र टोकेको अंग स्थिर राख्नुहोस्, घाउ काट्ने वा चुस्ने जस्ता हानिकारक उपाय नगर्नुहोस् र छिटो उपचारमा लैजानुहोस्।","General Surgery"],
  ["Which symptom after surgery may indicate pulmonary embolism?","शल्यक्रियापछि कुन लक्षणले pulmonary embolism को संकेत दिन सक्छ?",["Sudden breathlessness and pleuritic chest pain","Mild itch around a healed scar","Improved appetite","Chronic painless callus"],0,"Sudden dyspnoea, pleuritic chest pain, tachycardia or collapse may indicate pulmonary embolism and need emergency care.","अचानक सास गाह्रो, सास लिँदा छाती दुख्ने, छिटो नाडी वा ढल्नु pulmonary embolism का संकेत हुन सक्छन्; आकस्मिक उपचार चाहिन्छ।","General Surgery"],
  ["Which action should be taken for a patient with a suspected dislocated jaw after trauma?","चोटपछि जबडा खुस्किएको शंका भए कुन कदम चाल्नुपर्छ?",["Support the jaw, assess airway and arrange urgent clinical care","Force the mouth closed","Give hard food to test chewing","Attempt repeated manipulation"],0,"Assess airway and associated trauma, avoid forceful manipulation and arrange urgent assessment by a trained clinician.","Airway र अन्य चोट जाँच्नुहोस्, जबर्जस्ती नचलाउनुहोस् र प्रशिक्षित स्वास्थ्यकर्मीबाट तत्काल जाँच गराउनुहोस्।","General Surgery"],
  ["Which finding suggests a possible postoperative haemorrhage?","शल्यक्रियापछि कुन संकेतले रक्तस्राव भएको देखाउन सक्छ?",["Increasing wound soakage with tachycardia and falling blood pressure","Dry dressing and stable observations","Improving pain","Normal urine output"],0,"Increasing bleeding with tachycardia, hypotension or pallor requires urgent review and haemorrhage management.","ड्रेसिङमा रगत बढ्नु, छिटो नाडी, रक्तचाप घट्नु वा फिक्कापन भए तत्काल जाँच र रक्तस्राव व्यवस्थापन चाहिन्छ।","General Surgery"]
 );


 Q.push(
  ["Which gland secretes cortisol?","Cortisol कुन gland ले स्राव गर्छ?",["Adrenal cortex","Thyroid gland","Pineal gland","Parathyroid gland"],0,"Cortisol is a glucocorticoid produced by the adrenal cortex.","Cortisol adrenal cortex ले उत्पादन गर्ने glucocorticoid hormone हो।","Anatomy & Physiology"],
  ["Which part of the digestive tract absorbs most water from the remaining intestinal contents?","आन्द्रामा बाँकी रहेको सामग्रीबाट धेरै पानी अवशोषण गर्ने भाग कुन हो?",["Large intestine","Oesophagus","Stomach","Duodenum only"],0,"The large intestine absorbs water and electrolytes and helps form stool.","Large intestine ले पानी र electrolyte अवशोषण गरी दिसा बन्न सहयोग गर्छ।","Anatomy & Physiology"],
  ["Which structure carries urine from the kidney to the urinary bladder?","मिर्गौलाबाट urinary bladder सम्म पिसाब लैजाने संरचना कुन हो?",["Ureter","Urethra","Renal artery","Nephron"],0,"The ureter transports urine from the renal pelvis to the bladder by peristaltic activity.","Ureter ले peristalsis मार्फत renal pelvis बाट bladder सम्म पिसाब लैजान्छ।","Anatomy & Physiology"],
  ["Which blood component transports most oxygen?","अधिकांश oxygen बोक्ने रक्तघटक कुन हो?",["Haemoglobin in red blood cells","Platelets","Plasma sodium","White blood cells"],0,"Haemoglobin in erythrocytes binds and transports most oxygen in blood.","Red blood cell को haemoglobin ले रगतमा अधिकांश oxygen बाँधेर बोक्छ।","Anatomy & Physiology"],
  ["Which structure protects the brain and spinal cord?","मस्तिष्क र मेरुदण्डलाई सुरक्षा दिने झिल्लीलाई के भनिन्छ?",["Meninges","Pleura","Peritoneum","Pericardium"],0,"The meninges are protective membranes surrounding the brain and spinal cord.","Meninges मस्तिष्क र मेरुदण्ड वरिपरि रहेका सुरक्षा झिल्ली हुन्।","Anatomy & Physiology"],
  ["Which method helps assess whether a health education session was understood?","स्वास्थ्य शिक्षा सत्र बुझियो कि बुझिएन भनेर कुन तरिकाले मूल्याङ्कन गर्न सकिन्छ?",["Ask participants to explain or demonstrate key messages","Count the number of chairs","Record only the session duration","Assume attendance means understanding"],0,"Teach-back or demonstration checks understanding and identifies points needing clarification.","Teach-back वा प्रदर्शनले बुझाइ जाँच्छ र थप स्पष्ट पार्नुपर्ने कुरा देखाउँछ।","Community Health"],
  ["Which activity is an example of primary prevention?","Primary prevention को उदाहरण कुन हो?",["Immunization before disease occurs","Rehabilitation after stroke","Screening for established complications","Palliative care for advanced disease"],0,"Primary prevention acts before disease develops, for example through immunization and risk reduction.","Primary prevention रोग हुनुअघि गरिन्छ, जस्तै खोप र जोखिम घटाउने उपाय।","Community Health"],
  ["Which rate measures new cases of a disease occurring in a population over a specified period?","निर्धारित अवधिमा जनसंख्यामा देखिएका नयाँ रोगका केस कुन दरले मापन गर्छ?",["Incidence rate","Point prevalence","Case fatality rate","Bed occupancy rate"],0,"Incidence measures new cases over time among the population at risk.","Incidence ले जोखिममा रहेको जनसंख्यामा निश्चित अवधिका नयाँ केस मापन गर्छ।","Community Health"],
  ["What is an important purpose of disease notification?","रोग notification गर्नुको महत्वपूर्ण उद्देश्य के हो?",["Enable timely public-health action and surveillance","Keep cases secret from health authorities","Replace patient care","Increase medicine prices"],0,"Notification allows public-health teams to investigate, monitor trends and implement control measures.","Notification ले जनस्वास्थ्य टोलीलाई अनुसन्धान, प्रवृत्ति अनुगमन र नियन्त्रण उपाय गर्न मद्दत गर्छ।","Community Health"],
  ["Which practice is recommended for safe disposal of household sharps used for injections?","घरमा injection का लागि प्रयोग भएको sharp वस्तु सुरक्षित रूपमा कसरी फाल्नुपर्छ?",["Place immediately in a puncture-resistant sharps container","Mix loose with kitchen waste","Recap and leave on a table","Break by hand"],0,"Sharps should be placed immediately in a puncture-resistant container and disposed of through an approved system.","Sharp वस्तु तुरुन्त puncture-resistant container मा राखेर स्वीकृत प्रणालीबाट व्यवस्थापन गर्नुपर्छ।","Community Health"],
  ["A patient has jaundice, dark urine and pale stools. Which system is most likely involved?","बिरामीको आँखा पहेँलो, पिसाब गाढा र दिसा फिक्का छ। कुन प्रणाली प्रभावित हुन सक्छ?",["Hepatobiliary system","Musculoskeletal system","Auditory system","Integumentary system only"],0,"Jaundice with dark urine and pale stool can indicate hepatobiliary disease or impaired bile flow.","पहेँलोपन, गाढा पिसाब र फिक्का दिसाले hepatobiliary रोग वा bile flow अवरोध देखाउन सक्छ।","General Medicine"],
  ["Which symptom is a typical feature of peptic ulcer disease?","Peptic ulcer disease को सामान्य लक्षण कुन हो?",["Epigastric burning or gnawing pain","Sudden painless hearing loss","Painful red eye only","Ankle deformity"],0,"Peptic ulcer may cause epigastric burning pain, sometimes related to meals; bleeding or perforation are emergencies.","Peptic ulcer मा माथिल्लो पेट पोल्ने वा खानेकुरासँग सम्बन्धित दुखाइ हुन सक्छ; रक्तस्राव वा perforation आकस्मिक अवस्था हुन्।","General Medicine"],
  ["A patient has unilateral calf swelling and tenderness after prolonged immobility. What should be suspected?","लामो समय नचली बसेपछि एउटा पिँडुला सुन्निएको र दुखेको छ। के शंका गर्नुपर्छ?",["Deep vein thrombosis","Simple eczema","Otitis media","Migraine"],0,"Unilateral calf swelling and tenderness can indicate DVT; avoid massaging and arrange prompt clinical assessment.","एउटा पिँडुला सुन्निनु र दुख्नु DVT हुन सक्छ; मालिस नगरी छिटो clinical जाँच गराउनुहोस्।","General Medicine"],
  ["Which finding may indicate severe anaemia?","गम्भीर anaemia को संकेत कुन हुन सक्छ?",["Marked pallor with breathlessness at rest or tachycardia","Normal colour and normal activity","Isolated itchy scalp","Mild seasonal sneezing"],0,"Severe pallor with dyspnoea at rest, tachycardia, chest pain or syncope needs urgent assessment.","धेरै फिक्कापनसँग आराममै सास गाह्रो, छिटो नाडी, छाती दुखाइ वा बेहोस हुनुमा तत्काल जाँच चाहिन्छ।","General Medicine"],
  ["Which test is commonly used to assess oxygen saturation non-invasively?","Oxygen saturation non-invasive रूपमा जाँच्न कुन उपकरण प्रयोग हुन्छ?",["Pulse oximeter","Glucometer","Otoscope","Peak flow meter"],0,"Pulse oximetry estimates peripheral oxygen saturation and should be interpreted with clinical findings.","Pulse oximeter ले peripheral oxygen saturation अनुमान गर्छ; clinical अवस्था पनि विचार गर्नुपर्छ।","General Medicine"],
  ["Which medicine is a commonly used oral antihypertensive calcium-channel blocker?","सामान्यतया प्रयोग हुने oral antihypertensive calcium-channel blocker कुन हो?",["Amlodipine","Salbutamol","Omeprazole","Albendazole"],0,"Amlodipine is a dihydropyridine calcium-channel blocker used for hypertension and angina.","Amlodipine dihydropyridine calcium-channel blocker हो, उच्च रक्तचाप र angina मा प्रयोग हुन्छ।","Pharmacology & Pharmacy"],
  ["What is the purpose of checking drug interactions during dispensing?","औषधि वितरण गर्दा drug interaction जाँच्नुको उद्देश्य के हो?",["Identify combinations that may alter effect or increase harm","Make every medicine stronger","Avoid asking about current medicines","Replace allergy history"],0,"Interaction checks help identify combinations that may reduce efficacy or increase toxicity and adverse effects.","Interaction जाँचले औषधिको प्रभाव घटाउने वा toxicity र adverse effect बढाउने संयोजन पहिचान गर्छ।","Pharmacology & Pharmacy"],
  ["Which storage condition is generally suitable for many medicines unless the label says otherwise?","Label मा फरक निर्देशन नभए धेरै औषधिका लागि सामान्यतया कुन भण्डारण अवस्था उपयुक्त हुन्छ?",["Cool, dry place away from direct sunlight","Hot, humid windowsill","Direct sunlight","Next to a stove"],0,"Many medicines should be stored in a cool, dry place away from light; always follow product-specific label requirements.","धेरै औषधि घामबाट टाढा चिसो र सुख्खा ठाउँमा राख्नुपर्छ; उत्पादनको label निर्देशन पालना गर्नुहोस्।","Pharmacology & Pharmacy"],
  ["A patient has a deep laceration with uncontrolled bleeding. What is the priority?","गहिरो काटिएको घाउबाट रक्तस्राव रोकिएको छैन। प्राथमिकता के हो?",["Apply firm direct pressure and obtain emergency help","Remove all clots repeatedly","Apply soil to the wound","Delay care until bleeding stops"],0,"Firm direct pressure and emergency escalation are priorities for uncontrolled external bleeding.","नियन्त्रण नभएको बाहिरी रक्तस्रावमा कडा प्रत्यक्ष दबाब र आकस्मिक सहयोग प्राथमिकता हुन्।","General Surgery"],
  ["Which finding after a fracture may suggest fat embolism syndrome?","हड्डी भाँचिएपछि कुन संकेतले fat embolism syndrome देखाउन सक्छ?",["Sudden respiratory distress with confusion and petechial rash","Mild local pain only","Improved appetite","Isolated toothache"],0,"Fat embolism can follow long-bone fractures and may cause respiratory distress, neurological changes and petechiae.","लामो हड्डी भाँचिएपछि fat embolism भएर सास गाह्रो, मानसिक परिवर्तन र petechiae देखिन सक्छ।","General Surgery"],
  ["What should be done if a surgical patient develops sudden wound dehiscence with bowel visible?","शल्यक्रियापछि घाउ अचानक खुलेर आन्द्रा देखिएमा के गर्नुपर्छ?",["Cover with sterile saline-moistened dressing and seek emergency surgical help","Push bowel back into abdomen","Allow the patient to eat","Apply dry powder"],0,"Evisceration is a surgical emergency; cover exposed organs with sterile saline-moistened dressings and obtain immediate surgical care.","आन्द्रा बाहिर निस्कनु surgical emergency हो; sterile saline-moistened dressing ले छोपेर तत्काल surgical सहायता लिनुपर्छ।","General Surgery"],
  ["Which action is appropriate for a patient with suspected acute urinary retention?","Acute urinary retention शंका भएको बिरामीमा कुन कदम उपयुक्त हुन्छ?",["Urgent clinical assessment and bladder management by trained staff","Restrict all assessment","Press forcefully over the bladder","Send home without review"],0,"Acute urinary retention can be painful and needs prompt assessment; catheterization should be performed by trained staff when indicated.","Acute urinary retention दुखाइयुक्त हुन सक्छ र तत्काल जाँच चाहिन्छ; आवश्यक भए प्रशिक्षित स्वास्थ्यकर्मीले catheterization गर्नुपर्छ।","General Surgery"]
 );


 Q.push(
  ["Which part of the brainstem contains vital centres for respiration and heart rate regulation?","श्वासप्रश्वास र मुटुको गति नियमन गर्ने vital centre brainstem को कुन भागमा हुन्छ?",["Medulla oblongata","Cerebellum","Frontal cortex","Corpus callosum"],0,"The medulla oblongata contains important autonomic centres controlling breathing and cardiovascular function.","Medulla oblongata मा श्वासप्रश्वास र cardiovascular कार्य नियन्त्रण गर्ने महत्वपूर्ण autonomic centre हुन्छ।","Anatomy & Physiology"],
  ["Which organ produces insulin and glucagon?","Insulin र glucagon कुन अंगले उत्पादन गर्छ?",["Pancreas","Liver","Spleen","Adrenal gland"],0,"The endocrine islets of the pancreas contain beta cells producing insulin and alpha cells producing glucagon.","Pancreas का endocrine islet मा beta cell ले insulin र alpha cell ले glucagon उत्पादन गर्छ।","Anatomy & Physiology"],
  ["Which membrane surrounds the lungs?","फोक्सोलाई घेर्ने झिल्ली कुन हो?",["Pleura","Pericardium","Peritoneum","Meninges"],0,"The pleura consists of visceral and parietal layers surrounding each lung.","Pleura का visceral र parietal तहले प्रत्येक फोक्सोलाई घेर्छन्।","Anatomy & Physiology"],
  ["Which blood cells are primarily involved in fighting bacterial infection?","Bacterial infection विरुद्ध लड्न मुख्य भूमिका खेल्ने रक्तकोषिका कुन हुन्?",["Neutrophils","Erythrocytes","Platelets","Reticulocytes"],0,"Neutrophils are phagocytic white blood cells important in early defence against bacterial infection.","Neutrophil phagocytic white blood cell हो र bacterial infection विरुद्ध प्रारम्भिक प्रतिरक्षामा महत्वपूर्ण हुन्छ।","Anatomy & Physiology"],
  ["Which organ stores and concentrates bile?","Bile भण्डारण र गाढा बनाउने अंग कुन हो?",["Gallbladder","Liver","Pancreas","Duodenum"],0,"The gallbladder stores and concentrates bile produced by the liver.","Gallbladder ले liver बाट बनेको bile भण्डारण र गाढा बनाउँछ।","Anatomy & Physiology"],
  ["What is the main reason for maintaining accurate birth and death registration?","जन्म र मृत्यु दर्ता सही राख्नुको मुख्य कारण के हो?",["Support vital statistics, planning and legal documentation","Replace all health surveys","Determine medicine doses","Avoid population estimates"],0,"Reliable civil registration supports population statistics, health planning, rights and legal records.","विश्वसनीय नागरिक दर्ताले जनसंख्या तथ्याङ्क, स्वास्थ्य योजना, अधिकार र कानुनी अभिलेखमा सहयोग गर्छ।","Community Health"],
  ["Which group is generally considered at higher risk of severe dehydration from diarrhoea?","पखालाबाट गम्भीर dehydration हुने जोखिम बढी हुने समूह कुन हो?",["Young children and older or frail people","Healthy adults only","People with normal fluid intake only","All groups have identical risk"],0,"Young children and older or medically vulnerable people can deteriorate rapidly and need careful assessment.","साना बालबालिका, वृद्ध तथा अन्य रोग भएका व्यक्तिमा अवस्था छिटो बिग्रन सक्छ; सावधानीपूर्वक जाँच चाहिन्छ।","Community Health"],
  ["What is the purpose of health referral feedback from a higher facility?","माथिल्लो स्वास्थ्य संस्थाबाट referral feedback आउनुको उद्देश्य के हो?",["Ensure continuity of care and inform follow-up at the referring facility","Stop communication between facilities","Replace patient consent","Avoid documenting outcomes"],0,"Feedback closes the referral loop and supports coordinated follow-up and continuity of care.","Feedback ले referral प्रक्रिया पूरा गर्छ र समन्वित follow-up तथा निरन्तर सेवामा सहयोग गर्छ।","Community Health"],
  ["Which indicator is commonly used to assess maternal mortality at population level?","जनसंख्या स्तरमा मातृ मृत्युदर मूल्याङ्कन गर्न कुन सूचक प्रयोग हुन्छ?",["Maternal mortality ratio","Infant weight-for-age","Bed occupancy rate","Crude sex ratio"],0,"Maternal mortality ratio relates maternal deaths to live births, usually expressed per 100,000 live births.","Maternal mortality ratio ले मातृ मृत्यु र जीवित जन्मको सम्बन्ध देखाउँछ, सामान्यतया प्रति १ लाख जीवित जन्ममा।","Community Health"],
  ["Which approach is most appropriate for communicating risk during an outbreak?","प्रकोपको समयमा जोखिमबारे जानकारी दिन कुन तरिका उपयुक्त हुन्छ?",["Provide timely, clear, consistent messages and explain protective actions","Withhold information until the outbreak ends","Use rumours to increase attention","Give conflicting instructions"],0,"Risk communication should be timely, transparent, understandable and actionable, while addressing uncertainty honestly.","Risk communication समयमै, पारदर्शी, बुझिने र व्यवहारमा लागू गर्न मिल्ने हुनुपर्छ; अनिश्चितता इमानदारीपूर्वक बताउनुपर्छ।","Community Health"],
  ["A patient with chronic liver disease develops confusion and flapping tremor. What complication is possible?","दीर्घकालीन कलेजो रोग भएको बिरामी अलमलिन्छ र हात फटफटाउँछ। कुन जटिलता हुन सक्छ?",["Hepatic encephalopathy","Acute otitis media","Simple myopia","Osteoarthritis"],0,"Hepatic encephalopathy can cause altered mental status and asterixis in advanced liver disease.","गम्भीर कलेजो रोगमा hepatic encephalopathy भएर मानसिक अवस्था परिवर्तन र asterixis देखिन सक्छ।","General Medicine"],
  ["Which symptom is characteristic of an acute asthma attack?","Acute asthma attack को विशेषता कुन हो?",["Wheezing with breathlessness and chest tightness","Painless jaundice","Bloody urine only","Unilateral hearing loss"],0,"Acute asthma commonly causes wheeze, breathlessness, cough and chest tightness.","Acute asthma मा सास फेर्न गाह्रो, wheeze, खोकी र छाती कसिएको महसुस हुन सक्छ।","General Medicine"],
  ["Which condition is suggested by polyuria, polydipsia and unexplained weight loss?","धेरै पिसाब लाग्ने, धेरै तिर्खा लाग्ने र कारण नखुलेको तौल घट्ने लक्षणले कुन रोग संकेत गर्छ?",["Diabetes mellitus","Osteoarthritis","Otitis externa","Glaucoma"],0,"Polyuria, polydipsia and weight loss are classic symptoms of hyperglycaemia and diabetes.","Polyuria, polydipsia र तौल घट्नु hyperglycaemia तथा diabetes का सामान्य लक्षण हुन्।","General Medicine"],
  ["Which clinical feature may suggest appendicitis?","Appendicitis को सम्भावना देखाउने clinical feature कुन हो?",["Pain migrating from around the umbilicus to the right lower abdomen","Pain only in both ears","Chronic painless rash","Sudden loss of smell"],0,"Appendicitis often begins with vague periumbilical pain that migrates to the right lower quadrant.","Appendicitis मा सुरुमा नाभी वरिपरि दुखेर पछि दायाँ तल्लो पेटतिर सर्न सक्छ।","General Medicine"],
  ["Which finding is commonly associated with acute pancreatitis?","Acute pancreatitis सँग सामान्यतया कुन निष्कर्ष सम्बन्धित हुन्छ?",["Severe epigastric pain radiating to the back","Painless ankle swelling only","Itchy scalp","Sudden visual field loss"],0,"Acute pancreatitis often causes severe upper abdominal pain radiating to the back with nausea and vomiting.","Acute pancreatitis मा माथिल्लो पेटबाट ढाडतिर सर्ने कडा दुखाइ, वाकवाकी र बान्ता हुन सक्छ।","General Medicine"],
  ["Which medicine is a common first-line oral treatment for type 2 diabetes when appropriate?","उपयुक्त अवस्थामा type 2 diabetes को सामान्य पहिलो oral औषधि कुन हो?",["Metformin","Adrenaline","Warfarin","Salbutamol"],0,"Metformin is commonly used as initial pharmacological therapy when not contraindicated, alongside lifestyle measures.","Contraindication नभए lifestyle उपायसँगै metformin सामान्यतया प्रारम्भिक औषधिका रूपमा प्रयोग हुन्छ।","Pharmacology & Pharmacy"],
  ["Which route is appropriate for a topical skin cream?","छालामा लगाइने cream को route कुन हो?",["Topical","Intrathecal","Intravenous","Intra-articular"],0,"Topical medicines are applied directly to the skin or a localized surface.","Topical औषधि छाला वा निश्चित बाहिरी सतहमा सिधै लगाइन्छ।","Pharmacology & Pharmacy"],
  ["Why should a medicine requiring refrigeration be stored in a monitored refrigerator?","Refrigeration चाहिने औषधि अनुगमन गरिएको refrigerator मा किन राख्नुपर्छ?",["To maintain stability and potency within the required temperature range","To freeze every medicine","To increase the expiry date automatically","To avoid stock records"],0,"Temperature excursions can reduce medicine quality; monitor and document storage conditions according to the product label.","तापक्रम सीमा नाघ्दा औषधिको गुणस्तर घट्न सक्छ; label अनुसार तापक्रम अनुगमन र अभिलेख राख्नुपर्छ।","Pharmacology & Pharmacy"],
  ["A patient has a suspected fracture with an open wound. What should be avoided?","खुला घाउसहित fracture शंका भएको बिरामीमा के गर्नु हुँदैन?",["Pushing exposed bone back into the wound","Covering with sterile dressing","Immobilizing the limb","Checking distal circulation"],0,"Do not push exposed bone back; cover, immobilize, assess circulation and refer urgently.","बाहिर देखिएको हड्डी घाउभित्र नधकेल्नुहोस्; छोप्नुहोस्, immobilize गर्नुहोस्, रक्तसञ्चार जाँचेर referral गर्नुहोस्।","General Surgery"],
  ["Which sign after a burn suggests possible inhalation injury?","जलेको बिरामीमा कुन संकेतले श्वासमार्गमा धुवाँ/तातो हावा गएको शंका गराउँछ?",["Hoarseness, soot around mouth or breathing difficulty","Small superficial blister on a finger only","Normal voice and breathing","Isolated ankle pain"],0,"Hoarseness, facial burns, soot or respiratory distress may indicate inhalation injury and threatened airway.","आवाज बस्नु, अनुहार जलेको, कालो धुवाँको दाग वा सास गाह्रो हुनु inhalation injury र airway जोखिमको संकेत हुन सक्छ।","General Surgery"],
  ["Which action is important when transporting a patient with a suspected pelvic fracture?","Pelvic fracture शंका भएको बिरामीलाई लैजाँदा कुन कदम महत्वपूर्ण हुन्छ?",["Minimize movement and use appropriate pelvic stabilization by trained responders","Ask the patient to stand","Repeatedly rock the pelvis to test stability","Massage the abdomen"],0,"Pelvic fractures can cause major internal bleeding; minimize movement and follow trauma protocols for stabilization and transfer.","Pelvic fracture मा भित्री रक्तस्राव धेरै हुन सक्छ; movement कम गरी trauma protocol अनुसार stabilization र transfer गर्नुपर्छ।","General Surgery"],
  ["Which postoperative symptom may suggest a wound infection requiring review?","शल्यक्रियापछि कुन लक्षणले घाउ संक्रमणको शंका गराउँछ र जाँच चाहिन्छ?",["Increasing pain, redness, swelling or discharge","Improving pain and a dry wound","Normal appetite only","A stable healed scar"],0,"Worsening local inflammation or discharge can indicate infection and should be clinically assessed.","दुखाइ, रातोपन, सुन्निनु वा discharge बढ्नु संक्रमणको संकेत हुन सक्छ; clinical जाँच चाहिन्छ।","General Surgery"]
 );


 Q.push(
  ["Which cranial nerve controls most muscles of facial expression?","अनुहारका अधिकांश मांसपेशी नियन्त्रण गर्ने cranial nerve कुन हो?",["Facial nerve (VII)","Optic nerve (II)","Olfactory nerve (I)","Accessory nerve (XI)"],0,"The facial nerve supplies the muscles of facial expression and carries taste from the anterior two-thirds of the tongue.","Facial nerve ले अनुहारका मांसपेशीलाई supply गर्छ र जिब्रोको अगाडिको दुई-तिहाइ भागको taste बोक्छ।","Anatomy & Physiology"],
  ["Which organ is primarily responsible for detoxification and metabolism of many drugs?","धेरै औषधिको metabolism र detoxification मुख्य रूपमा कुन अंगले गर्छ?",["Liver","Spleen","Urinary bladder","Thymus"],0,"The liver contains enzyme systems that metabolize many medicines and toxins.","Liver मा धेरै औषधि र विषाक्त पदार्थ metabolize गर्ने enzyme system हुन्छ।","Anatomy & Physiology"],
  ["Which hormone increases water reabsorption in the kidney collecting ducts?","मिर्गौलाको collecting duct मा पानी पुनःअवशोषण बढाउने hormone कुन हो?",["Antidiuretic hormone","Insulin","Glucagon","Calcitonin"],0,"Antidiuretic hormone increases water permeability in collecting ducts and reduces urine volume.","Antidiuretic hormone ले collecting duct मा पानीको permeability बढाएर पिसाबको मात्रा घटाउँछ।","Anatomy & Physiology"],
  ["Which part of the ear is responsible for hearing transduction?","श्रवण संवेदना उत्पन्न गर्ने कानको भाग कुन हो?",["Organ of Corti in the cochlea","Semicircular canals","Pinna","Eustachian tube"],0,"Hair cells in the organ of Corti convert sound-related vibrations into nerve signals.","Cochlea को Organ of Corti का hair cell ले ध्वनि कम्पनलाई nerve signal मा बदल्छन्।","Anatomy & Physiology"],
  ["Which blood vessel carries deoxygenated blood from the heart to the lungs?","मुटुबाट फोक्सोतर्फ oxygen कम भएको रगत कुन रक्तनलीले लैजान्छ?",["Pulmonary artery","Pulmonary vein","Aorta","Coronary vein"],0,"The pulmonary artery carries deoxygenated blood from the right ventricle to the lungs.","Pulmonary artery ले right ventricle बाट oxygen कम भएको रगत फोक्सोमा लैजान्छ।","Anatomy & Physiology"],
  ["Which activity is an example of secondary prevention?","Secondary prevention को उदाहरण कुन हो?",["Screening to detect disease early","Immunization before exposure","Rehabilitation after disability","Palliative care"],0,"Secondary prevention aims at early detection and prompt treatment, such as screening.","Secondary prevention ले screening जस्ता उपायबाट रोग चाँडै पत्ता लगाई उपचार गर्न खोज्छ।","Community Health"],
  ["Which factor is an important social determinant of health?","स्वास्थ्यको महत्वपूर्ण सामाजिक निर्धारक कुन हो?",["Education and income","Blood group only","Eye colour","Hand dominance"],0,"Education and income influence living conditions, health literacy, access to services and health outcomes.","शिक्षा र आम्दानीले जीवन अवस्था, स्वास्थ्य साक्षरता, सेवा पहुँच र स्वास्थ्य नतिजामा प्रभाव पार्छ।","Community Health"],
  ["What is the purpose of a household health survey?","घरपरिवार स्वास्थ्य सर्वेक्षणको उद्देश्य के हो?",["Collect standardized information on health status and risk factors","Provide surgery to every household","Replace all routine health services","Count only clinic visitors"],0,"A household survey gathers structured data on health, service use, environment and risk factors for planning.","घरपरिवार सर्वेक्षणले स्वास्थ्य, सेवा उपयोग, वातावरण र जोखिमबारे व्यवस्थित तथ्याङ्क संकलन गर्छ।","Community Health"],
  ["Which action helps prevent iodine deficiency disorders?","Iodine deficiency disorder रोक्न कुन उपाय सहयोगी हुन्छ?",["Use adequately iodized salt","Avoid all salt regardless of context","Use only non-iodized rock salt","Take antibiotics regularly"],0,"Adequately iodized salt is a population strategy to prevent iodine deficiency when used within recommended salt limits.","पर्याप्त iodized salt ले सिफारिस गरिएको नुनको सीमाभित्र iodine कमी रोक्न सहयोग गर्छ।","Community Health"],
  ["Which measure is most appropriate for evaluating a health programme's effectiveness?","स्वास्थ्य कार्यक्रमको प्रभावकारिता मूल्याङ्कन गर्न कुन उपाय उपयुक्त हुन्छ?",["Compare predefined indicators before and after implementation","Count only the number of posters","Ask only programme staff whether it worked","Ignore baseline data"],0,"Evaluation compares defined objectives and indicators with baseline and follow-up data, considering context and limitations.","Evaluation ले पूर्वनिर्धारित उद्देश्य र सूचकलाई baseline तथा follow-up तथ्याङ्कसँग तुलना गर्छ।","Community Health"],
  ["A patient with fever and a new heart murmur has a history of valve disease. What should be suspected?","ज्वरो र नयाँ heart murmur भएको, valve disease को इतिहास भएको बिरामीमा के शंका गर्नुपर्छ?",["Infective endocarditis","Simple tension headache","Acute conjunctivitis","Uncomplicated scabies"],0,"Fever with a new murmur in a patient with valve disease raises concern for infective endocarditis and needs urgent assessment.","Valve disease भएको बिरामीमा ज्वरो र नयाँ murmur हुँदा infective endocarditis शंका गरी तत्काल जाँच गर्नुपर्छ।","General Medicine"],
  ["Which finding is a common feature of chronic obstructive pulmonary disease?","Chronic obstructive pulmonary disease को सामान्य विशेषता कुन हो?",["Persistent airflow limitation with chronic cough or breathlessness","Sudden isolated rash","Painful urination only","Acute unilateral vision loss"],0,"COPD is characterized by persistent respiratory symptoms and airflow limitation, often associated with tobacco or biomass exposure.","COPD मा लगातार श्वासप्रश्वास लक्षण र airflow limitation हुन्छ; सुर्ती वा biomass धुवाँसँग सम्बन्ध हुन सक्छ।","General Medicine"],
  ["Which symptom may indicate upper gastrointestinal bleeding?","Upper gastrointestinal bleeding को संकेत कुन हुन सक्छ?",["Vomiting blood or coffee-ground material","Clear urine","Dry skin only","Painless ankle swelling"],0,"Haematemesis or coffee-ground vomitus suggests upper GI bleeding and requires urgent assessment.","रगत वा coffee-ground जस्तो बान्ता upper GI bleeding को संकेत हो; तत्काल जाँच चाहिन्छ।","General Medicine"],
  ["A patient has painful urination, frequency and fever with flank pain. What should be considered?","पिसाब गर्दा दुख्ने, बारम्बार पिसाब लाग्ने, ज्वरो र ढाडको छेउ दुख्ने बिरामीमा के विचार गर्नुपर्छ?",["Upper urinary tract infection or pyelonephritis","Simple allergic rhinitis","Migraine","Osteoarthritis"],0,"Fever and flank pain with urinary symptoms may indicate pyelonephritis and require prompt assessment.","पिसाबका लक्षणसँग ज्वरो र flank pain हुनु pyelonephritis को संकेत हुन सक्छ; छिटो जाँच चाहिन्छ।","General Medicine"],
  ["Which medicine is a commonly used oral iron supplement?","सामान्यतया प्रयोग हुने oral iron supplement कुन हो?",["Ferrous sulfate","Amlodipine","Cetirizine","Salbutamol"],0,"Ferrous sulfate provides elemental iron for treatment or prevention of iron deficiency when indicated.","Ferrous sulfate ले आवश्यक अवस्थामा iron deficiency उपचार वा रोकथामका लागि elemental iron दिन्छ।","Pharmacology & Pharmacy"],
  ["Which medication safety check confirms that the medicine is given to the intended person?","औषधि सही व्यक्तिलाई दिइएको पुष्टि गर्ने medication safety check कुन हो?",["Right patient using approved identifiers","Right room colour","Right staff uniform","Right bed position only"],0,"Confirm patient identity with approved identifiers before medication administration.","औषधि दिनुअघि स्वीकृत identifier प्रयोग गरी बिरामीको पहिचान पुष्टि गर्नुपर्छ।","Pharmacology & Pharmacy"],
  ["Which adverse effect is associated with opioid medicines?","Opioid औषधिसँग सम्बन्धित adverse effect कुन हो?",["Respiratory depression and constipation","Increased bone density","Improved hearing","Reduced infection risk"],0,"Opioids can cause sedation, respiratory depression, constipation and dependence; monitor carefully.","Opioid ले निद्रा, श्वासप्रश्वास दबिने, कब्जियत र निर्भरता गराउन सक्छ; सावधानीपूर्वक निगरानी चाहिन्छ।","Pharmacology & Pharmacy"],
  ["A patient has a suspected fracture with severe pain. What should be done before transfer?","धेरै दुखाइ भएको fracture शंका भएको बिरामीलाई transfer अघि के गर्नुपर्छ?",["Immobilize the injured part in the position found","Repeatedly move the limb","Attempt forceful realignment","Ask the patient to bear weight"],0,"Immobilization reduces pain and further tissue injury; check distal circulation and sensation before and after.","Immobilization ले दुखाइ र थप चोट घटाउँछ; अघि र पछि distal circulation तथा sensation जाँच्नुपर्छ।","General Surgery"],
  ["Which sign after abdominal trauma suggests peritonitis?","पेटमा चोटपछि peritonitis को संकेत कुन हो?",["Involuntary guarding and rebound tenderness","Soft painless abdomen","Normal appetite","Isolated itchy skin"],0,"Involuntary guarding and rebound tenderness can indicate peritoneal irritation and need urgent surgical assessment.","आफैँ पेट कडा हुनु र rebound tenderness peritoneal irritation का संकेत हुन्; तत्काल surgical जाँच चाहिन्छ।","General Surgery"],
  ["What is the appropriate first aid for a suspected ankle sprain without deformity?","विकृति नभएको ankle sprain शंका हुँदा पहिलो सहायता के हो?",["Protect, rest, apply wrapped cold pack and elevate as appropriate","Apply direct heat immediately","Forcefully stretch the joint","Continue running"],0,"Protection, relative rest, wrapped cold application and elevation may help; assess for fracture or neurovascular compromise when indicated.","Protection, आराम, कपडाले बेरेको चिसो सेक र उचालेर राख्दा सहयोग हुन्छ; आवश्यक परे fracture र रक्तसञ्चार जाँच्नुपर्छ।","General Surgery"]
 );


 Q.push(
  ["Which hormone is released by the adrenal medulla during the fight-or-flight response?","Fight-or-flight response मा adrenal medulla बाट कुन hormone निस्कन्छ?",["Adrenaline","Insulin","Thyroxine","Oestrogen"],0,"The adrenal medulla releases adrenaline and noradrenaline during sympathetic activation.","Sympathetic activation हुँदा adrenal medulla ले adrenaline र noradrenaline निकाल्छ।","Anatomy & Physiology"],
  ["Which structure connects the pharynx to the stomach?","Pharynx लाई stomach सँग जोड्ने संरचना कुन हो?",["Oesophagus","Trachea","Ureter","Bronchus"],0,"The oesophagus transports swallowed food and liquids from the pharynx to the stomach.","Oesophagus ले निलेको खाना र तरल pharynx बाट stomach सम्म पुर्‍याउँछ।","Anatomy & Physiology"],
  ["Which part of the kidney contains most glomeruli?","मिर्गौलाको कुन भागमा अधिकांश glomeruli हुन्छन्?",["Renal cortex","Renal medulla","Renal pelvis","Ureter"],0,"Most renal corpuscles, including glomeruli, are located in the renal cortex.","अधिकांश renal corpuscle र glomeruli renal cortex मा हुन्छन्।","Anatomy & Physiology"],
  ["Which type of muscle is found in the wall of the intestine?","आन्द्राको भित्तामा कुन प्रकारको muscle हुन्छ?",["Smooth muscle","Skeletal muscle","Cardiac muscle","Voluntary striated muscle only"],0,"The intestinal wall contains smooth muscle that produces involuntary peristaltic movements.","आन्द्राको भित्तामा smooth muscle हुन्छ, जसले अनैच्छिक peristalsis गराउँछ।","Anatomy & Physiology"],
  ["Which part of the blood is the liquid medium carrying cells and dissolved substances?","रक्तकोषिका र घुलनशील पदार्थ बोक्ने तरल भाग कुन हो?",["Plasma","Platelet","Haemoglobin","Neutrophil"],0,"Plasma is the liquid component of blood containing water, proteins, electrolytes and dissolved substances.","Plasma रगतको तरल भाग हो, जसमा पानी, protein, electrolyte र घुलनशील पदार्थ हुन्छन्।","Anatomy & Physiology"],
  ["What is the main purpose of a baseline survey before implementing a health intervention?","स्वास्थ्य कार्यक्रम सुरु गर्नुअघि baseline survey गर्नुको मुख्य उद्देश्य के हो?",["Establish starting values for later comparison","Replace programme monitoring","Measure only staff satisfaction","Guarantee the programme succeeds"],0,"Baseline data provide a reference point for assessing change after an intervention.","Baseline तथ्याङ्कले कार्यक्रमपछि आएको परिवर्तन तुलना गर्ने आधार दिन्छ।","Community Health"],
  ["Which practice supports respectful maternity care?","सम्मानजनक मातृत्व सेवामा कुन अभ्यास पर्छ?",["Maintain privacy, dignity and informed choice","Perform procedures without explanation","Ignore the woman's preferences","Disclose personal information publicly"],0,"Respectful maternity care protects dignity, privacy, confidentiality, informed choice and freedom from abuse.","सम्मानजनक मातृत्व सेवाले गरिमा, गोपनीयता, informed choice र दुर्व्यवहारबाट सुरक्षा सुनिश्चित गर्छ।","Community Health"],
  ["Which group is the main target for routine growth monitoring in child health programmes?","बाल स्वास्थ्य कार्यक्रममा नियमित वृद्धि अनुगमनको मुख्य लक्षित समूह कुन हो?",["Children under five years","Only adults over 60","Only pregnant men","All hospital employees"],0,"Growth monitoring is particularly important in under-five children to detect growth faltering early.","वृद्धि कमजोर भएको चाँडै पत्ता लगाउन पाँच वर्षमुनिका बालबालिकाको वृद्धि अनुगमन महत्वपूर्ण हुन्छ।","Community Health"],
  ["Which practice reduces the risk of heat-related illness during very hot weather?","अत्यधिक गर्मीमा heat-related illness को जोखिम घटाउने उपाय कुन हो?",["Drink adequate safe fluids, stay cool and limit strenuous activity in peak heat","Wear heavy clothing outdoors at midday","Avoid drinking water","Exercise intensely in direct sun"],0,"Hydration, shade, cooling and reducing strenuous activity during peak heat help prevent heat illness.","पर्याप्त सुरक्षित तरल, छायाँ, चिसो वातावरण र अत्यधिक गर्मीमा कडा काम घटाउँदा heat illness रोक्न सहयोग हुन्छ।","Community Health"],
  ["What should a health worker do when a communicable disease case is legally notifiable?","कानुनी रूपमा notification गर्नुपर्ने संक्रामक रोग भेटिए स्वास्थ्यकर्मीले के गर्नुपर्छ?",["Report promptly through the required public-health channel","Wait until the patient requests reporting","Post the patient's identity on social media","Ignore the requirement"],0,"Timely notification follows public-health law and enables surveillance and control action while protecting confidentiality.","समयमै notification गर्दा निगरानी र नियन्त्रणमा सहयोग हुन्छ; बिरामीको गोपनीयता भने सुरक्षित राख्नुपर्छ।","Community Health"],
  ["A patient with chronic diarrhoea has weight loss and greasy, floating stools. What should be considered?","लामो पखाला, तौल घट्ने र चिल्लो तैरिने दिसा भएको बिरामीमा के विचार गर्नुपर्छ?",["Malabsorption","Acute otitis media","Glaucoma","Uncomplicated sprain"],0,"Steatorrhoea and weight loss suggest fat malabsorption and need investigation for gastrointestinal or pancreatic causes.","चिल्लो तैरिने दिसा र तौल घट्नु fat malabsorption को संकेत हुन सक्छ; आन्द्रा वा pancreas सम्बन्धी कारण जाँच्नुपर्छ।","General Medicine"],
  ["Which symptom is a common manifestation of anaemia?","Anaemia को सामान्य लक्षण कुन हो?",["Fatigue and exertional breathlessness","Sudden painless rash","Excessive hearing acuity","Improved exercise tolerance"],0,"Reduced oxygen-carrying capacity can cause fatigue, pallor, palpitations and breathlessness on exertion.","Oxygen बोक्ने क्षमता घट्दा थकान, फिक्कापन, धड्कन बढ्नु र काम गर्दा सास गाह्रो हुन सक्छ।","General Medicine"],
  ["A patient has a seizure lasting more than five minutes. What is the priority?","बिरामीको दौरा पाँच मिनेटभन्दा बढी चलिरहेको छ। प्राथमिकता के हो?",["Treat as status epilepticus and activate emergency protocol","Put an object in the mouth","Restrain all limbs forcefully","Give oral fluids during the seizure"],0,"A seizure lasting five minutes or recurrent seizures without recovery is a medical emergency requiring airway support and protocol-based treatment.","पाँच मिनेटभन्दा बढी दौरा वा बीचमा चेतना नफर्की दोहोरिने दौरा आकस्मिक अवस्था हो; airway र protocol अनुसार उपचार चाहिन्छ।","General Medicine"],
  ["Which finding is characteristic of hyperthyroidism?","Hyperthyroidism को विशेषता कुन हो?",["Heat intolerance, tremor and weight loss","Cold intolerance and weight gain","Slow pulse with marked lethargy in all cases","Reduced sweating only"],0,"Excess thyroid hormone can cause heat intolerance, tremor, palpitations and weight loss.","Thyroid hormone बढी हुँदा गर्मी सहन नसक्नु, कम्पन, धड्कन र तौल घट्नु हुन सक्छ।","General Medicine"],
  ["Which medicine is commonly used to treat bacterial infections when indicated?","आवश्यक परेको अवस्थामा bacterial infection उपचार गर्न कुन औषधि समूह प्रयोग हुन्छ?",["Antibiotics","Antihistamines","Antacids","Anthelmintics"],0,"Antibiotics act against susceptible bacteria and should be selected according to diagnosis, guidelines and resistance patterns.","Antibiotic ले संवेदनशील bacteria विरुद्ध काम गर्छ; निदान, guideline र resistance अनुसार छनोट गर्नुपर्छ।","Pharmacology & Pharmacy"],
  ["What is the purpose of a loading dose for some medicines?","केही औषधिमा loading dose दिनुको उद्देश्य के हो?",["Reach the target therapeutic concentration more rapidly","Prevent all adverse effects","Replace every maintenance dose","Reduce absorption to zero"],0,"A loading dose may rapidly achieve a target concentration when appropriate, based on drug distribution and patient factors.","उपयुक्त अवस्थामा औषधिको distribution र बिरामीको अवस्थाअनुसार loading dose ले target concentration छिटो पुर्‍याउँछ।","Pharmacology & Pharmacy"],
  ["Which medicine class is used to reduce fever and relieve mild pain?","ज्वरो घटाउन र हल्का दुखाइ कम गर्न कुन औषधि वर्ग प्रयोग हुन्छ?",["Analgesic-antipyretics such as paracetamol","Anticoagulants","Anthelmintics","Antipsychotics"],0,"Paracetamol is an analgesic and antipyretic; dose limits and liver risk must be considered.","Paracetamol दुखाइ कम गर्ने र ज्वरो घटाउने औषधि हो; dose सीमा र कलेजोको जोखिम विचार गर्नुपर्छ।","Pharmacology & Pharmacy"],
  ["A patient has an open fracture. Which additional assessment is important?","Open fracture भएको बिरामीमा थप कुन मूल्याङ्कन महत्वपूर्ण हुन्छ?",["Distal pulses, sensation and movement","Hair length","Dental occlusion","Visual acuity only"],0,"Neurovascular assessment distal to the injury helps detect vascular or nerve compromise and should be repeated after immobilization.","चोटभन्दा तलको नाडी, संवेदना र movement जाँच्दा रक्तनली वा nerve समस्या पत्ता लाग्छ; immobilization पछि पनि दोहोर्‍याउनुपर्छ।","General Surgery"],
  ["Which position may help a conscious patient with breathing difficulty while awaiting assessment, if no contraindication exists?","सास फेर्न गाह्रो भएको तर चेतनामा रहेको बिरामीलाई contraindication नभए जाँच पर्खँदा कुन position ले सहयोग गर्न सक्छ?",["Upright or semi-sitting position","Flat prone position","Head-down position","Forced standing"],0,"An upright position may ease breathing in many conscious patients; continuously assess and follow emergency protocols.","धेरै सचेत बिरामीमा सिधा वा अर्ध-बसेको position ले सास फेर्न सजिलो बनाउन सक्छ; निरन्तर मूल्याङ्कन र emergency protocol पालना गर्नुहोस्।","General Surgery"],
  ["Which finding after an injury suggests possible nerve damage?","चोटपछि कुन निष्कर्षले nerve damage को सम्भावना देखाउँछ?",["New numbness, weakness or loss of sensation distal to injury","Normal movement and sensation","Mild bruising only","Improving pain"],0,"New sensory loss or weakness distal to an injury may indicate nerve damage and needs assessment.","चोटभन्दा तल नयाँ लाटोपन, कमजोरी वा संवेदना हराउनु nerve damage को संकेत हुन सक्छ; जाँच आवश्यक हुन्छ।","General Surgery"]
 );


 Q.push(
  ["Which measure is used to estimate the proportion of births attended by skilled health personnel?","दक्ष स्वास्थ्यकर्मीको उपस्थितिमा भएका जन्मको अनुपात अनुमान गर्न कुन सूचक प्रयोग हुन्छ?",["Proportion of births attended by skilled health personnel","Crude death rate","Bed occupancy rate","Case fatality rate"],0,"This indicator measures access to skilled care during childbirth and is important for maternal-newborn health monitoring.","यस सूचकले प्रसवका बेला दक्ष सेवा पहुँच मापन गर्छ र मातृ-नवजात स्वास्थ्य अनुगमनमा महत्वपूर्ण हुन्छ।","Community Health"],
  ["Which approach best supports inclusion of people with disabilities in community health activities?","समुदाय स्वास्थ्य गतिविधिमा अपाङ्गता भएका व्यक्तिको समावेशिता बढाउन कुन उपाय राम्रो हुन्छ?",["Ensure accessible venues, communication and participation","Exclude them from planning","Provide information only in small print","Assume one approach fits everyone"],0,"Accessible environments and communication enable meaningful participation and equitable access to services.","पहुँचयोग्य स्थान र सञ्चारले अर्थपूर्ण सहभागिता तथा समान सेवा पहुँच सुनिश्चित गर्छ।","Community Health"],
  ["Which action is important when conducting a confidential household health interview?","गोपनीय घरपरिवार स्वास्थ्य अन्तर्वार्ता गर्दा कुन कुरा महत्वपूर्ण हुन्छ?",["Explain purpose, obtain consent and interview privately","Discuss answers with neighbours","Record names publicly","Interview without permission"],0,"Privacy, consent and clear explanation promote trust and protect personal information.","गोपनीयता, सहमति र स्पष्ट जानकारीले विश्वास बढाउँछ र व्यक्तिगत सूचना सुरक्षित गर्छ।","Community Health"],
  ["Which indicator is commonly used to assess the nutritional status of a child over time?","बालबालिकाको पोषण अवस्था समयसँगै मूल्याङ्कन गर्न कुन सूचक प्रयोग हुन्छ?",["Growth pattern on serial weight measurements","Hair length alone","Number of siblings","Eye colour"],0,"Repeated accurate weight and growth plotting helps detect faltering and guide nutrition assessment.","बारम्बार सही तौल लिएर वृद्धि चार्टमा राख्दा वृद्धि कमजोर भएको पत्ता लाग्छ र पोषण मूल्याङ्कनमा मद्दत गर्छ।","Community Health"],
  ["What is the main purpose of a school health programme?","विद्यालय स्वास्थ्य कार्यक्रमको मुख्य उद्देश्य के हो?",["Promote health, prevent illness and support a safe learning environment","Provide hospital surgery at school","Replace family health services","Assess only examination scores"],0,"School health programmes combine health education, prevention, early identification and referral to support learning and wellbeing.","विद्यालय स्वास्थ्य कार्यक्रमले स्वास्थ्य शिक्षा, रोकथाम, प्रारम्भिक पहिचान र referral मार्फत सिकाइ तथा कल्याणमा सहयोग गर्छ।","Community Health"],
  ["Which practice reduces the risk of zoonotic disease transmission?","जनावरबाट मानिसमा सर्ने रोगको जोखिम घटाउने अभ्यास कुन हो?",["Safe animal handling, hand hygiene and appropriate vaccination/control","Handle sick animals without protection","Consume uninspected animal products","Ignore animal bites"],0,"Safe handling, hygiene, animal vaccination and prompt bite management reduce zoonotic risks.","सुरक्षित व्यवहार, सरसफाइ, जनावरको खोप र टोकेको अवस्थामा छिटो उपचारले zoonotic जोखिम घटाउँछ।","Community Health"],
  ["Which activity is an example of tertiary prevention?","Tertiary prevention को उदाहरण कुन हो?",["Rehabilitation to reduce disability after stroke","Immunization before infection","Screening for early disease","Health education before risk exposure"],0,"Tertiary prevention aims to limit complications and disability and improve function after disease or injury.","Tertiary prevention ले रोग वा चोटपछि जटिलता र अपाङ्गता घटाई कार्यक्षमता सुधार गर्छ।","Community Health"],
  ["A patient with diabetes has fever, vomiting and deep rapid breathing. What should be suspected?","मधुमेह भएको बिरामीलाई ज्वरो, बान्ता र गहिरो छिटो श्वास छ। के शंका गर्नुपर्छ?",["Diabetic ketoacidosis or another acute metabolic emergency","Simple seasonal allergy","Uncomplicated dermatitis","Chronic myopia"],0,"Deep rapid breathing with vomiting in diabetes can indicate ketoacidosis or severe illness and needs emergency assessment.","मधुमेहमा बान्तासँग गहिरो छिटो श्वास ketoacidosis वा गम्भीर रोगको संकेत हुन सक्छ; आकस्मिक जाँच चाहिन्छ।","General Medicine"],
  ["Which symptom is typical of a urinary tract infection in an adult?","वयस्कमा urinary tract infection को सामान्य लक्षण कुन हो?",["Dysuria and urinary frequency","Sudden loss of hearing","Painless skin blister","Chronic shoulder stiffness"],0,"Dysuria, frequency and urgency are common lower urinary tract symptoms; fever or flank pain suggests upper tract involvement.","पिसाब पोल्नु, बारम्बार र तुरुन्त पिसाब लाग्नु lower UTI का सामान्य लक्षण हुन्; ज्वरो वा flank pain ले upper UTI देखाउन सक्छ।","General Medicine"],
  ["Which clinical sign may indicate dehydration in an adult?","वयस्कमा dehydration को संकेत कुन हुन सक्छ?",["Dry mucous membranes and postural dizziness","Excessive salivation","New hair growth","Improved skin turgor"],0,"Dry mucosa, thirst, reduced urine and postural dizziness can suggest dehydration; assess severity and cause.","मुख सुक्नु, तिर्खा, पिसाब कम हुनु र उभिँदा चक्कर dehydration का संकेत हुन सक्छन्; गम्भीरता जाँच्नुपर्छ।","General Medicine"],
  ["A patient presents with unilateral facial weakness and inability to close one eye. Which condition may be considered after excluding stroke?","एकातिर अनुहार कमजोर छ र एउटा आँखा बन्द गर्न सक्दैन। Stroke हटाएपछि कुन अवस्था विचार गर्न सकिन्छ?",["Bell palsy","Acute appendicitis","Glaucoma","Otitis externa"],0,"Bell palsy causes acute peripheral facial nerve weakness; stroke must be considered and excluded when appropriate.","Bell palsy मा facial nerve को peripheral कमजोरी अचानक हुन्छ; आवश्यक अवस्थामा stroke पहिला विचार गरी छुट्याउनुपर्छ।","General Medicine"],
  ["Which finding is common in rheumatoid arthritis?","Rheumatoid arthritis मा सामान्यतया कुन लक्षण देखिन्छ?",["Symmetrical inflammatory joint pain and morning stiffness","Only one brief muscle cramp","Painless hearing loss","Acute watery diarrhoea"],0,"Rheumatoid arthritis commonly causes symmetrical inflammatory polyarthritis and prolonged morning stiffness.","Rheumatoid arthritis मा सममित जोर्नी दुखाइ/सुन्निनु र लामो morning stiffness हुन सक्छ।","General Medicine"],
  ["Which condition can cause a productive cough with foul-smelling sputum?","दुर्गन्धयुक्त खकारसहित खोकी कुन अवस्थामा हुन सक्छ?",["Lung abscess or bronchiectasis","Simple refractive error","Uncomplicated migraine","Acute glaucoma"],0,"Foul sputum can occur with lung abscess or bronchiectasis and requires clinical assessment and appropriate investigations.","दुर्गन्धयुक्त खकार lung abscess वा bronchiectasis मा हुन सक्छ; clinical जाँच र आवश्यक investigation चाहिन्छ।","General Medicine"],
  ["Which drug is used as an anticoagulant in selected patients to prevent or treat thrombosis?","केही बिरामीमा thrombosis रोक्न वा उपचार गर्न कुन औषधि anticoagulant का रूपमा प्रयोग हुन्छ?",["Warfarin","Paracetamol","Cetirizine","Omeprazole"],0,"Warfarin reduces vitamin K-dependent clotting factor activity and requires INR monitoring.","Warfarin ले vitamin K-निर्भर clotting factor को कार्य घटाउँछ र INR निगरानी चाहिन्छ।","Pharmacology & Pharmacy"],
  ["Which medicine is a common oral antihistamine for allergic rhinitis?","Allergic rhinitis मा प्रयोग हुने सामान्य oral antihistamine कुन हो?",["Loratadine","Metformin","Insulin","Furosemide"],0,"Loratadine is a second-generation H1 antihistamine used for allergic symptoms.","Loratadine second-generation H1 antihistamine हो र एलर्जीका लक्षणमा प्रयोग हुन्छ।","Pharmacology & Pharmacy"],
  ["Which action is most appropriate if a patient develops a severe allergic reaction after a medicine?","औषधि खाएपछि बिरामीलाई गम्भीर एलर्जी प्रतिक्रिया भए कुन कदम उपयुक्त हुन्छ?",["Stop the suspected medicine, assess ABC and provide emergency treatment","Give another dose to confirm","Ask the patient to drive home","Wait without monitoring"],0,"A severe reaction may be anaphylaxis; stop exposure, assess airway/breathing/circulation and follow emergency protocol including adrenaline when indicated.","गम्भीर प्रतिक्रिया anaphylaxis हुन सक्छ; औषधि रोक्नुहोस्, ABC जाँच्नुहोस् र आवश्यक भए adrenaline सहित emergency protocol पालना गर्नुहोस्।","Pharmacology & Pharmacy"],
  ["A patient has a suspected abdominal aortic aneurysm with sudden back pain and collapse. What is the priority?","अचानक ढाड दुखाइ र collapse भएको बिरामीमा abdominal aortic aneurysm शंका छ। प्राथमिकता के हो?",["Activate emergency transfer and avoid delay","Give oral food","Encourage walking","Apply abdominal massage"],0,"Ruptured aneurysm can cause catastrophic internal bleeding and requires immediate emergency care.","Aneurysm फुट्दा घातक आन्तरिक रक्तस्राव हुन सक्छ; तत्काल आकस्मिक उपचार आवश्यक हुन्छ।","General Surgery"],
  ["Which action is appropriate for a patient with a suspected burn involving the face and airway symptoms?","अनुहार जलेको र airway सम्बन्धी लक्षण भएको बिरामीमा कुन कदम उपयुक्त हुन्छ?",["Urgent airway assessment and emergency transfer","Apply ointment and discharge","Give oral fluids only","Wait for blisters to appear"],0,"Facial burns with hoarseness, soot or breathing difficulty may signal airway injury and need urgent specialist care.","आवाज बस्नु, कालो धुवाँको दाग वा सास गाह्रोसँगको अनुहारको burn ले airway injury देखाउन सक्छ; तत्काल विशेषज्ञ उपचार चाहिन्छ।","General Surgery"],
  ["Which position is commonly used to help a patient with suspected spinal injury during transfer?","Spinal injury शंका भएको बिरामीलाई transfer गर्दा कुन तरिका प्रयोग गरिन्छ?",["Maintain neutral alignment with appropriate spinal motion restriction","Sit upright and bend the neck","Allow twisting during transfer","Pull by the arms"],0,"Maintain neutral alignment and use trained handling and appropriate equipment according to trauma protocols.","Neutral alignment कायम राखेर प्रशिक्षित टोली र उपयुक्त उपकरणले trauma protocol अनुसार transfer गर्नुपर्छ।","General Surgery"],
  ["Which finding may indicate infection in a postoperative patient beyond the wound itself?","शल्यक्रियापछि घाउबाहेक कुन निष्कर्षले संक्रमण देखाउन सक्छ?",["Fever with tachycardia and worsening general condition","Improving appetite and normal observations","A healed incision","Mild stable scar itch"],0,"Fever, tachycardia, confusion or clinical deterioration may indicate systemic infection and needs prompt assessment.","ज्वरो, छिटो नाडी, अलमल वा अवस्था बिग्रनु systemic infection को संकेत हुन सक्छ; छिटो जाँच चाहिन्छ।","General Surgery"]
 );


 Q.push(
  ["Which activity is part of routine antenatal care?","नियमित गर्भजाँच सेवामा कुन गतिविधि पर्छ?",["Monitor maternal health, fetal growth and danger signs","Avoid checking blood pressure","Prescribe medicines without assessment","Discourage birth preparedness"],0,"Antenatal care includes maternal and fetal assessment, preventive interventions, counselling and birth preparedness.","गर्भजाँचमा आमा र भ्रूणको मूल्याङ्कन, preventive सेवा, परामर्श र प्रसव तयारी समावेश हुन्छ।","Community Health"],
  ["Which measure is useful for identifying a possible outbreak above the expected level?","अपेक्षित स्तरभन्दा बढी रोग देखिएको प्रकोप पहिचान गर्न कुन उपाय उपयोगी हुन्छ?",["Compare current case counts with baseline or expected levels","Count only health workers","Ignore seasonal patterns","Use one patient's symptoms only"],0,"Outbreak detection compares observed cases with expected baseline levels, considering seasonality and data quality.","प्रकोप पहिचानमा मौसम र तथ्याङ्कको गुणस्तर विचार गरी हालका केसलाई अपेक्षित baseline सँग तुलना गरिन्छ।","Community Health"],
  ["What is the main purpose of a health facility infection prevention committee?","स्वास्थ्य संस्थाको infection prevention committee को मुख्य उद्देश्य के हो?",["Coordinate infection prevention policies, monitoring and improvement","Approve patient food preferences only","Set medicine prices","Replace clinical teams"],0,"The committee supports infection prevention governance, training, surveillance, audit and corrective action.","समितिले संक्रमण रोकथामको नीति, तालिम, निगरानी, audit र सुधारात्मक कदम समन्वय गर्छ।","Community Health"],
  ["Which factor increases the risk of non-communicable diseases?","Non-communicable disease को जोखिम बढाउने कारण कुन हो?",["Tobacco use and physical inactivity","Handwashing with soap","Routine immunization","Safe drinking water"],0,"Tobacco use, unhealthy diet, harmful alcohol use and physical inactivity are major modifiable NCD risk factors.","सुर्ती, अस्वस्थ आहार, हानिकारक मदिरा र शारीरिक निष्क्रियता NCD का परिवर्तन गर्न सकिने मुख्य जोखिम हुन्।","Community Health"],
  ["Which action is important after a dog bite in a person with broken skin?","छाला फुट्ने गरी कुकुरले टोकेपछि कुन कदम महत्वपूर्ण हुन्छ?",["Wash the wound thoroughly and seek prompt rabies risk assessment and post-exposure care","Apply chilli powder","Close the wound tightly at home","Wait for symptoms of rabies"],0,"Immediate wound washing and prompt rabies exposure assessment for vaccine and immunoglobulin when indicated are essential.","घाउ तुरुन्त साबुनपानीले राम्ररी धुनु र आवश्यकताअनुसार rabies vaccine तथा immunoglobulin को मूल्याङ्कन गराउनु आवश्यक हुन्छ।","Community Health"],
  ["Which service is an example of a preventive health service for adolescents?","किशोरकिशोरीका लागि preventive health service को उदाहरण कुन हो?",["Counselling on nutrition, mental health and sexual/reproductive health","Only emergency surgery","Treatment after disability only","Avoid confidential discussion"],0,"Adolescent-friendly services include confidential, age-appropriate counselling and prevention across physical and mental health.","किशोरमैत्री सेवामा गोप्य, उमेरअनुकूल पोषण, मानसिक तथा यौन/प्रजनन स्वास्थ्य परामर्श र रोकथाम समावेश हुन्छ।","Community Health"],
  ["Which action best supports continuity of care for a patient with hypertension?","उच्च रक्तचाप भएको बिरामीको निरन्तर सेवा सुनिश्चित गर्न कुन कदम राम्रो हुन्छ?",["Regular follow-up, medicine adherence support and blood pressure monitoring","Stop follow-up when symptoms disappear","Change medicines without review","Measure blood pressure only once"],0,"Long-term hypertension care requires regular monitoring, adherence support, risk assessment and treatment review.","उच्च रक्तचापको दीर्घकालीन सेवामा नियमित निगरानी, औषधि पालनामा सहयोग, जोखिम मूल्याङ्कन र उपचार समीक्षा चाहिन्छ।","Community Health"],
  ["A patient has fever, productive cough and oxygen saturation of 86%. What is the priority?","ज्वरो र खकारसहित खोकी भएको बिरामीको oxygen saturation ८६% छ। प्राथमिकता के हो?",["Urgent oxygenation assessment, emergency management and referral","Routine appointment in one week","Give cough syrup only","Ask the patient to walk"],0,"An oxygen saturation of 86% is markedly low for most patients and requires urgent assessment and oxygen/emergency support per protocol.","धेरैजसो बिरामीमा ८६% oxygen saturation निकै कम हो; protocol अनुसार तत्काल मूल्याङ्कन र oxygen/आकस्मिक सहयोग चाहिन्छ।","General Medicine"],
  ["Which symptom is typical of acute cholecystitis?","Acute cholecystitis को सामान्य लक्षण कुन हो?",["Right upper abdominal pain with fever and tenderness","Painless hearing loss","Chronic itchy scalp","Sudden ankle deformity"],0,"Acute cholecystitis commonly causes right upper quadrant pain, fever and local tenderness, sometimes after meals.","Acute cholecystitis मा दायाँ माथिल्लो पेट दुख्ने, ज्वरो र tenderness हुन सक्छ, कहिलेकाहीँ खाना खाएपछि।","General Medicine"],
  ["Which finding may indicate meningococcal septicaemia?","Meningococcal septicaemia को संकेत कुन हुन सक्छ?",["Rapid deterioration with a non-blanching purpuric rash","Mild seasonal sneezing","Chronic stable knee pain","Painless callus"],0,"A rapidly spreading non-blanching purpuric rash with systemic illness is a medical emergency.","शरीर गम्भीर बिरामी हुँदा छिटो फैलिने नफिक्का purpuric rash आकस्मिक अवस्था हो।","General Medicine"],
  ["Which clinical finding is common in acute glomerulonephritis?","Acute glomerulonephritis मा सामान्यतया कुन निष्कर्ष देखिन्छ?",["Haematuria, oedema and hypertension","Excessive hair growth","Sudden hearing improvement","Isolated tooth sensitivity"],0,"Glomerular inflammation can cause blood in urine, fluid retention, oedema and raised blood pressure.","Glomerulus मा सूजन हुँदा पिसाबमा रगत, तरल जम्मा, सुन्निनु र रक्तचाप बढ्न सक्छ।","General Medicine"],
  ["A patient with severe headache has neck stiffness and photophobia. What is the priority?","कडा टाउको दुखाइसँग घाँटी कडा र प्रकाश सहन नसक्ने लक्षण छ। प्राथमिकता के हो?",["Urgent assessment for meningitis or other serious cause","Routine eye test only","Give a laxative","Advise prolonged screen use"],0,"Headache with neck stiffness and photophobia may indicate meningitis and needs urgent assessment.","घाँटी कडा र प्रकाश सहन नसक्ने टाउको दुखाइ meningitis को संकेत हुन सक्छ; तत्काल जाँच चाहिन्छ।","General Medicine"],
  ["Which medicine is a common loop diuretic?","सामान्य loop diuretic औषधि कुन हो?",["Furosemide","Metformin","Amoxicillin","Loratadine"],0,"Furosemide acts on the loop of Henle to increase sodium and water excretion.","Furosemide ले loop of Henle मा काम गरी sodium र पानीको उत्सर्जन बढाउँछ।","Pharmacology & Pharmacy"],
  ["Which medicine is commonly used as an antiplatelet after selected cardiovascular events?","केही cardiovascular घटनापछि antiplatelet का रूपमा कुन औषधि प्रयोग हुन्छ?",["Clopidogrel","Omeprazole","Albendazole","Cetirizine"],0,"Clopidogrel inhibits the platelet P2Y12 receptor and is used for selected cardiovascular indications.","Clopidogrel ले platelet P2Y12 receptor रोक्छ र केही cardiovascular अवस्थामा प्रयोग हुन्छ।","Pharmacology & Pharmacy"],
  ["Which practice reduces the risk of medication administration error?","औषधि दिने क्रममा त्रुटि घटाउने अभ्यास कुन हो?",["Read the label and verify patient, drug, dose, route and time","Rely only on tablet colour","Prepare medicines for several patients without labels","Ignore allergy history"],0,"Systematic medication checks and allergy verification reduce preventable errors.","व्यवस्थित औषधि जाँच र allergy पुष्टि गर्दा रोक्न सकिने त्रुटि घट्छ।","Pharmacology & Pharmacy"],
  ["A patient has a penetrating abdominal injury with protruding bowel. What is appropriate first aid?","पेटमा छेडिएको चोटपछि आन्द्रा बाहिर निस्किएको छ। पहिलो सहायता के हो?",["Cover with sterile saline-moistened dressing and arrange emergency surgery","Push bowel back inside","Give oral food and water","Apply pressure directly on bowel"],0,"Do not replace exposed organs; cover with sterile saline-moistened dressing and obtain immediate surgical care.","बाहिर निस्किएको आन्द्रा भित्र नधकेल्नुहोस्; sterile saline-moistened dressing ले छोपेर तत्काल surgical उपचार खोज्नुहोस्।","General Surgery"],
  ["Which injury requires urgent assessment for possible compartment syndrome?","Compartment syndrome को सम्भावनाका लागि कुन चोटको तत्काल मूल्याङ्कन चाहिन्छ?",["Tight swelling and escalating pain after a fracture","Small painless bruise","Healed scar","Mild itch"],0,"Increasing severe pain, tense swelling and pain on passive stretch after fracture are warning signs.","Fracture पछि बढ्दो कडा दुखाइ, कडा सुन्निनु र passive stretch गर्दा दुखाइ चेतावनी संकेत हुन्।","General Surgery"],
  ["Which action is appropriate for a suspected dislocated knee?","Knee dislocation शंका भए कुन कदम उपयुक्त हुन्छ?",["Immobilize, check distal circulation and arrange emergency referral","Forcefully straighten it","Ask the patient to walk","Massage behind the knee"],0,"Knee dislocation can injure the popliteal artery; urgent neurovascular assessment and specialist care are essential.","Knee dislocation ले popliteal artery मा चोट पुर्‍याउन सक्छ; तत्काल neurovascular जाँच र विशेषज्ञ उपचार चाहिन्छ।","General Surgery"],
  ["Which sign may indicate wound dehiscence after surgery?","शल्यक्रियापछि wound dehiscence को संकेत कुन हो?",["Separation of wound edges","Normal healed scar","Dry intact dressing","Improving tenderness"],0,"Wound dehiscence is separation of previously closed wound edges and needs prompt clinical assessment.","पहिले बन्द गरिएको घाउका किनारा छुट्टिनु wound dehiscence हो; छिटो clinical जाँच चाहिन्छ।","General Surgery"],
  ["What is the priority for a patient with suspected internal bleeding and signs of shock?","आन्तरिक रक्तस्राव शंका र shock का संकेत भएको बिरामीमा प्राथमिकता के हो?",["Emergency transfer, ABC support and control of external bleeding","Give oral fluids and discharge","Encourage walking","Delay monitoring"],0,"Suspected internal bleeding with shock requires immediate emergency care, monitoring and rapid transfer.","Shock सहित आन्तरिक रक्तस्राव शंका भए तत्काल आकस्मिक उपचार, निगरानी र छिटो transfer चाहिन्छ।","General Surgery"]
 );


 Q.push(
  ["Which action is recommended to reduce the risk of mother-to-child transmission of HIV?","आमाबाट बच्चामा HIV सर्ने जोखिम घटाउन कुन उपाय सिफारिस हुन्छ?",["Timely testing, ART and appropriate maternal-infant care","Avoid all antenatal visits","Breastfeed without individualized counselling","Delay treatment until symptoms develop"],0,"Early diagnosis, effective ART and guideline-based maternal and infant interventions greatly reduce transmission risk.","छिटो निदान, प्रभावकारी ART र guideline अनुसार आमा तथा शिशुको हेरचाहले संक्रमण सर्ने जोखिम धेरै घटाउँछ।","Community Health"],
  ["Which action is most appropriate when a health worker suspects child abuse?","स्वास्थ्यकर्मीलाई बाल दुर्व्यवहारको शंका भए कुन कदम उपयुक्त हुन्छ?",["Ensure immediate safety, document objectively and follow safeguarding/reporting procedures","Confront the suspected person alone","Ignore the concern without assessment","Promise absolute secrecy regardless of risk"],0,"Prioritize the child's safety, listen without leading questions, document facts and follow local safeguarding and reporting pathways.","बालबालिकाको सुरक्षा प्राथमिकता दिनुहोस्, leading प्रश्न नगरी सुन्नुहोस्, तथ्य अभिलेख गर्नुहोस् र safeguarding/reporting प्रक्रिया पालना गर्नुहोस्।","Community Health"],
  ["Which factor is important when selecting a health education message for a community?","समुदायका लागि स्वास्थ्य शिक्षा सन्देश छान्दा कुन कुरा महत्वपूर्ण हुन्छ?",["Local language, culture and health literacy","Use only technical English","Ignore local beliefs","Make the message as long as possible"],0,"Messages should be culturally appropriate, understandable, actionable and adapted to audience needs.","सन्देश स्थानीय भाषा र संस्कृतिअनुकूल, बुझिने, व्यवहारमा लागू गर्न मिल्ने र लक्षित समूहअनुसार हुनुपर्छ।","Community Health"],
  ["Which activity helps identify barriers to accessing health services?","स्वास्थ्य सेवा पहुँचमा अवरोध पहिचान गर्न कुन गतिविधि उपयोगी हुन्छ?",["Community consultation and service-user feedback","Counting only staff uniforms","Reviewing medicine colour","Ignoring people who do not attend"],0,"Consultation with users and underserved groups can reveal distance, cost, cultural and accessibility barriers.","सेवा प्रयोगकर्ता र सेवा नपुगेका समूहसँग छलफल गर्दा दूरी, खर्च, सांस्कृतिक र पहुँचसम्बन्धी अवरोध थाहा हुन्छ।","Community Health"],
  ["Which public health action is appropriate during a suspected foodborne outbreak?","खाद्यजन्य रोगको प्रकोप शंका हुँदा कुन जनस्वास्थ्य कदम उपयुक्त हुन्छ?",["Identify common food exposures, notify authorities and support safe food control","Continue serving the suspected food","Destroy all records","Give antibiotics to everyone without assessment"],0,"Investigate cases and shared exposures, notify public health authorities and implement proportionate food-safety measures.","केस र साझा खाना exposure अनुसन्धान गरी जनस्वास्थ्य निकायलाई खबर गर्नुहोस् र उपयुक्त food-safety उपाय लागू गर्नुहोस्।","Community Health"],
  ["Which symptom is a common feature of chronic kidney disease?","Chronic kidney disease को सामान्य लक्षण कुन हुन सक्छ?",["Fatigue, oedema or reduced appetite","Sudden improved vision","Acute ear discharge only","Increased hair growth"],0,"CKD may be asymptomatic early; later features include fatigue, oedema, appetite changes and biochemical abnormalities.","CKD सुरुमा लक्षणविहीन हुन सक्छ; पछि थकान, सुन्निनु, भोक घट्नु र biochemical परिवर्तन देखिन सक्छ।","General Medicine"],
  ["Which clinical sign may indicate acute appendicitis with peritoneal irritation?","Peritoneal irritation सहित acute appendicitis को संकेत कुन हुन सक्छ?",["Rebound tenderness in the right lower abdomen","Painless bilateral ankle swelling","Chronic hearing loss","Itchy scalp"],0,"Right lower quadrant tenderness with rebound or guarding can indicate appendicitis and requires urgent assessment.","दायाँ तल्लो पेटमा rebound वा guarding सहित दुखाइ appendicitis को संकेत हुन सक्छ; तत्काल जाँच चाहिन्छ।","General Medicine"],
  ["A patient with diabetes is unconscious and hypoglycaemia is suspected. What should be avoided?","मधुमेह भएको बिरामी बेहोस छ र hypoglycaemia शंका छ। के गर्नु हुँदैन?",["Giving food or liquid by mouth","Calling emergency help","Checking airway and breathing","Following the emergency protocol"],0,"Never give oral food or fluid to an unconscious person due to aspiration risk; provide emergency care according to protocol.","बेहोस व्यक्तिलाई aspiration जोखिमका कारण मुखबाट खाना वा तरल नदिनुहोस्; protocol अनुसार आकस्मिक उपचार गर्नुहोस्।","General Medicine"],
  ["Which test is used to assess lung function and airflow obstruction?","फोक्सोको कार्य र airflow obstruction जाँच्न कुन परीक्षण प्रयोग हुन्छ?",["Spirometry","ECG","Urine dipstick","Otoscopy"],0,"Spirometry measures airflow and volumes and helps diagnose and monitor obstructive lung disease.","Spirometry ले airflow र lung volume मापन गरी obstructive lung disease निदान तथा निगरानीमा सहयोग गर्छ।","General Medicine"],
  ["Which condition may cause a bounding pulse and widened pulse pressure?","कुन अवस्थामा bounding pulse र pulse pressure फराकिलो हुन सक्छ?",["Aortic regurgitation","Severe dehydration in every case","Complete heart block only","Acute otitis externa"],0,"Aortic regurgitation can produce a wide pulse pressure and bounding peripheral pulse.","Aortic regurgitation मा pulse pressure फराकिलो र peripheral pulse बलियो हुन सक्छ।","General Medicine"],
  ["Which medication class is commonly used to treat bacterial hypertension-related fluid overload?","उच्च रक्तचापसँग सम्बन्धित तरल बढी भएको अवस्थामा प्रयोग हुने औषधि वर्ग कुन हो?",["Diuretics","Antifungals","Anthelmintics","Antihistamines"],0,"Diuretics increase renal sodium and water excretion and may be used for hypertension or fluid overload depending on the patient.","Diuretic ले मिर्गौलाबाट sodium र पानीको उत्सर्जन बढाउँछ र बिरामीअनुसार उच्च रक्तचाप वा fluid overload मा प्रयोग हुन्छ।","Pharmacology & Pharmacy"],
  ["Which medicine is an example of a proton pump inhibitor?","Proton pump inhibitor को उदाहरण कुन औषधि हो?",["Omeprazole","Aspirin","Metformin","Cetirizine"],0,"Omeprazole inhibits the gastric proton pump and reduces acid secretion.","Omeprazole ले gastric proton pump रोक्दै acid secretion घटाउँछ।","Pharmacology & Pharmacy"],
  ["What should be done if a patient has a documented severe allergy to a prescribed medicine?","Prescription गरिएको औषधिमा बिरामीको documented severe allergy छ भने के गर्नुपर्छ?",["Do not administer; contact the prescriber for a safe alternative","Give a small test dose without authorization","Ignore the allergy record","Ask the patient to take an antihistamine and proceed"],0,"A serious documented allergy requires withholding the suspected medicine and urgent clarification for an appropriate alternative.","गम्भीर allergy अभिलेख छ भने शंकास्पद औषधि नदिनुहोस् र सुरक्षित विकल्पका लागि prescriber सँग तुरुन्त पुष्टि गर्नुहोस्।","Pharmacology & Pharmacy"],
  ["Which injury should be suspected when a patient has severe pain on passive stretch after a limb fracture?","अंग भाँचिएपछि passive stretch गर्दा धेरै दुखेमा कुन जटिलता शंका गर्नुपर्छ?",["Compartment syndrome","Simple bruise","Uncomplicated sprain","Chronic dermatitis"],0,"Pain out of proportion and pain on passive stretch are early warning signs of compartment syndrome.","अत्यधिक दुखाइ र passive stretch गर्दा दुख्नु compartment syndrome का प्रारम्भिक चेतावनी संकेत हुन्।","General Surgery"],
  ["Which action is appropriate for a patient with a suspected open chest wound?","Open chest wound शंका भएको बिरामीमा कुन कदम उपयुक्त हुन्छ?",["Activate emergency response and follow current chest-wound protocol","Pack the wound deeply with cloth","Remove embedded objects","Give food and fluids"],0,"Open chest injuries can impair ventilation; urgent emergency care and trained protocol-based wound management are required.","Open chest injury ले ventilation बिगार्न सक्छ; तत्काल आकस्मिक उपचार र प्रशिक्षित protocol अनुसार घाउ व्यवस्थापन चाहिन्छ।","General Surgery"],
  ["Which sign after a head injury may suggest a basal skull fracture?","टाउकोमा चोटपछि कुन संकेतले basal skull fracture देखाउन सक्छ?",["Bruising behind the ear or around both eyes","A small superficial hand cut","Mild ankle swelling","Normal hearing and no symptoms"],0,"Battle sign or periorbital ecchymosis after trauma can suggest basal skull fracture and requires urgent assessment.","चोटपछि कान पछाडि वा दुवै आँखावरिपरि नीलडाम basal skull fracture को संकेत हुन सक्छ; तत्काल जाँच चाहिन्छ।","General Surgery"],
  ["What is the appropriate action for a patient with suspected acute limb ischaemia?","Acute limb ischaemia शंका भएको बिरामीमा कुन कदम उपयुक्त हुन्छ?",["Urgent vascular assessment and emergency referral","Apply a tight bandage and wait","Massage the limb vigorously","Encourage prolonged walking"],0,"Sudden pain, pallor, pulselessness, coldness, paraesthesia or paralysis indicate threatened limb and need emergency vascular care.","अचानक दुखाइ, फिक्कापन, नाडी नहुनु, चिसोपन, झमझम वा पक्षाघातले अंग जोखिममा परेको देखाउँछ; आकस्मिक vascular उपचार चाहिन्छ।","General Surgery"],
  ["Which practice is important before transferring a patient with a suspected fracture?","Fracture शंका भएको बिरामी transfer गर्नुअघि कुन अभ्यास महत्वपूर्ण हुन्छ?",["Check and document distal neurovascular status","Forcefully test range of motion","Remove all support","Ask the patient to walk"],0,"Document pulses, capillary refill, sensation and movement before and after immobilization and transfer.","Immobilization र transfer अघि तथा पछि नाडी, capillary refill, संवेदना र movement अभिलेख गर्नुपर्छ।","General Surgery"],
  ["Which symptom following abdominal surgery may indicate paralytic ileus?","पेटको शल्यक्रियापछि कुन लक्षणले paralytic ileus देखाउन सक्छ?",["Abdominal distension, vomiting and failure to pass flatus","Normal bowel sounds and stool passage","Improving appetite","Mild wound itch only"],0,"Ileus can cause abdominal distension, nausea, vomiting and delayed passage of flatus or stool.","Ileus हुँदा पेट फुल्ने, वाकवाकी, बान्ता र दिसा वा ग्यास ननिस्कने हुन सक्छ।","General Surgery"]
 );


 Q.push(
  ["Which action is appropriate for a patient with suspected stroke who is unable to swallow safely?","निल्न नसक्ने stroke शंका भएको बिरामीमा कुन कदम उपयुक्त हुन्छ?",["Keep nil by mouth and arrange urgent assessment","Give oral tablets with water","Offer food to test swallowing","Place food at the back of the throat"],0,"Dysphagia after stroke creates aspiration risk; keep nil by mouth until swallowing has been assessed by a trained professional.","Stroke पछि dysphagia हुँदा aspiration जोखिम हुन्छ; प्रशिक्षित व्यक्तिले swallowing जाँच नगरेसम्म मुखबाट केही नदिनुहोस्।","General Medicine"],
  ["Which symptom is a common feature of peripheral arterial disease?","Peripheral arterial disease को सामान्य लक्षण कुन हो?",["Calf pain on walking relieved by rest","Pain only after eating","Sudden itchy rash","Chronic ear discharge"],0,"Intermittent claudication is exertional limb pain that improves with rest due to reduced arterial blood flow.","Intermittent claudication मा धमनीबाट रगत कम पुग्दा हिँड्दा खुट्टा दुख्छ र आराम गर्दा कम हुन्छ।","General Medicine"],
  ["A patient with suspected sepsis has confusion, rapid breathing and low blood pressure. What is the priority?","Sepsis शंका भएको बिरामी अलमलिएको, छिटो सास फेरेको र रक्तचाप कम छ। प्राथमिकता के हो?",["Immediate emergency sepsis assessment and treatment","Routine follow-up tomorrow","Give only oral vitamins","Wait for fever to develop"],0,"Confusion, tachypnoea and hypotension suggest severe sepsis or shock and require immediate protocol-based care.","अलमल, छिटो श्वास र कम रक्तचाप severe sepsis वा shock का संकेत हुन्; तत्काल protocol अनुसार उपचार चाहिन्छ।","General Medicine"],
  ["Which finding may indicate acute appendicitis in a child?","बालबालिकामा acute appendicitis को संकेत कुन हुन सक्छ?",["Progressive abdominal pain with vomiting and right lower quadrant tenderness","Isolated painless cough","Chronic itchy eyes","Painless ankle swelling"],0,"Progressive abdominal pain, vomiting and localized tenderness require prompt assessment for appendicitis.","बढ्दो पेट दुखाइ, बान्ता र स्थानीय tenderness हुँदा appendicitis का लागि छिटो जाँच गर्नुपर्छ।","General Medicine"],
  ["Which condition is associated with a high fever, severe muscle pain and bleeding manifestations after mosquito exposure in endemic areas?","Endemic क्षेत्रमा लामखुट्टेको exposure पछि उच्च ज्वरो, धेरै मांसपेशी दुखाइ र रक्तस्राव देखिए कुन रोग विचार गर्नुपर्छ?",["Dengue","Osteoarthritis","Otitis externa","Peptic ulcer"],0,"Dengue may cause high fever, severe myalgia and warning signs such as bleeding, abdominal pain or persistent vomiting.","Dengue मा उच्च ज्वरो, धेरै मांसपेशी दुखाइ र रक्तस्राव, पेट दुखाइ वा लगातार बान्ता जस्ता warning sign हुन सक्छन्।","General Medicine"],
  ["Which medicine is commonly used for treatment of uncomplicated scabies?","जटिलता नभएको scabies उपचारमा कुन औषधि सामान्यतया प्रयोग हुन्छ?",["Permethrin 5% cream","Amlodipine tablet","Omeprazole capsule","Salbutamol inhaler"],0,"Permethrin 5% topical cream is a common treatment; close contacts and laundering measures should be addressed according to guidance.","Permethrin 5% cream scabies को सामान्य उपचार हो; नजिकका सम्पर्क र कपडा धुने उपाय पनि निर्देशनअनुसार गर्नुपर्छ।","Pharmacology & Pharmacy"],
  ["Which medicine is used to treat intestinal worm infections?","आन्द्राका जुका संक्रमण उपचार गर्न कुन औषधि प्रयोग हुन्छ?",["Albendazole","Aspirin","Amlodipine","Insulin"],0,"Albendazole is an anthelmintic used for selected intestinal helminth infections according to local guidance.","Albendazole स्थानीय निर्देशनअनुसार केही intestinal helminth संक्रमणमा प्रयोग हुने anthelmintic हो।","Pharmacology & Pharmacy"],
  ["Which medicine class is used to treat fungal infections?","Fungal infection उपचार गर्न कुन औषधि समूह प्रयोग हुन्छ?",["Antifungals","Anticoagulants","Antiplatelets","Antihypertensives"],0,"Antifungal medicines act against fungi; choice depends on the organism, site and severity.","Antifungal औषधिले fungi विरुद्ध काम गर्छ; छनोट जीव, संक्रमणको स्थान र गम्भीरतामा निर्भर हुन्छ।","Pharmacology & Pharmacy"],
  ["Which action is important when a patient is prescribed insulin?","बिरामीलाई insulin दिइएको छ भने कुन निर्देशन महत्वपूर्ण हुन्छ?",["Teach correct storage, injection technique, site rotation and hypoglycaemia recognition","Store all insulin in direct sunlight","Reuse needles between patients","Stop meals after injection"],0,"Safe insulin use requires correct storage, dose, injection technique, site rotation and recognition of hypoglycaemia.","Insulin सुरक्षित प्रयोग गर्न सही भण्डारण, dose, injection technique, site rotation र hypoglycaemia पहिचान सिकाउनुपर्छ।","Pharmacology & Pharmacy"],
  ["Which action is appropriate for a patient with suspected acute compartment syndrome?","Acute compartment syndrome शंका भएको बिरामीमा कुन कदम उपयुक्त हुन्छ?",["Urgent surgical assessment; loosen constrictive dressings if appropriate and do not delay","Apply a tight bandage","Elevate excessively above heart level in all cases","Wait until pulses disappear"],0,"Compartment syndrome is time-critical; urgent surgical review is needed before irreversible tissue damage occurs.","Compartment syndrome समय-संवेदनशील अवस्था हो; tissue damage स्थायी हुनुअघि तत्काल surgical जाँच चाहिन्छ।","General Surgery"],
  ["Which finding may indicate a tension pneumothorax?","Tension pneumothorax को संकेत कुन हुन सक्छ?",["Severe respiratory distress with hypotension and unilateral reduced breath sounds","Mild bilateral ankle swelling","Chronic itchy rash","Normal breathing and stable vital signs"],0,"Tension pneumothorax can cause severe distress, hypotension and reduced breath sounds on one side; immediate emergency treatment is required.","Tension pneumothorax मा गम्भीर सास कष्ट, रक्तचाप कम र एकातिर breath sound घट्न सक्छ; तत्काल आकस्मिक उपचार चाहिन्छ।","General Surgery"],
  ["What is the priority when a patient has an amputated finger after an accident?","दुर्घटनामा औँला काटिएर छुटेको छ भने प्राथमिकता के हो?",["Control bleeding, wrap the part in clean moist gauze, seal and cool appropriately, and transfer urgently","Place the part directly on ice","Scrub the part with disinfectant","Discard the amputated part"],0,"Control bleeding and preserve the amputated part in a sealed bag kept cool without direct ice contact; urgent specialist transfer is needed.","रक्तस्राव रोक्नुहोस् र काटिएको भाग सफा नम gauze मा बेरेर बन्द झोलामा राखी प्रत्यक्ष बरफ नछुवाई चिसो राख्नुहोस्; तत्काल transfer चाहिन्छ।","General Surgery"],
  ["Which symptom after surgery may indicate deep wound infection?","शल्यक्रियापछि कुन लक्षणले गहिरो घाउ संक्रमण देखाउन सक्छ?",["Increasing deep pain, fever and purulent drainage","A clean dry incision","Improving mobility","Normal temperature"],0,"Deep pain, fever, wound separation or purulent drainage may indicate a deep surgical-site infection.","गहिरो दुखाइ, ज्वरो, घाउ छुट्टिनु वा पीप आउनु deep surgical-site infection को संकेत हुन सक्छ।","General Surgery"],
  ["Which action is appropriate when a patient has a suspected foreign body in the airway and cannot speak or cough effectively?","श्वासमार्गमा वस्तु अड्किएको शंका र बिरामी बोल्न वा प्रभावकारी खोकी गर्न नसक्ने अवस्थामा के गर्नुपर्छ?",["Activate emergency response and provide age-appropriate choking first aid","Offer water to drink","Perform blind finger sweeps","Leave the patient alone"],0,"Severe airway obstruction requires immediate age-appropriate choking manoeuvres and emergency support; avoid blind finger sweeps.","गम्भीर airway obstruction मा उमेरअनुसार choking first aid र आकस्मिक सहयोग तुरुन्त चाहिन्छ; नदेखिएको वस्तु औँलाले खोज्नु हुँदैन।","General Surgery"],
  ["Which test is commonly used to assess anaemia severity?","Anaemia को गम्भीरता मूल्याङ्कन गर्न कुन परीक्षण सामान्यतया प्रयोग हुन्छ?",["Haemoglobin concentration","Serum amylase","ECG","Urine culture"],0,"Haemoglobin concentration helps classify and assess the severity of anaemia alongside clinical status.","Haemoglobin concentration ले clinical अवस्था सँगै anaemia को स्तर र गम्भीरता मूल्याङ्कन गर्न मद्दत गर्छ।","Clinical Pathology"],
  ["Which laboratory result is commonly associated with bacterial infection?","Bacterial infection सँग कुन laboratory result सम्बन्धित हुन सक्छ?",["Raised white blood cell count with neutrophilia","Low platelet count in every case","Low serum calcium only","High urine glucose only"],0,"Leukocytosis with neutrophilia may support bacterial infection but is nonspecific and must be interpreted clinically.","Neutrophilia सहित leukocytosis ले bacterial infection को समर्थन गर्न सक्छ तर यो विशिष्ट होइन; clinical अवस्थासँग बुझ्नुपर्छ।","Clinical Pathology"],
  ["Which test is used to assess blood clotting through the extrinsic and common pathways?","Extrinsic र common clotting pathway जाँच्न कुन परीक्षण प्रयोग हुन्छ?",["Prothrombin time/INR","Bleeding time only","Serum creatinine","HbA1c"],0,"PT/INR assesses the extrinsic and common coagulation pathways and is used to monitor warfarin.","PT/INR ले extrinsic र common coagulation pathway जाँच्छ र warfarin निगरानीमा प्रयोग हुन्छ।","Clinical Pathology"],
  ["Which laboratory test is commonly used to assess platelet count?","Platelet संख्या जाँच्न कुन laboratory test प्रयोग हुन्छ?",["Complete blood count","Urine dipstick","Liver ultrasound","Stool microscopy"],0,"A complete blood count includes platelet count and other blood cell measurements.","Complete blood count मा platelet संख्या र अन्य रक्तकोषिका मापन समावेश हुन्छ।","Clinical Pathology"]
 );


 Q.push(
  ["Which finding is commonly seen in vitamin B12 deficiency?","Vitamin B12 कमी हुँदा सामान्यतया कुन निष्कर्ष देखिन्छ?",["Macrocytic anaemia with possible neurological symptoms","Microcytosis in every case","High platelet count only","Raised serum calcium only"],0,"Vitamin B12 deficiency can cause megaloblastic macrocytic anaemia and neurological impairment.","Vitamin B12 कमीले megaloblastic macrocytic anaemia र स्नायु सम्बन्धी समस्या गराउन सक्छ।","Clinical Pathology"],
  ["Which specimen is appropriate for stool microscopy for intestinal parasites?","आन्द्राका परजीवी जाँच्न stool microscopy का लागि कुन नमुना उपयुक्त हुन्छ?",["Fresh stool in a clean, leak-proof container","Stool mixed with disinfectant","Stool collected from the floor","Old dry stool in an open bag"],0,"Fresh stool collected in a clean leak-proof container is suitable; transport promptly according to laboratory instructions.","सफा leak-proof container मा ताजा दिसा संकलन उपयुक्त हुन्छ; laboratory निर्देशनअनुसार छिटो पठाउनुपर्छ।","Clinical Pathology"],
  ["Which blood test is commonly used to assess liver cell injury?","कलेजोका कोषिकामा चोट/क्षति मूल्याङ्कन गर्न कुन रक्त परीक्षण उपयोगी हुन्छ?",["ALT and AST","Troponin only","Serum sodium only","Bleeding time"],0,"ALT and AST are aminotransferases that may rise with hepatocellular injury.","ALT र AST aminotransferase हुन्; कलेजोका कोषिकामा क्षति हुँदा बढ्न सक्छन्।","Clinical Pathology"],
  ["Which laboratory finding may support acute bacterial infection?","Acute bacterial infection को समर्थन गर्ने laboratory finding कुन हुन सक्छ?",["Neutrophilia","Low haemoglobin only","Low serum albumin only","Reduced urine pH only"],0,"Neutrophilia may support bacterial infection but is not diagnostic alone.","Neutrophilia ले bacterial infection को समर्थन गर्न सक्छ तर एक्लैले निदान गर्दैन।","Clinical Pathology"],
  ["Which condition can cause a low platelet count?","Platelet संख्या कम हुने अवस्था कुन हुन सक्छ?",["Thrombocytopenia","Polycythaemia","Hypernatraemia","Hyperglycaemia"],0,"Thrombocytopenia means a reduced platelet count and may increase bleeding risk depending on severity and cause.","Thrombocytopenia भनेको platelet संख्या घट्नु हो; कारण र गम्भीरताअनुसार रक्तस्राव जोखिम बढ्न सक्छ।","Clinical Pathology"],
  ["Which measure is essential when collecting a blood specimen?","रगतको नमुना संकलन गर्दा कुन कुरा आवश्यक हुन्छ?",["Correct patient identification and proper labelling at collection","Label tubes later from memory","Use one label for several patients","Ignore collection time"],0,"Confirm patient identity and label the specimen at the point of collection to prevent serious errors.","गम्भीर त्रुटि रोक्न नमुना लिने ठाउँमै बिरामीको पहिचान पुष्टि गरी label लगाउनुपर्छ।","Clinical Pathology"],
  ["Which condition is a common cause of acute severe chest pain with sweating and nausea?","पसिना र वाकवाकीसहितको acute severe chest pain को सामान्य कारण कुन हो?",["Acute coronary syndrome","Chronic dermatitis","Otitis externa","Uncomplicated cataract"],0,"Acute coronary syndrome may cause central chest pressure, sweating, nausea and radiation to arm or jaw.","Acute coronary syndrome मा छातीको बीचमा दबाब, पसिना, वाकवाकी र हात वा जबडातिर दुखाइ सर्न सक्छ।","General Medicine"],
  ["Which symptom may indicate an acute exacerbation of chronic obstructive pulmonary disease?","COPD को acute exacerbation को संकेत कुन हुन सक्छ?",["Increased breathlessness, sputum volume or sputum purulence","Improved exercise tolerance","Sudden painless rash","Reduced need for inhalers with worsening symptoms"],0,"An exacerbation often involves worsening dyspnoea, cough and changes in sputum volume or purulence.","Exacerbation मा सास गाह्रो बढ्ने, खोकी र खकारको मात्रा वा पीपिलोपन परिवर्तन हुन सक्छ।","General Medicine"],
  ["Which clinical feature may suggest acute pancreatitis rather than simple dyspepsia?","साधारण dyspepsia भन्दा acute pancreatitis को सम्भावना देखाउने लक्षण कुन हो?",["Severe persistent upper abdominal pain radiating to the back","Mild brief belching only","Itchy scalp","Painless ear discharge"],0,"Acute pancreatitis commonly causes severe persistent epigastric pain radiating to the back with nausea or vomiting.","Acute pancreatitis मा माथिल्लो पेटको लगातार कडा दुखाइ ढाडतिर सर्नु र वाकवाकी/बान्ता हुन सक्छ।","General Medicine"],
  ["A patient with fever has a painful red swollen leg and rapidly spreading skin changes. What should be considered?","ज्वरो भएको बिरामीको खुट्टा रातो, सुन्निएको र छालाको परिवर्तन छिटो फैलिएको छ। के विचार गर्नुपर्छ?",["Cellulitis or a deeper soft-tissue infection","Simple dry skin","Chronic myopia","Uncomplicated migraine"],0,"Rapidly spreading erythema with fever may indicate cellulitis or serious soft-tissue infection requiring prompt assessment.","ज्वरोसँग छिटो फैलिने रातोपन cellulitis वा गम्भीर soft-tissue infection हुन सक्छ; छिटो जाँच चाहिन्छ।","General Medicine"],
  ["Which clinical finding is common in Parkinson disease?","Parkinson disease मा सामान्यतया कुन लक्षण देखिन्छ?",["Resting tremor, rigidity and bradykinesia","Sudden severe diarrhoea","High fever with rash","Acute painful red eye"],0,"Parkinson disease commonly causes bradykinesia, rigidity and resting tremor, with variable postural instability.","Parkinson disease मा movement ढिलो, rigidity र आराम अवस्थामा tremor हुन सक्छ; सन्तुलन समस्या पनि हुन सक्छ।","General Medicine"],
  ["Which medicine is used as a bronchodilator in asthma?","Asthma मा bronchodilator का रूपमा कुन औषधि प्रयोग हुन्छ?",["Salbutamol","Ferrous sulfate","Warfarin","Omeprazole"],0,"Salbutamol is a short-acting beta-2 agonist used for rapid relief of bronchospasm.","Salbutamol short-acting beta-2 agonist हो र bronchospasm मा छिटो राहत दिन्छ।","Pharmacology & Pharmacy"],
  ["Which medicine is commonly used to treat hypothyroidism?","Hypothyroidism उपचार गर्न कुन औषधि प्रयोग हुन्छ?",["Levothyroxine","Methimazole","Adrenaline","Furosemide"],0,"Levothyroxine replaces thyroid hormone and is adjusted according to clinical and thyroid function monitoring.","Levothyroxine ले thyroid hormone पूर्ति गर्छ र clinical तथा thyroid function जाँचअनुसार dose मिलाइन्छ।","Pharmacology & Pharmacy"],
  ["Which instruction is important for patients taking oral iron?","Oral iron खाने बिरामीलाई कुन निर्देशन महत्वपूर्ण हुन्छ?",["Stools may become darker and constipation can occur","Stop immediately if stools darken without other symptoms","Take double doses after a missed tablet","Share tablets with family"],0,"Oral iron can darken stools and cause gastrointestinal effects; patients should follow prescribed dosing and seek advice for concerning symptoms.","Oral iron ले दिसा गाढा र पेटसम्बन्धी असर गराउन सक्छ; prescription अनुसार लिनुहोस् र चिन्ताजनक लक्षणमा सल्लाह लिनुहोस्।","Pharmacology & Pharmacy"],
  ["Which action is appropriate for suspected acute appendicitis before surgical assessment?","Surgical assessment अघि acute appendicitis शंका भएको बिरामीमा कुन कदम उपयुक्त हुन्छ?",["Arrange urgent referral and avoid giving food or drink pending assessment","Give a laxative","Apply strong abdominal massage","Delay referral for several days"],0,"Suspected appendicitis needs urgent assessment; oral intake may be withheld pending surgical review according to protocol.","Appendicitis शंका हुँदा तत्काल जाँच चाहिन्छ; protocol अनुसार surgical review नहुँदासम्म मुखबाट खाना-पानी रोक्नुपर्ने हुन सक्छ।","General Surgery"],
  ["Which action is appropriate for a patient with suspected fracture and an open wound?","खुला घाउसहित fracture शंका भएको बिरामीमा कुन कदम उपयुक्त हुन्छ?",["Cover the wound with sterile dressing and immobilize the limb","Probe the wound with fingers","Push bone fragments into place","Allow weight-bearing"],0,"Cover the wound, immobilize the limb, assess distal neurovascular status and arrange urgent referral.","घाउ छोप्नुहोस्, अंग immobilize गर्नुहोस्, distal neurovascular अवस्था जाँचेर तत्काल referral गर्नुहोस्।","General Surgery"],
  ["Which sign after a fall may indicate a hip fracture in an older adult?","वृद्ध व्यक्ति लडेपछि कुन संकेतले hip fracture देखाउन सक्छ?",["Hip pain with shortened, externally rotated leg","Normal painless walking","Isolated itchy hand","Improved range of motion"],0,"Hip fracture may present with pain, inability to bear weight and a shortened externally rotated leg.","Hip fracture मा दुखाइ, भार राख्न नसक्नु र खुट्टा छोटो तथा बाहिर फर्किएको देखिन सक्छ।","General Surgery"],
  ["Which action is important for preventing infection during wound dressing?","घाउ dressing गर्दा संक्रमण रोक्न कुन कदम महत्वपूर्ण हुन्छ?",["Perform hand hygiene and use aseptic technique","Reuse soiled dressings","Touch sterile supplies with unclean hands","Leave the wound exposed to dust"],0,"Hand hygiene and aseptic technique reduce contamination during wound care.","Hand hygiene र aseptic technique ले घाउ हेरचाह गर्दा contamination घटाउँछ।","General Surgery"],
  ["Which symptom may indicate a postoperative urinary retention problem?","शल्यक्रियापछि कुन लक्षणले urinary retention देखाउन सक्छ?",["Inability to pass urine with suprapubic discomfort","Frequent normal urine output","Improving appetite","Mild scar itch"],0,"Inability to void with lower abdominal or suprapubic discomfort suggests retention and needs assessment.","पिसाब गर्न नसक्नु र तल्लो पेट दुख्नु urinary retention को संकेत हुन सक्छ; जाँच आवश्यक हुन्छ।","General Surgery"],
  ["Which finding is a possible sign of wound sepsis?","घाउसँग सम्बन्धित sepsis को सम्भावित संकेत कुन हो?",["Fever, rapid pulse and worsening general condition","Normal temperature and improving pain","Dry intact wound only","Normal appetite"],0,"Systemic deterioration with fever and tachycardia in a patient with a wound may indicate sepsis and needs urgent care.","घाउ भएको बिरामीमा ज्वरो, छिटो नाडी र अवस्था बिग्रनु sepsis को संकेत हुन सक्छ; तत्काल उपचार चाहिन्छ।","General Surgery"]
 );


 Q.push(
  ["Which symptom is typical of acute otitis media?","Acute otitis media को सामान्य लक्षण कुन हो?",["Ear pain with fever and possible reduced hearing","Painless ankle swelling","Sudden severe abdominal guarding","Chronic constipation only"],0,"Acute otitis media commonly causes otalgia, fever and sometimes reduced hearing or ear discharge.","Acute otitis media मा कान दुख्ने, ज्वरो र कहिलेकाहीँ सुनाइ कम वा कानबाट discharge हुन सक्छ।","General Medicine"],
  ["Which finding may indicate severe malaria?","गम्भीर malaria को संकेत कुन हुन सक्छ?",["Altered consciousness, respiratory distress or severe anaemia","Mild isolated itching","Normal activity with no fever","Chronic painless callus"],0,"Severe malaria can cause impaired consciousness, respiratory distress, severe anaemia, hypoglycaemia or organ dysfunction and needs emergency care.","गम्भीर malaria मा चेतना परिवर्तन, सास कष्ट, गम्भीर anaemia, hypoglycaemia वा अंगको कार्य बिग्रन सक्छ; आकस्मिक उपचार चाहिन्छ।","General Medicine"],
  ["Which symptom may suggest an ectopic pregnancy?","Ectopic pregnancy को सम्भावना देखाउने लक्षण कुन हो?",["Missed period with lower abdominal pain and vaginal bleeding","Mild bilateral shoulder stiffness","Chronic itchy eyes","Painless ear discharge"],0,"A missed period with abdominal pain and bleeding may indicate ectopic pregnancy, especially with dizziness or collapse.","महिनावारी छुट्नु, पेट दुख्नु र रक्तस्राव ectopic pregnancy को संकेत हुन सक्छ; चक्कर वा collapse भए झन् आकस्मिक हुन्छ।","General Medicine"],
  ["Which finding is common in acute rheumatic fever?","Acute rheumatic fever मा सामान्यतया कुन निष्कर्ष देखिन्छ?",["Migratory polyarthritis after streptococcal infection","Sudden painless vision improvement","Chronic skin dryness only","Isolated tooth sensitivity"],0,"Acute rheumatic fever can follow group A streptococcal infection and cause migratory large-joint arthritis and carditis.","Group A streptococcal संक्रमणपछि acute rheumatic fever भएर ठूला जोर्नीमा सर्ने दुखाइ र carditis हुन सक्छ।","General Medicine"],
  ["Which symptom may indicate acute glaucoma?","Acute glaucoma को संकेत कुन हुन सक्छ?",["Severe eye pain, red eye and blurred vision with halos","Mild painless dry skin","Chronic knee stiffness","Ear wax only"],0,"Acute angle closure may cause severe ocular pain, redness, blurred vision, halos, headache and nausea.","Acute angle closure मा आँखाको कडा दुखाइ, रातोपन, धमिलो दृष्टि, halos, टाउको दुखाइ र वाकवाकी हुन सक्छ।","General Medicine"],
  ["Which medicine is used as a vitamin K antagonist anticoagulant?","Vitamin K antagonist anticoagulant का रूपमा कुन औषधि प्रयोग हुन्छ?",["Warfarin","Heparin","Aspirin","Clopidogrel"],0,"Warfarin inhibits vitamin K recycling and reduces synthesis of vitamin K-dependent clotting factors.","Warfarin ले vitamin K recycling रोक्दै vitamin K-निर्भर clotting factor निर्माण घटाउँछ।","Pharmacology & Pharmacy"],
  ["Which medicine is commonly used to treat hypothyroidism in pregnancy when indicated?","आवश्यक अवस्थामा गर्भावस्थामा hypothyroidism उपचार गर्न कुन औषधि प्रयोग हुन्छ?",["Levothyroxine","Methotrexate","Warfarin","Isotretinoin"],0,"Levothyroxine is thyroid hormone replacement and is generally continued or adjusted with close monitoring during pregnancy.","Levothyroxine thyroid hormone replacement हो र गर्भावस्थामा नजिकबाट निगरानी गरी जारी वा dose मिलाइन्छ।","Pharmacology & Pharmacy"],
  ["Which practice helps reduce antimicrobial resistance?","Antimicrobial resistance घटाउन कुन अभ्यास सहयोगी हुन्छ?",["Use antimicrobials only when indicated and follow appropriate regimens","Use antibiotics for every viral cold","Share leftover antibiotics","Stop prescribed therapy without advice"],0,"Antimicrobial stewardship promotes appropriate selection, dose and duration and avoids unnecessary use.","Antimicrobial stewardship ले सही औषधि, dose र अवधि प्रयोग गराउँछ र अनावश्यक प्रयोग रोक्छ।","Pharmacology & Pharmacy"],
  ["Which laboratory test is used to detect glucose in urine?","पिसाबमा glucose पत्ता लगाउन कुन परीक्षण प्रयोग हुन्छ?",["Urine dipstick","ECG","Chest X-ray","Sputum smear"],0,"Urine dipstick can detect glucose, although blood glucose testing is needed to diagnose and assess diabetes.","Urine dipstick ले पिसाबमा glucose देखाउन सक्छ, तर diabetes निदान र मूल्याङ्कनका लागि blood glucose जाँच चाहिन्छ।","Clinical Pathology"],
  ["Which blood component is measured as packed cell volume or haematocrit?","Packed cell volume वा haematocrit ले कुन रक्तघटकको अनुपात जनाउँछ?",["Red blood cells","Platelets","Plasma glucose","White blood cells only"],0,"Haematocrit is the proportion of blood volume occupied by red blood cells.","Haematocrit ले रगतको कुल आयतनमा red blood cell ले ओगटेको अनुपात जनाउँछ।","Clinical Pathology"],
  ["Which test is commonly used to detect malaria parasites rapidly at the point of care?","Malaria parasite छिटो पत्ता लगाउन point-of-care मा कुन परीक्षण प्रयोग हुन्छ?",["Malaria rapid diagnostic test","Widal test","Mantoux test","Urine pregnancy test"],0,"Malaria rapid diagnostic tests detect parasite antigens and complement microscopy according to national guidance.","Malaria rapid diagnostic test ले parasite antigen पत्ता लगाउँछ र राष्ट्रिय निर्देशनअनुसार microscopy सँग प्रयोग हुन्छ।","Clinical Pathology"],
  ["Which laboratory test is used to assess blood glucose at a single point in time?","कुनै एक समयमा रगतको glucose जाँच्न कुन परीक्षण प्रयोग हुन्छ?",["Capillary or venous blood glucose","ESR","Bleeding time","Serum bilirubin"],0,"A blood glucose measurement reflects the glucose level at the time of sampling.","Blood glucose परीक्षणले नमुना लिएको समयको glucose स्तर देखाउँछ।","Clinical Pathology"],
  ["Which condition can cause elevated serum potassium?","Serum potassium बढ्ने अवस्था कुन हुन सक्छ?",["Renal impairment","Severe vomiting in every case","Iron deficiency alone","Seasonal allergy"],0,"Reduced renal potassium excretion can cause hyperkalaemia, which may produce dangerous cardiac arrhythmias.","मिर्गौलाबाट potassium उत्सर्जन घट्दा hyperkalaemia हुन सक्छ, जसले खतरनाक cardiac arrhythmia गराउन सक्छ।","Clinical Pathology"],
  ["Which action is appropriate for a patient with severe bleeding from a limb wound?","अंगको घाउबाट धेरै रक्तस्राव भएको बिरामीमा कुन कदम उपयुक्त हुन्छ?",["Apply firm direct pressure and activate emergency care","Remove pressure repeatedly to inspect","Wash without controlling bleeding","Give oral fluids before first aid"],0,"Firm direct pressure is first-line for external bleeding; severe uncontrolled bleeding needs emergency escalation and trained use of a tourniquet when indicated.","बाहिरी रक्तस्रावमा कडा प्रत्यक्ष दबाब पहिलो उपाय हो; गम्भीर नरोकिने रक्तस्रावमा आकस्मिक सहयोग र आवश्यक परे प्रशिक्षित व्यक्तिबाट tourniquet चाहिन्छ।","General Surgery"],
  ["Which injury may cause a flail chest?","Flail chest कुन चोटका कारण हुन सक्छ?",["Multiple adjacent rib fractures in more than one place","Single superficial skin cut","Simple ankle sprain","Isolated finger bruise"],0,"Flail chest occurs when a segment of chest wall becomes detached due to multiple rib fractures and can impair ventilation.","धेरै rib fracture का कारण छातीको एउटा भाग अलग्गिएर चल्दा flail chest हुन्छ र ventilation बिग्रन सक्छ।","General Surgery"],
  ["Which action is appropriate for a patient with suspected pelvic bleeding after trauma?","चोटपछि pelvic bleeding शंका भएको बिरामीमा कुन कदम उपयुक्त हुन्छ?",["Minimize movement, support circulation and arrange urgent trauma transfer","Repeatedly press and release the pelvis","Ask the patient to stand","Give a large meal"],0,"Pelvic trauma may cause life-threatening haemorrhage; minimize movement and follow trauma stabilization and transfer protocols.","Pelvic चोटले जीवन जोखिमपूर्ण रक्तस्राव गराउन सक्छ; movement कम गरी trauma stabilization र transfer protocol पालना गर्नुपर्छ।","General Surgery"],
  ["Which symptom may indicate acute urinary tract obstruction?","Acute urinary tract obstruction को संकेत कुन हुन सक्छ?",["Severe flank pain with reduced urine output","Improved urine flow","Chronic painless rash","Mild seasonal sneezing"],0,"Obstruction may cause flank pain, reduced urine output, hydronephrosis or infection and requires assessment.","Obstruction ले flank pain, पिसाब कम, hydronephrosis वा संक्रमण गराउन सक्छ; जाँच आवश्यक हुन्छ।","General Surgery"],
  ["Which action is important when caring for a patient with a suspected head injury and vomiting?","टाउकोमा चोट र बान्ता भएको बिरामीको हेरचाहमा कुन कदम महत्वपूर्ण हुन्छ?",["Protect airway, monitor consciousness and arrange urgent assessment","Give food and drink immediately","Leave the patient unattended","Encourage neck movement"],0,"Vomiting after head injury can signal intracranial injury; protect the airway, monitor neurological status and refer urgently.","टाउकोमा चोटपछि बान्ता intracranial चोटको संकेत हुन सक्छ; airway सुरक्षित राखी neurological अवस्था निगरानी र तत्काल referral गर्नुहोस्।","General Surgery"],
  ["Which sign may indicate a wound has developed a haematoma?","घाउमा haematoma बनेको संकेत कुन हुन सक्छ?",["Localized swelling and bruising from collected blood","Clear dry skin only","Improving wound size","Normal scar maturation"],0,"A haematoma is a collection of blood in tissue and may present as swelling, bruising and tenderness.","Haematoma भनेको tissue भित्र रगत जम्मा हुनु हो; सुन्निनु, नीलडाम र दुखाइ देखिन सक्छ।","General Surgery"],
  ["Which action should be taken if a patient collapses and is unresponsive with absent normal breathing?","बिरामी ढलेर प्रतिक्रिया दिँदैन र सामान्य श्वास छैन भने के गर्नुपर्छ?",["Activate emergency response, start CPR and use an AED as soon as available","Give water by mouth","Wait for spontaneous recovery","Place a pillow under the head and leave"],0,"Unresponsiveness with absent normal breathing requires immediate CPR and early AED use according to resuscitation guidance.","प्रतिक्रिया नदिनु र सामान्य श्वास नहुनुमा तुरुन्त CPR सुरु गरी उपलब्ध हुनेबित्तिकै AED प्रयोग गर्नुपर्छ।","General Surgery"]
 );


 Q.push(
  ["Which clinical feature is typical of acute rheumatic carditis?","Acute rheumatic carditis को सामान्य clinical feature कुन हो?",["New murmur or signs of cardiac inflammation after streptococcal infection","Isolated itchy scalp","Painless ankle callus","Sudden hair whitening"],0,"Rheumatic carditis may cause a new murmur, tachycardia or heart failure signs after group A streptococcal infection.","Group A streptococcal संक्रमणपछि rheumatic carditis हुँदा नयाँ murmur, छिटो नाडी वा heart failure का संकेत देखिन सक्छन्।","General Medicine"],
  ["Which symptom may indicate a severe allergic reaction involving the airway?","Airway संलग्न भएको गम्भीर allergic reaction को संकेत कुन हुन सक्छ?",["Tongue or throat swelling with difficulty breathing","Mild local itching only","A small bruise","Chronic knee pain"],0,"Tongue or throat swelling, hoarseness, wheeze or breathing difficulty may indicate anaphylaxis and need immediate treatment.","जिब्रो वा घाँटी सुन्निनु, आवाज बस्नु, wheeze वा सास गाह्रो हुनु anaphylaxis को संकेत हुन सक्छ; तत्काल उपचार चाहिन्छ।","General Medicine"],
  ["Which finding may suggest chronic venous insufficiency?","Chronic venous insufficiency को संकेत कुन हुन सक्छ?",["Ankle oedema with skin pigmentation and venous ulcers","Sudden facial droop","Acute severe eye pain","Painless jaundice"],0,"Venous hypertension can cause dependent oedema, skin pigmentation, varicose veins and venous ulcers.","Venous pressure बढ्दा खुट्टा सुन्निने, छालाको रङ परिवर्तन, varicose vein र venous ulcer हुन सक्छ।","General Medicine"],
  ["Which clinical sign may indicate acute appendicitis has progressed to perforation?","Acute appendicitis perforation भएको संकेत कुन हुन सक्छ?",["Sudden generalized worsening pain with rigid abdomen and fever","Pain fully resolving with normal examination","Isolated mild headache","Chronic itchy eyes"],0,"Perforation may lead to generalized peritonitis with worsening diffuse pain, rigidity and systemic illness.","Perforation भएपछि diffuse pain, पेट कडा र systemic illness सहित generalized peritonitis हुन सक्छ।","General Medicine"],
  ["Which symptom is a common presentation of migraine?","Migraine को सामान्य लक्षण कुन हो?",["Recurrent headache with nausea and sensitivity to light or sound","Painless ear discharge","Chronic painless ankle swelling","Burning urination only"],0,"Migraine often causes recurrent headache with nausea, photophobia or phonophobia; features vary.","Migraine मा दोहोरिने टाउको दुखाइसँग वाकवाकी, प्रकाश वा आवाज सहन नसक्ने हुन सक्छ।","General Medicine"],
  ["Which medicine is a commonly used antipyretic in children when correctly dosed?","सही dose मा बालबालिकामा प्रयोग हुने सामान्य antipyretic कुन हो?",["Paracetamol","Warfarin","Metformin","Omeprazole"],0,"Paracetamol can reduce fever and pain; paediatric dosing must be weight-based and avoid duplicate products.","Paracetamol ले ज्वरो र दुखाइ घटाउँछ; बालबालिकाको dose तौलअनुसार हुनुपर्छ र एउटै औषधि दोहोरिनु हुँदैन।","Pharmacology & Pharmacy"],
  ["Which medicine is commonly used for emergency treatment of severe hypoglycaemia when the patient cannot swallow and IV access is unavailable?","बिरामी निल्न नसक्ने र IV access नभएको गम्भीर hypoglycaemia मा आकस्मिक रूपमा कुन औषधि प्रयोग हुन सक्छ?",["Glucagon","Aspirin","Omeprazole","Cetirizine"],0,"Glucagon can raise blood glucose when oral treatment is unsafe and IV glucose is unavailable; follow local protocol.","मुखबाट उपचार सुरक्षित नभएको र IV glucose उपलब्ध नभएको अवस्थामा glucagon ले glucose बढाउन सक्छ; स्थानीय protocol पालना गर्नुहोस्।","Pharmacology & Pharmacy"],
  ["Which blood test is used to monitor warfarin therapy?","Warfarin उपचारको निगरानी गर्न कुन रक्त परीक्षण प्रयोग हुन्छ?",["INR","HbA1c","Serum amylase","ESR"],0,"INR standardizes prothrombin time and is used to monitor warfarin anticoagulation.","INR ले prothrombin time लाई standardize गर्छ र warfarin anticoagulation निगरानीमा प्रयोग हुन्छ।","Clinical Pathology"],
  ["Which urine finding may be seen in nephrotic syndrome?","Nephrotic syndrome मा पिसाबमा कुन निष्कर्ष देखिन सक्छ?",["Heavy proteinuria","Glucose absence only","Bilirubin absence","Low urine volume in every case"],0,"Nephrotic syndrome is characterized by marked protein loss in urine and low serum albumin.","Nephrotic syndrome मा पिसाबबाट धेरै protein निस्कन्छ र रगतमा albumin घट्छ।","Clinical Pathology"],
  ["Which test is used to detect pregnancy by identifying human chorionic gonadotropin?","Human chorionic gonadotropin पत्ता लगाएर गर्भावस्था जाँच्ने परीक्षण कुन हो?",["Urine or serum hCG test","Widal test","Sputum AFB test","Bleeding time"],0,"Pregnancy tests detect hCG in urine or blood after implantation.","Pregnancy test ले implantation पछि पिसाब वा रगतमा hCG पत्ता लगाउँछ।","Clinical Pathology"],
  ["Which finding on a peripheral blood smear may be seen in iron deficiency anaemia?","Iron deficiency anaemia मा peripheral blood smear मा कुन निष्कर्ष देखिन सक्छ?",["Microcytic hypochromic red cells","Macrocytic hyperchromic cells only","Sickle cells in every case","Normal red cell morphology always"],0,"Iron deficiency commonly produces small pale red blood cells (microcytic and hypochromic).","Iron deficiency मा सामान्यतया साना र फिक्का red blood cell (microcytic, hypochromic) देखिन्छन्।","Clinical Pathology"],
  ["Which finding is a warning sign of severe dengue?","गम्भीर dengue को warning sign कुन हो?",["Severe abdominal pain, persistent vomiting or mucosal bleeding","Mild fever resolving with fluids","Normal appetite only","Isolated sneezing"],0,"Severe abdominal pain, persistent vomiting, mucosal bleeding, lethargy or fluid accumulation require urgent assessment.","कडा पेट दुखाइ, लगातार बान्ता, mucosal bleeding, सुस्ती वा तरल जम्मा हुनुमा तत्काल जाँच चाहिन्छ।","General Medicine"],
  ["Which condition is suggested by sudden severe pain, pallor and absent pulse in a limb?","अंगमा अचानक कडा दुखाइ, फिक्कापन र नाडी नहुनुले कुन अवस्था संकेत गर्छ?",["Acute limb ischaemia","Simple muscle strain","Chronic dermatitis","Uncomplicated sprain"],0,"The classic signs of acute limb ischaemia include pain, pallor, pulselessness, coldness, paraesthesia and paralysis.","Acute limb ischaemia का संकेत दुखाइ, फिक्कापन, नाडी नहुनु, चिसोपन, झमझम र पक्षाघात हुन्।","General Medicine"],
  ["Which symptom is typical of benign positional vertigo?","Benign positional vertigo को सामान्य लक्षण कुन हो?",["Brief spinning sensation triggered by head position changes","Persistent painless jaundice","Chronic productive cough","Sudden abdominal rigidity"],0,"Benign paroxysmal positional vertigo causes brief episodes of vertigo triggered by specific head movements.","Benign paroxysmal positional vertigo मा टाउकोको निश्चित movement गर्दा छोटो समय घुमेजस्तो चक्कर आउँछ।","General Medicine"],
  ["Which medicine is used as a bronchodilator in acute asthma?","Acute asthma मा bronchodilator का रूपमा कुन औषधि प्रयोग हुन्छ?",["Salbutamol","Ferrous sulfate","Warfarin","Levothyroxine"],0,"Salbutamol relaxes bronchial smooth muscle through beta-2 receptor stimulation.","Salbutamol ले beta-2 receptor उत्तेजित गरी bronchial smooth muscle खुकुलो पार्छ।","Pharmacology & Pharmacy"],
  ["Which action is appropriate when a patient develops a suspected adverse reaction to an antibiotic?","Antibiotic खाएपछि adverse reaction शंका भए कुन कदम उपयुक्त हुन्छ?",["Assess severity, document and seek prescriber advice before further doses","Double the next dose","Ignore the symptoms","Share the medicine with another person"],0,"Assess the reaction, stop and seek urgent help for severe symptoms, and document/report according to local policy.","प्रतिक्रिया मूल्याङ्कन गर्नुहोस्; गम्भीर लक्षण भए औषधि रोक्दै तत्काल सहयोग लिनुहोस् र स्थानीय नीतिअनुसार अभिलेख/report गर्नुहोस्।","Pharmacology & Pharmacy"],
  ["Which action is most important before giving a medicine to a patient with a history of anaphylaxis?","Anaphylaxis को इतिहास भएको बिरामीलाई औषधि दिनुअघि सबैभन्दा महत्वपूर्ण कदम के हो?",["Check the allergy history and verify the medicine is safe","Assume all medicines are safe","Give a test dose without supervision","Ignore previous reaction"],0,"A clear allergy history and verification of the prescribed medicine are essential to prevent repeat severe reactions.","दोहोरो गम्भीर प्रतिक्रिया रोक्न allergy history र prescribed औषधिको सुरक्षा पुष्टि गर्नुपर्छ।","Pharmacology & Pharmacy"],
  ["Which injury may cause a traumatic pneumothorax?","Traumatic pneumothorax कुन चोटले गराउन सक्छ?",["Penetrating or blunt chest trauma damaging the pleura or lung","Superficial finger abrasion","Simple ankle sprain","Minor scalp itch"],0,"Chest trauma can allow air into the pleural space, causing partial or complete lung collapse.","छातीको चोटले pleural space मा हावा पस्दा फोक्सो आंशिक वा पूर्ण खुम्चिन सक्छ।","General Surgery"],
  ["Which action is appropriate for a patient with suspected internal abdominal bleeding?","पेटभित्र रक्तस्राव शंका भएको बिरामीमा कुन कदम उपयुक्त हुन्छ?",["Keep the patient at rest, monitor ABC and arrange emergency transfer","Give food and water","Apply deep abdominal pressure","Encourage walking"],0,"Suspected internal bleeding needs urgent emergency care, monitoring and rapid transfer; avoid oral intake pending assessment.","आन्तरिक रक्तस्राव शंका हुँदा आकस्मिक उपचार, निगरानी र छिटो transfer चाहिन्छ; जाँचअघि मुखबाट खाना-पानी नदिनुहोस्।","General Surgery"],
  ["Which sign after a burn indicates possible infection?","जलेको घाउमा संक्रमण भएको संकेत कुन हो?",["Increasing redness, warmth, pain or pus","Gradually improving pain","Dry intact skin","Normal healing itch only"],0,"Increasing inflammation, worsening pain, fever or purulent discharge may indicate burn wound infection.","रातोपन, तातोपन, दुखाइ बढ्नु, ज्वरो वा पीप आउनु burn wound infection को संकेत हुन सक्छ।","General Surgery"],
  ["Which action is important when caring for a patient with a suspected spinal cord injury?","Spinal cord injury शंका भएको बिरामीको हेरचाहमा कुन कदम महत्वपूर्ण हुन्छ?",["Maintain spinal alignment and avoid unnecessary movement","Flex the neck repeatedly","Ask the patient to sit and twist","Massage the spine"],0,"Spinal motion restriction and careful handling reduce the risk of secondary neurological injury.","Spinal motion restriction र सावधानीपूर्वक handling ले थप स्नायु चोटको जोखिम घटाउँछ।","General Surgery"],
  ["Which condition may cause sudden severe abdominal pain with a pulsatile abdominal mass in an older adult?","वृद्ध व्यक्तिमा पेटमा धड्किने mass र अचानक कडा पेट दुखाइ कुन अवस्थाले गराउन सक्छ?",["Abdominal aortic aneurysm","Simple constipation","Acute otitis media","Chronic dermatitis"],0,"A painful pulsatile abdominal mass may indicate an abdominal aortic aneurysm, especially if rupture occurs; emergency care is essential.","दुख्ने pulsatile abdominal mass abdominal aortic aneurysm हुन सक्छ; फुटेको अवस्थामा आकस्मिक उपचार अत्यावश्यक हुन्छ।","General Surgery"]
 );


 Q.push(["Which finding is most concerning in a patient with severe dehydration?","गम्भीर dehydration भएको बिरामीमा कुन निष्कर्ष बढी चिन्ताजनक हुन्छ?",["Altered mental status with weak rapid pulse and poor perfusion","Normal alertness and normal urine output","Moist mucosa and normal capillary refill","Normal blood pressure with no symptoms"],0,"Altered mental status, weak rapid pulse and poor perfusion suggest severe circulatory compromise and require urgent emergency management.","मानसिक अवस्था परिवर्तन, कमजोर छिटो नाडी र रक्तसञ्चार कमजोर हुनु गम्भीर circulatory compromise का संकेत हुन्; तत्काल आकस्मिक उपचार चाहिन्छ।","General Medicine"]);

 // Build both practice pools only after the full question bank is assembled.
 // Shuffle answer choices once per app load and keep the correct-answer index accurate.
 Q.forEach(q=>{
  const pairs=q[2].map((option,index)=>({option,correct:index===q[3]}));
  for(let i=pairs.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pairs[i],pairs[j]]=[pairs[j],pairs[i]];}
  q[2]=pairs.map(x=>x.option);
  q[3]=pairs.findIndex(x=>x.correct);
 });
 // Separate, non-overlapping banks. Expand each bank independently toward 250+ questions.
 const splitAt=Math.ceil(Q.length/2);
 const practiceQ=Q.slice(0,splitAt);
 const mockQ=Q.slice(splitAt);

 const state={mode:"",index:0,answers:{},timer:null,left:0,items:[]};
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
 function panel(html){root.querySelector("#haContent").innerHTML=html;root.querySelector("#haContent").scrollIntoView({behavior:"smooth",block:"start"});}
 function menu(){
  panel('<div class="ha-overview"><div class="ha-kpis"><div><b>'+notes.length+'</b><small>विस्तृत Notes</small></div><div><b>'+Q.length+'</b><small>अहिलेका MCQ</small></div><div><b>500+</b><small>लक्ष्य MCQ</small></div></div><p>MCQ बैंक चरणबद्ध रूपमा बढाइँदैछ। अहिलेको प्रश्न बैंक प्रारम्भिक संस्करण हो; ५००+ अद्वितीय र समीक्षा गरिएका प्रश्न पूरा नभएसम्म संख्या लक्ष्य मात्र हो।</p></div><div class="ha-actions"><button data-ha="notes">📚 Detailed Notes</button><button data-ha="practice">🧠 MCQ Practice</button><button data-ha="timed">⏱️ Timed Practice</button><button data-ha="mock">📝 Full Syllabus Mock</button></div><h3>NHPC Licensing Syllabus – Subject Weightage</h3><div class="ha-topic-list">'+topics.map(t=>'<article><div><b>'+t[0]+'</b><strong>'+t[1]+'</strong></div><p>'+t[2]+'</p><p class="np">'+t[3]+'</p></article>').join("")+'</div><div class="notice"><b>परीक्षा ढाँचाबारे स्पष्टता</b><p>NHPC को उपलब्ध HA licensing syllabus ले विषयगत भार १०%, २५%, २५%, १०%, २५%, ५% तोकेको छ। यसले MCQ संख्या, कुल परीक्षा समय वा negative marking निर्दिष्ट गरेको छैन। त्यसैले यहाँका timed practice र mock समय अभ्यासका लागि राखिएका हुन्, आधिकारिक परीक्षा समय होइनन्।</p></div>');
 }
 function showNotes(){panel('<h3>विस्तृत अध्ययन Notes</h3><p class="muted">English concept + नेपाली व्याख्या • Clinical safety focus</p>'+notes.map(n=>'<article class="ha-note"><h4>'+n[0]+'</h4><p>'+n[1]+'</p><p class="np">'+n[2]+'</p></article>').join("")+'<button data-ha="menu" class="smallbtn">← मुख्य मेनु</button>');}
 function start(mode){
  clearInterval(state.timer);state.mode=mode;state.index=0;state.answers={};
  const pool=mockQ;const size=mode==="timed"?Math.min(10,pool.length):Math.min(100,pool.length);state.items=pool.slice().sort(()=>Math.random()-0.5).slice(0,size);state.left=mode==="timed"?600:7200;
  renderQuestion();state.timer=setInterval(()=>{state.left--;const el=root.querySelector("#haTimer");if(el)el.textContent=fmt(state.left);if(state.left<=0)finish();},1000);
 }
 function fmt(n){return Math.floor(n/60).toString().padStart(2,"0")+":"+Math.max(0,n%60).toString().padStart(2,"0")}
 function renderQuestion(){
  const q=state.items[state.index],selected=state.answers[state.index];
  panel('<div class="ha-test-head"><span>'+(state.mode==="timed"?"TIMED PRACTICE":"FULL SYLLABUS PRACTICE MOCK")+'</span><b id="haTimer">'+fmt(state.left)+'</b></div><div class="ha-progress"><span style="width:'+((state.index+1)/state.items.length*100)+'%"></span></div><p class="muted">प्रश्न '+(state.index+1)+' / '+state.items.length+' • प्रत्येक १ अंक • जम्मा '+state.items.length+' अंक</p><article class="ha-question"><small>'+q[6]+'</small><h3>'+q[0]+'</h3><p class="np">'+q[1]+'</p><div class="ha-options">'+q[2].map((o,i)=>'<button class="'+(selected===i?"selected":"")+'" data-ha-option="'+i+'">'+String.fromCharCode(65+i)+'. '+o+'</button>').join("")+'</div></article><div class="ha-nav"><button data-ha-prev '+(state.index===0?"disabled":"")+'>← अघिल्लो</button><button data-ha-next>'+(state.index===state.items.length-1?"Submit Test":"अर्को →")+'</button></div>');
 }
 function finish(){
  clearInterval(state.timer);
  let score=0;
  const details=state.items.map((q,i)=>{const ok=state.answers[i]===q[3];if(ok)score++;return {q,selected:state.answers[i],ok}});
  const pct=Math.round(score/state.items.length*100);
  const passed=pct>=50;
  const moduleName="NHPC HA – General Medicine";
  if(window.DHPNProgress)window.DHPNProgress.recordMock(moduleName,score,state.items.length,{subject:"HA"});
  let history=[];
  try{history=JSON.parse(localStorage.getItem("dhpn-mock-history")||"[]").filter(x=>x.module===moduleName).sort((a,b)=>String(b.date).localeCompare(String(a.date))).slice(0,5)}catch(e){}
  const historyHtml=history.length?'<h3>तपाईंको पछिल्लो Mock Test Record</h3>'+history.map((h,i)=>'<article class="ha-review"><b>प्रयास '+(history.length-i)+' • '+new Date(h.date).toLocaleString()+'</b><p><strong>'+h.score+' / '+h.total+'</strong> • '+h.percent+'%</p><p class="'+(h.percent>=50?'correct':'incorrect')+'">'+(h.percent>=50?'अभ्यासमा Pass':'अझै अभ्यास आवश्यक')+'</p></article>').join(""):'';
  panel('<div class="ha-result '+(passed?'ha-pass':'ha-retry')+'"><h3>'+(passed?'🎉 बधाई छ! तपाईंले अभ्यास Mock Test पास गर्नुभयो।':'💪 निराश नहुनुहोस्! फेरि अभ्यास गरेर सुधार गर्न सक्नुहुन्छ।')+'</h3><div class="ha-score">'+score+' / '+state.items.length+'</div><b>'+pct+'% सही</b><p>सही उत्तर: '+score+' • गलत/छुटेका: '+(state.items.length-score)+'</p><p><strong>अभ्यास नतिजा: '+(passed?'PASS':'NEEDS MORE PRACTICE')+'</strong></p><p class="muted">यो App को अभ्यास benchmark (५०%) हो; NHPC को आधिकारिक pass/fail निर्णय वा उत्तीर्णाङ्क होइन।</p><button data-ha="retry">फेरि Mock Test दिनुहोस्</button><button data-ha="menu" class="smallbtn">मुख्य मेनुमा फर्कनुहोस्</button></div>'+historyHtml+'<h3>उत्तर समीक्षा</h3>'+details.map((d,i)=>'<article class="ha-review"><b>'+(i+1)+'. '+d.q[0]+'</b><p class="np">'+d.q[1]+'</p><p class="'+(d.ok?"correct":"incorrect")+'">'+(d.ok?"सही उत्तर":"गलत वा उत्तर नदिएको")+' • '+d.q[2][d.q[3]]+'</p><p>'+d.q[4]+'</p><p class="np">'+d.q[5]+'</p></article>').join(""));
 }
 function practice(){
  state.mode="practice";state.items=practiceQ;state.index=0;state.answers={};renderPracticeQ();
 }
 function renderPracticeQ(){
  const q=practiceQ[state.index],selected=state.answers[state.index],done=selected!==undefined;
  panel('<p class="muted">MCQ '+(state.index+1)+' / '+practiceQ.length+' • '+q[6]+'</p><article class="ha-question"><h3>'+q[0]+'</h3><p class="np">'+q[1]+'</p><div class="ha-options">'+q[2].map((o,i)=>'<button class="'+(selected===i?"selected":"")+'" data-ha-option="'+i+'">'+String.fromCharCode(65+i)+'. '+o+'</button>').join("")+'</div>'+(done?'<div class="ha-explain"><b>'+(selected===q[3]?"सही उत्तर!":"सही उत्तर: "+q[2][q[3]])+'</b><p>'+q[4]+'</p><p class="np">'+q[5]+'</p></div>':"")+'</article><div class="ha-nav"><button data-ha-practice-prev '+(state.index===0?"disabled":"")+'>← अघिल्लो</button><button data-ha-practice-next>'+(state.index===practiceQ.length-1?"समाप्त":"अर्को →")+'</button></div><button data-ha="menu" class="smallbtn">मुख्य मेनु</button>');
 }
 root.addEventListener("click",e=>{
  const b=e.target.closest("button");if(!b)return;
  if(b.dataset.ha){const a=b.dataset.ha;if(a==="menu")menu();if(a==="notes")showNotes();if(a==="practice")practice();if(a==="timed")start("timed");if(a==="mock")start("mock");if(a==="retry")start("mock");return;}
  if(b.dataset.haOption!==undefined){const idx=Number(b.dataset.haOption);if(state.mode==="practice"){state.answers[state.index]=idx;renderPracticeQ();if(window.DHPNProgress)window.DHPNProgress.recordMCQ("NHPC HA – General Medicine",[Q[state.index][0],Q[state.index][1],Q[state.index][2],Q[state.index][3],Q[state.index][4],Q[state.index][5]],idx);}else{state.answers[state.index]=idx;renderQuestion();}return;}
  if(b.dataset.haNext!==undefined){if(state.index===state.items.length-1)finish();else{state.index++;renderQuestion();}return;}
  if(b.dataset.haPrev!==undefined){state.index=Math.max(0,state.index-1);renderQuestion();return;}
  if(b.dataset.haPracticeNext!==undefined){if(state.index===practiceQ.length-1){menu();return;}state.index++;renderPracticeQ();return;}
  if(b.dataset.haPracticePrev!==undefined){state.index=Math.max(0,state.index-1);renderPracticeQ();}
 });
 menu();
})();